BEGIN;

INSERT INTO public.aircraft (
  id, name, manufacturer, category, description, recognition_hints, first_flight, max_speed_kmh, length_m, wingspan_m, height_m, range_km, ceiling_m, service_entry, retirement, country_of_origin, engines, units_built, rarity, image_url, image_author, image_license, image_license_url, image_source_url, wikidata_id, enwiki_title, aliases, wikipedia_url, sources, verified
) VALUES
  -- Airbus A320 (Q6475)
  ('a320', 'Airbus A320', 'Airbus Commercial Aircraft', 'ligne', 'La famille Airbus A320 regroupe quatre types d''avions de ligne moyen-courriers monocouloirs, conçus et fabriqués par Airbus depuis 1986, déclinés en plusieurs variantes. Le premier appareil construit est l''A320, qui donne son nom à la famille, suivi d''une version rallongée d''environ 18,5 %, l''A321, et de deux versions raccourcies, les A319 et A318. L''A320 et l''A321 P2F convertis sont en version fret et tous sauf l''A318 se déclinent en version NEO (New Engine Option), plus performante.', 'Monocouloir court/moyen-courrier, moteurs sous les ailes, nez arrondi caractéristique', '1987-02-22', NULL, 31.45, 34.1, 12.56, NULL, 12130, '1988-03-01', NULL, NULL, 'CFM International CFM56 / IAE V2500', 9693, 2, 'https://upload.wikimedia.org/wikipedia/commons/c/c1/Airbus_A320-214%2C_Airbus_Industrie_JP7617615.jpg', 'Pedro Aragão', 'CC BY-SA 3.0', 'https://creativecommons.org/licenses/by-sa/3.0', 'https://commons.wikimedia.org/wiki/File:Airbus_A320-214,_Airbus_Industrie_JP7617615.jpg', 'Q6475', 'Airbus A320 family', ARRAY['airbus a320 family', 'airbus a320', 'airbus a318/319/320/321/acj'], 'https://fr.wikipedia.org/wiki/Airbus_A320', '{"units_built":["https://www.airbus.com/aircraft/market/orders-deliveries.html"]}'::jsonb, true),
  -- Airbus A321 (Q3278675)
  ('a321', 'Airbus A321', 'Airbus Commercial Aircraft', 'ligne', 'L''Airbus A321 est une version allongée de l''Airbus A320, produite par Airbus Commercial Aircraft. Cet avion biréacteur monocouloir est le plus grand et long de la gamme A320. Son vol inaugural a eu lieu en mars 1993, puis il a été exploité par Lufthansa l''année suivante.', 'Version allongée de l''A320, fuselage plus long, même configuration moteurs', '1993-03-11', NULL, NULL, NULL, NULL, NULL, NULL, '1994-01-01', NULL, 'Allemagne / France', NULL, NULL, 3, 'https://thumb.wikimedia.org/wikipedia/commons/thumb/1/18/Lufthansa.a321-100.d-aire.arp.jpg/1280px-Lufthansa.a321-100.d-aire.arp.jpg', 'Arpingstone', 'Public domain', NULL, 'https://commons.wikimedia.org/wiki/File:Lufthansa.a321-100.d-aire.arp.jpg', 'Q3278675', 'Airbus A321', ARRAY['airbus a321', 'a321'], 'https://fr.wikipedia.org/wiki/Airbus_A321', '{}'::jsonb, true),
  -- Boeing 737 (Q6387)
  ('b737', 'Boeing 737', 'Boeing Commercial Airplanes / Boeing', 'ligne', 'Le Boeing 737 est un avion de ligne court à moyen-courrier biréacteur à fuselage étroit développé et construit depuis 1967 par la Boeing Commercial Airplanes. Initialement développé comme un dérivé des 707 et 727, plus petit et plus abordable, le 737 se décline en une famille de dix modèles pouvant emporter de 85 à 215 passagers. Depuis 2004, le 737 est le seul avion de ligne à fuselage étroit de Boeing en production.', 'Monocouloir court/moyen-courrier, moteurs aplatis sous les ailes (nacelles ovales)', '1967-04-09', NULL, NULL, 34.3, 12.5, NULL, 11300, '1968-02-10', NULL, 'États-Unis', 'Pratt & Whitney JT8D / CFM International CFM56', 10510, 1, 'https://thumb.wikimedia.org/wikipedia/commons/thumb/d/d9/Aviogenex_b737-200_yu-anp_arp.jpg/1280px-Aviogenex_b737-200_yu-anp_arp.jpg', 'Photographed by Adrian Pingstone and released to the public domain. Public domainPublic domainfalsefalse This work has been released into the public domain by its author, Arpingstone. This applies worldwide. In some countries this may not be legally possible; if so: Arpingstone grants anyone the right to use this work for any purpose, without any conditions, unless such conditions are required by law.', 'Public domain', NULL, 'https://commons.wikimedia.org/wiki/File:Aviogenex_b737-200_yu-anp_arp.jpg', 'Q6387', 'Boeing 737', ARRAY['boeing 737', '737', 'b737', 'b-737'], 'https://fr.wikipedia.org/wiki/Boeing_737', '{"units_built":["http://www.boeing.com/commercial/#/orders-deliveries"]}'::jsonb, true),
  -- Airbus A380 (Q5830)
  ('a380', 'Airbus A380', 'Airbus Commercial Aircraft', 'ligne', 'L''Airbus A380 est un avion de ligne civil très gros-porteur long-courrier quadriréacteur à double pont, produit par Airbus de 2004 à 2021. L''A380 est, en 2026, le plus gros avion civil de transport de passagers en service et le quatrième plus gros avion de l''histoire de l''aéronautique.', 'Très gros porteur double-pont, 4 moteurs, fuselage très large, double pont visible', '2005-04-27', NULL, 72.72, 79.8, 24.1, 15200, 13106, '2007-10-25', NULL, 'France', 'Rolls-Royce Trent 700 / Engine Alliance GP7200', 251, 4, 'https://thumb.wikimedia.org/wikipedia/commons/thumb/0/09/A6-EDY_A380_Emirates_31_jan_2013_jfk_%288442269364%29_%28cropped%29.jpg/1280px-A6-EDY_A380_Emirates_31_jan_2013_jfk_%288442269364%29_%28cropped%29.jpg', 'Maarten Visser from Capelle aan den IJssel, Nederland', 'CC BY-SA 2.0', 'https://creativecommons.org/licenses/by-sa/2.0', 'https://commons.wikimedia.org/wiki/File:A6-EDY_A380_Emirates_31_jan_2013_jfk_(8442269364)_(cropped).jpg', 'Q5830', 'Airbus A380', ARRAY['airbus a380', 'a380neo', 'a380plus', 'a380'], 'https://fr.wikipedia.org/wiki/Airbus_A380', '{"first_flight":["https://www.airbus.com/en/newsroom/press-releases/2005-04-a380-worlds-largest-commercial-aircraft-successfully-takes-to-the"]}'::jsonb, true),
  -- Boeing 747 (Q179)
  ('b747', 'Boeing 747', 'Boeing Commercial Airplanes', 'ligne', 'Le Boeing 747 est un avion de ligne à réaction américain à fuselage large construit entre 1968 et 2022 par Boeing, souvent désigné par son qualificatif, Jumbo Jet ou Reine des Cieux. Sa « bosse » caractéristique à l''avant du fuselage fait du 747 un appareil particulièrement reconnaissable. Le 747 est également le premier avion de ligne à fuselage large.', 'Gros porteur, 4 moteurs, bosse caractéristique sur l''avant (double pont partiel)', '1969-02-09', NULL, NULL, 59.64, NULL, NULL, NULL, '1970-01-22', NULL, 'États-Unis', NULL, 1574, 3, 'https://thumb.wikimedia.org/wikipedia/commons/thumb/b/b8/B-747_Iberia.jpg/1280px-B-747_Iberia.jpg', 'Iberia Airlines', 'CC BY 2.0', 'https://creativecommons.org/licenses/by/2.0', 'https://commons.wikimedia.org/wiki/File:B-747_Iberia.jpg', 'Q179', 'Boeing 747', ARRAY['boeing 747', 'jumbo jet', 'queen of the skies'], 'https://fr.wikipedia.org/wiki/Boeing_747', '{"first_flight":["http://www.boeing.com/news/releases/2004/q1/nr_040209g.html","http://www.time.com/time/magazine/article/0,9171,839015,00.html"],"wingspan_m":["https://www.wikidata.org/wiki/Q29042798"],"units_built":["https://www.cnbc.com/2022/12/06/boeing-747-production-is-ending-with-shift-to-twin-engine-jets.html"]}'::jsonb, true),
  -- Concorde (Q6505)
  ('concorde', 'Concorde', 'Sud-Aviation / British Aircraft Corporation', 'ligne', 'Le Concorde est un avion supersonique construit entre 1967 et 1979. Il s''agit d''un avion de ligne conçu conjointement par Sud-Aviation (devenue par la suite Aérospatiale puis Airbus) et British Aircraft Corporation (devenue ensuite British Aerospace). Il est exploité entre 1976 et 2003 par Air France et British Airways. Son premier vol a eu lieu en 1969. Sa vitesse de croisière est de Mach 2,04, soit environ 2 172 km/h, à une altitude variant de 16 000 à 18 000 m.', 'Supersonique civil, ailes delta ogives, nez en visite articulé, 4 moteurs Olympus sous les ailes', '1969-03-02', NULL, 61.66, 25.56, 12.2, 6580, 18300, '1976-01-21', '2003-11-26', NULL, 'Rolls-Royce/Snecma Olympus 593', 20, 5, 'https://upload.wikimedia.org/wikipedia/commons/e/eb/British_Airways_Concorde_G-BOAC_03.jpg', 'Eduard Marmet', 'CC BY-SA 3.0', 'https://creativecommons.org/licenses/by-sa/3.0', 'https://commons.wikimedia.org/wiki/File:British_Airways_Concorde_G-BOAC_03.jpg', 'Q6505', 'Concorde', ARRAY['concorde', 'aérospatiale-bac concorde', 'aerospatiale-bac concorde', 'sud-bac concorde', 'aerospatiale/bac concorde', 'aerospatiale/bae concorde'], 'https://fr.wikipedia.org/wiki/Concorde_(avion)', '{"first_flight":["https://www.wikidata.org/wiki/Q116756292"],"length_m":["https://www.wikidata.org/wiki/Q29042798"],"wingspan_m":["https://www.wikidata.org/wiki/Q29042798","https://www.wikidata.org/wiki/Q116756292"],"range_km":["https://www.wikidata.org/wiki/Q116756292"],"units_built":["https://www.baesystems.com/en/heritage/bac-concorde"],"service_entry":["https://www.britishairways.com/en-gb/information/about-ba/history-and-heritage/celebrating-concorde"],"retirement":["http://news.bbc.co.uk/2/hi/uk_news/england/bristol/somerset/3238674.stm"]}'::jsonb, true),
  -- Dassault Rafale (Q190973)
  ('rafale', 'Dassault Rafale', 'Dassault Aviation', 'militaire', 'Le Rafale de Dassault Aviation est un avion de combat multirôle — qualifié d''« omnirôle » par son constructeur — développé conjointement pour la Marine nationale et l''Armée de l''air françaises. Livré à partir du 18 mai 2001, il est entré en service en 2002 dans la Marine nationale et en 2007 dans l''Armée de l''air.', 'Chasseur français bimoteur, delta avec canards, entrée d''air sous le nez, dérive unique', '1986-07-04', NULL, 15.27, 10.86, 5.34, 1850, 16750, '2002-01-01', NULL, 'France', 'Snecma M88', 313, 4, 'https://thumb.wikimedia.org/wikipedia/commons/thumb/6/64/Rafale_-_RIAT_2009_%283751416421%29.jpg/1280px-Rafale_-_RIAT_2009_%283751416421%29.jpg', 'Tim Felce (Airwolfhound)', 'CC BY-SA 2.0', 'https://creativecommons.org/licenses/by-sa/2.0', 'https://commons.wikimedia.org/wiki/File:Rafale_-_RIAT_2009_(3751416421).jpg', 'Q190973', 'Dassault Rafale', ARRAY['dassault rafale', 'dassault breguet rafale', 'dassault rafale m', 'rafale', 'rafale ag1'], 'https://fr.wikipedia.org/wiki/Dassault_Rafale', '{"service_entry":["https://www.defense.gouv.fr/marine/equipements/aeronefs/rafale-marine","http://questions.assemblee-nationale.fr/q14/14-83QE.htm","https://www.meretmarine.com/fr/content/il-y-vingt-ans-dassault-aviation-faisait-voler-le-rafale"]}'::jsonb, true),
  -- Dassault Mirage 2000 (Q200038)
  ('mirage-2000', 'Dassault Mirage 2000', 'Dassault Aviation', 'militaire', 'Le Mirage 2000 est un avion de chasse conçu par la société française Dassault Aviation, à la fin des années 1970. Bien que la formule à ailes delta fasse penser au Mirage III des années 1960 et que le Mirage 2000 soit de taille comparable, il s''agit en fait d''un avion entièrement nouveau. Il dispose d''une surface alaire plus importante, naturellement instable afin d''améliorer sa manœuvrabilité et il est équipé de commandes de vol électriques.', 'Chasseur français monomoteur, aile delta pure sans canards, dérive unique, nez plus fin', '1978-03-10', NULL, 14.36, 9, 5.3, NULL, 17100, '1984-07-02', NULL, NULL, NULL, 601, 3, 'https://thumb.wikimedia.org/wikipedia/commons/thumb/6/69/French_Mirage_2000_finishes_refueling_from_KC-10A_2009-12-06_mod1.jpg/1280px-French_Mirage_2000_finishes_refueling_from_KC-10A_2009-12-06_mod1.jpg', 'Staff Sgt. Michael B. Keller, USAF', 'Public domain', NULL, 'https://commons.wikimedia.org/wiki/File:French_Mirage_2000_finishes_refueling_from_KC-10A_2009-12-06_mod1.jpg', 'Q200038', 'Dassault Mirage 2000', ARRAY['dassault mirage 2000', 'm2000', 'dassault-breguet mirage 2000', 'mirage 2000', 'mirage 2000d', 'mirage 2000 d'], 'https://fr.wikipedia.org/wiki/Dassault_Mirage_2000', '{"wingspan_m":["https://www.wikidata.org/wiki/Q29042798"]}'::jsonb, true),
  -- General Dynamics F-16 Fighting Falcon (Q100026)
  ('f16', 'General Dynamics F-16 Fighting Falcon', 'General Dynamics / Lockheed Martin', 'militaire', 'Le F-16 Fighting Falcon est un avion de combat multirôle développé par General Dynamics (aujourd''hui Lockheed Martin) pour les États-Unis dans les années 1970. Commandé par plus de vingt pays différents, construit sous licence par un groupe de quatre pays de l''OTAN en Belgique et aux Pays-Bas, ainsi qu''en Turquie et en Corée du Sud, le F-16 est l''avion de chasse le plus utilisé dans le monde avec 2 145 appareils en service en 2023, soit 15 % de la flotte mondiale, selon Flight International.', 'Chasseur monomoteur américain, entrée d''air ventrale, aile delta/trapézoïdale, dérive unique haute', '1974-01-20', NULL, 15.06, 9.96, 4.88, NULL, NULL, '1979-01-01', NULL, 'États-Unis', 'Pratt & Whitney F100', 4604, 2, 'https://thumb.wikimedia.org/wikipedia/commons/thumb/d/d5/Defense.gov_News_Photo_070720-F-5502S-003.jpg/1280px-Defense.gov_News_Photo_070720-F-5502S-003.jpg', 'Capt. Tana R.H. Stevenson, U.S. Air Force', 'Public domain', NULL, 'https://commons.wikimedia.org/wiki/File:Defense.gov_News_Photo_070720-F-5502S-003.jpg', 'Q100026', 'General Dynamics F-16 Fighting Falcon', ARRAY['general dynamics f-16 fighting falcon', 'general dynamics fighting falcon', 'lockheed martin f-16 fighting falcon', 'fighting falcon', 'f-16', 'lockheed f-16 fighting falcon', 'viper', 'f-16 fighting falcon'], 'https://fr.wikipedia.org/wiki/General_Dynamics_F-16_Fighting_Falcon', '{"service_entry":["http://f-16.net/aircraft-database/F-16/airframe-profile/11/"]}'::jsonb, true),
  -- F/A-18 Hornet (Q46397)
  ('fa18', 'F/A-18 Hornet', 'McDonnell Douglas / Boeing Integrated Defense Systems', 'militaire', 'Le McDonnell Douglas F/A-18 Hornet est un avion de combat multirôle américain, initialement destiné à être embarqué à bord de porte-avions de l''US Navy. Mis en service au début des années 1980, il a été construit entre 1974 et 2000 à 1 480 exemplaires et exporté dans une dizaine de pays. Il est le deuxième avion de combat le plus utilisé dans le monde en 2012 avec, selon une estimation, 1 005 appareils en activité, soit 6 % de la flotte mondiale d''avions de combat.', 'Chasseur bimoteur américain, double dérive, entrées d''air latérales, aile trapézoïdale', '1978-11-18', NULL, 17.1, NULL, 4.9, 531, 15250, '1983-01-07', NULL, NULL, 'General Electric F404', 1480, 3, 'https://thumb.wikimedia.org/wikipedia/commons/thumb/0/0e/F-18_overflying_water_-_%28USN%2C_USDoD%29.jpg/1280px-F-18_overflying_water_-_%28USN%2C_USDoD%29.jpg', 'DN-SC-04-08946', 'Public domain', NULL, 'https://commons.wikimedia.org/wiki/File:F-18_overflying_water_-_(USN,_USDoD).jpg', 'Q46397', 'McDonnell Douglas F/A-18 Hornet', ARRAY['mcdonnell douglas f/a-18 hornet', 'f/a-18 hornet', 'boeing f/a-18', 'mcdonnell douglas f/a-18', 'hornet', 'f-18', 'f/a-18'], 'https://fr.wikipedia.org/wiki/McDonnell_Douglas_F/A-18_Hornet', '{}'::jsonb, true),
  -- Supermarine Spitfire (Q29190)
  ('spitfire', 'Supermarine Spitfire', 'Supermarine', 'collection', 'Le Supermarine Spitfire est l''un des chasseurs monoplaces les plus utilisés par la RAF et par les Alliés pendant la Seconde Guerre mondiale. Il a servi pendant toute la durée de la Seconde Guerre mondiale et, avec toutes ses variantes, a été de tous les combats. Il donna lieu à une diversification et à une multiplicité de versions jamais atteinte auparavant dans l''histoire de l''aviation. Les ailes elliptiques du Spitfire lui ont donné une apparence très reconnaissable.', 'Chasseur WWII britannique, aile elliptique très distinctive, moteur Merlin en étoile, hélice', '1936-03-05', 595, NULL, NULL, NULL, NULL, NULL, '1938-08-04', '1961-01-01', 'Royaume-Uni', NULL, 20351, 1, 'https://upload.wikimedia.org/wikipedia/commons/3/31/Ray_Flying_Legends_2005-1.jpg', 'The original uploader was Bryan Fury75 at French Wikipedia.', 'CC BY-SA 3.0', 'http://creativecommons.org/licenses/by-sa/3.0/', 'https://commons.wikimedia.org/wiki/File:Ray_Flying_Legends_2005-1.jpg', 'Q29190', 'Supermarine Spitfire', ARRAY['supermarine spitfire', 'type 300 spitfire', 'spitfire fighter', 'supermarine 300', 'supermarine type 300'], 'https://fr.wikipedia.org/wiki/Supermarine_Spitfire', '{}'::jsonb, true),
  -- Hawker Hurricane (Q194251)
  ('hurricane', 'Hawker Hurricane', 'Hawker Aircraft', 'collection', 'Le Hawker Hurricane fut le premier chasseur monoplan de la Royal Air Force. Il s''illustra en particulier lors de la bataille d''Angleterre, durant la Seconde Guerre mondiale. Un total de 14 583 exemplaires furent construits, utilisés par plusieurs forces aériennes alliées.', 'Chasseur WWII britannique, aile droite arrondie (moins elliptique que le Spitfire), fuselage plus trapu', '1935-11-06', NULL, NULL, NULL, NULL, NULL, NULL, '1937-01-01', NULL, 'Royaume-Uni', 'Rolls-Royce Merlin', 14532, 1, 'https://thumb.wikimedia.org/wikipedia/commons/thumb/8/84/Hawker_Hurricane_I_%27R4118_UP-W%27_%28G-HUPW%29_%2841455530471%29.jpg/1280px-Hawker_Hurricane_I_%27R4118_UP-W%27_%28G-HUPW%29_%2841455530471%29.jpg', 'Alan Wilson from Stilton, Peterborough, Cambs, UK', 'CC BY-SA 2.0', 'https://creativecommons.org/licenses/by-sa/2.0', 'https://commons.wikimedia.org/wiki/File:Hawker_Hurricane_I_%27R4118_UP-W%27_(G-HUPW)_(41455530471).jpg', 'Q194251', 'Hawker Hurricane', ARRAY['hawker hurricane', 'hurricane', 'hurribomber'], 'https://fr.wikipedia.org/wiki/Hawker_Hurricane', '{}'::jsonb, true),
  -- Douglas DC-3 (Q190211)
  ('dc3', 'Douglas DC-3', 'Douglas', 'collection', 'Le Douglas DC-3 est un avion de transport bimoteur à hélices, produit par la compagnie américaine Douglas Aircraft entre 1936 et 1945. Sa vitesse et son rayon d''action révolutionnèrent le transport aérien. Conçu à l''origine comme une évolution du Douglas DC-2 permettant le transport nocturne et confortable de passagers civils, le DC-3 est rapidement devenu un outil indispensable aux armées alliées durant la Seconde Guerre mondiale.', 'Transport classique années 1930-40, deux moteurs en étoile, aile basse, train fixe ou rétractable', '1935-12-17', 372, 19.63, 28.96, NULL, 3420, 7346, '1936-01-01', NULL, 'États-Unis', 'Twin Wasp S1C3G', 607, 3, 'https://upload.wikimedia.org/wikipedia/commons/d/df/Douglas_DC-3%2C_SE-CFP.jpg', 'Towpilot', 'CC BY-SA 3.0', 'http://creativecommons.org/licenses/by-sa/3.0/', 'https://commons.wikimedia.org/wiki/File:Douglas_DC-3,_SE-CFP.jpg', 'Q190211', 'Douglas DC-3', ARRAY['douglas dc-3', 'gooney bird', 'douglas dc-3 dakota', 'dakota dc-3', 'dc-3', 'dc3', 'douglas dc3', 'douglas c-49'], 'https://fr.wikipedia.org/wiki/Douglas_DC-3', '{"max_speed_kmh":["https://www.wikidata.org/wiki/Q15058267"],"length_m":["https://www.wikidata.org/wiki/Q29042798"],"wingspan_m":["https://www.wikidata.org/wiki/Q29042798"],"range_km":["https://www.wikidata.org/wiki/Q15058267"],"ceiling_m":["https://www.wikidata.org/wiki/Q15058267"]}'::jsonb, true),
  -- North American P-51 Mustang (Q192075)
  ('p51', 'North American P-51 Mustang', 'North American Aviation', 'collection', 'Le P-51 Mustang est un avion de chasse américain conçu par North American Aviation. Utilisé lors de la Seconde Guerre mondiale, il est au départ développé pendant l''année 1940 pour répondre au besoin urgent de chasseurs supplémentaires de la Royal Air Force.', 'Chasseur WWII américain, aile trapézoïdale, entrée d''air ventrale caractéristique (radiateur), hélice', '1940-10-26', NULL, NULL, 11.28, 4.08, NULL, 12800, '1942-01-01', '1984-01-01', 'États-Unis', NULL, 16974, 1, 'https://thumb.wikimedia.org/wikipedia/commons/thumb/e/e3/P51_Mustang_-_CHino_Airshow_2014_%2814349568311%29.jpg/1280px-P51_Mustang_-_CHino_Airshow_2014_%2814349568311%29.jpg', 'Airwolfhound from Hertfordshire, UK', 'CC BY-SA 2.0', 'https://creativecommons.org/licenses/by-sa/2.0', 'https://commons.wikimedia.org/wiki/File:P51_Mustang_-_CHino_Airshow_2014_(14349568311).jpg', 'Q192075', 'North American P-51 Mustang', ARRAY['north american p-51 mustang', 'p-51', 'mustang fighter', 'mustang', 'north american mustang', 'f-51 mustang', 'mustang aircraft', 'north american mustang aircraft', 'pursuit design 51', 'p-51 mustang', 'north american xp-78', 'p51', 'f-51'], 'https://fr.wikipedia.org/wiki/North_American_P-51_Mustang', '{}'::jsonb, true),
  -- Airbus A350 (Q6484)
  ('a350', 'Airbus A350', 'Airbus Commercial Aircraft', 'ligne', 'L''Airbus A350 est un avion de ligne long-courrier et gros porteur construit par l''avionneur européen Airbus depuis 2012. Initialement conçu comme un modèle dérivé de l''A330, il est décidé à la mi-juillet 2006 d''en revoir le concept à la suite des réactions des compagnies aériennes et de le munir d''un fuselage plus large, à la fois par rapport aux A330 et A340, mais surtout face à son principal concurrent, à cette époque, le Boeing 787.', 'Gros porteur long-courrier, 2 moteurs, fuselage composite sombre, bouts d''ailes courbés vers le haut', '2013-06-14', NULL, NULL, 64.75, NULL, NULL, NULL, '2015-01-15', NULL, 'Allemagne / France', 'Rolls-Royce Trent XWB', 295, 4, 'https://thumb.wikimedia.org/wikipedia/commons/thumb/f/f2/Virgin_Atlantic_Airbus_A350-1041XWB_G-VLUX_%28Red_Velvet%29_approaching_JFK_Airport.jpg/1280px-Virgin_Atlantic_Airbus_A350-1041XWB_G-VLUX_%28Red_Velvet%29_approaching_JFK_Airport.jpg', 'Adam Moreira (AEMoreira042281)', 'CC BY-SA 4.0', 'https://creativecommons.org/licenses/by-sa/4.0', 'https://commons.wikimedia.org/wiki/File:Virgin_Atlantic_Airbus_A350-1041XWB_G-VLUX_(Red_Velvet)_approaching_JFK_Airport.jpg', 'Q6484', 'Airbus A350', ARRAY['airbus a350', 'a350'], 'https://fr.wikipedia.org/wiki/Airbus_A350', '{"service_entry":["https://www.diariodesevilla.es/economia/Airbus-entrega-Qatar-Airways-A350_0_873812945.html"]}'::jsonb, true),
  -- Lockheed Martin F-22 Raptor (Q133324)
  ('lockheed-martin-f-22-raptor', 'Lockheed Martin F-22 Raptor', 'Lockheed Martin Aeronautics / Boeing Integrated Defense Systems', 'militaire', 'Le Lockheed Martin F-22 Raptor est un avion de chasse furtif développé par les États-Unis dont le développement commence à la fin des années 1980 afin de succéder aux F-15 de l''US Air Force. Initialement conçu pour les combats aériens, il est également capable d’assurer des missions de soutien militaire au sol, d''attaque électronique ou encore de renseignement d’origine électromagnétique.', NULL, '1997-09-07', NULL, 18.92, 13.56, 5.08, 3000, 15000, '2005-12-15', NULL, 'États-Unis', 'Pratt & Whitney F119', 195, 4, 'https://thumb.wikimedia.org/wikipedia/commons/thumb/4/46/192d_FW_F-22_Raptor.jpg/1280px-192d_FW_F-22_Raptor.jpg', '(U.S. Marine Corps photo by Lance Cpl. Dan T. Le/Released)', 'Public domain', NULL, 'https://commons.wikimedia.org/wiki/File:192d_FW_F-22_Raptor.jpg', 'Q133324', 'Lockheed Martin F-22 Raptor', ARRAY['lockheed martin f-22 raptor', 'raptor', 'f-22', 'f-22 raptor', 'f/a-22', 'lockheed f-22 raptor', 'lockheed f/a-22 raptor', 'lockheed-martin f-22 raptor', 'f 22', 'f22'], 'https://fr.wikipedia.org/wiki/Lockheed_Martin_F-22_Raptor', '{"first_flight":["http://www.f22-raptor.com/about/chronology.html","http://lockheedmartin.com/us/100years/stories/f-22.html"],"length_m":["https://www.af.mil/About-Us/Fact-Sheets/Display/Article/104506/f-22-raptor/"],"wingspan_m":["https://www.af.mil/About-Us/Fact-Sheets/Display/Article/104506/f-22-raptor/"],"height_m":["https://www.af.mil/About-Us/Fact-Sheets/Display/Article/104506/f-22-raptor/"],"range_km":["https://www.af.mil/About-Us/Fact-Sheets/Display/Article/104506/f-22-raptor/"],"ceiling_m":["https://www.af.mil/About-Us/Fact-Sheets/Display/Article/104506/f-22-raptor/"],"units_built":["http://www.combataircraft.net/view_article.asp?id=4994"],"service_entry":["http://www.af.mil/News/ArticleDisplay/tabid/223/Article/132463/f-22a-raptor-goes-operational.aspx"]}'::jsonb, true),
  -- Boeing 777 (Q6425)
  ('boeing-777', 'Boeing 777', 'Boeing Commercial Airplanes', 'ligne', 'Le Boeing 777 ou B777, parfois surnommé triple sept dans le milieu aérien, est un avion de ligne gros porteur, long courrier et biréacteur construit par la société Boeing depuis 1993. Entré en service en 1995, il est le plus grand biréacteur au monde, avec une capacité de 300 à 550 (haute densité monoclasse) passagers et une distance franchissable variant de 9 695 à 17 370 km selon les modèles.', NULL, '1994-06-12', NULL, NULL, NULL, NULL, NULL, NULL, '1995-06-07', NULL, 'États-Unis', NULL, 1662, 3, 'https://thumb.wikimedia.org/wikipedia/commons/thumb/0/07/United_Airlines_777_N797UA_LAX.jpg/1280px-United_Airlines_777_N797UA_LAX.jpg', NULL, 'CC BY-SA 2.0', 'https://creativecommons.org/licenses/by-sa/2.0', 'https://commons.wikimedia.org/wiki/File:United_Airlines_777_N797UA_LAX.jpg', 'Q6425', 'Boeing 777', ARRAY['boeing 777', 'b777', '777', 'boeing triple seven', 'triple seven', 'b-777', 'triple sept'], 'https://fr.wikipedia.org/wiki/Boeing_777', '{"units_built":["http://www.boeing.com/commercial/#/orders-deliveries"]}'::jsonb, true),
  -- Lockheed Martin F-35 Lightning II (Q29261)
  ('lockheed-martin-f-35-lightning-ii', 'Lockheed Martin F-35 Lightning II', 'Lockheed Martin Aeronautics / Lockheed Martin', 'militaire', 'Le F-35 Lightning II (également connu sous le nom générique de F-35 Joint strike fighter ou F-35 JSF) est un avion militaire monoplace, monomoteur, furtif, de cinquième génération, multirôle, conçu pour l''attaque au sol et les missions de supériorité aérienne. Il est développé depuis 1996 par le constructeur Lockheed Martin, avec comme principaux partenaires Northrop Grumman et BAE Systems sur une définition du Pentagone.', NULL, '2006-12-15', NULL, 15.54, 10.67, 4.38, NULL, NULL, '2015-07-31', NULL, 'États-Unis', 'Pratt & Whitney F135', 610, 3, 'https://thumb.wikimedia.org/wikipedia/commons/thumb/5/56/F-35_at_Edwards.jpg/1280px-F-35_at_Edwards.jpg', 'U.S. Air Force photo/Senior Airman Julius Delos Reyes', 'Public domain', NULL, 'https://commons.wikimedia.org/wiki/File:F-35_at_Edwards.jpg', 'Q29261', 'Lockheed Martin F-35 Lightning II', ARRAY['lockheed martin f-35 lightning ii', 'lockheed martin lightning ii', 'fighter design 35', 'lockheed f-35 joint strike fighter', 'f-35', 'lockheed martin f-35', 'f35', 'f-35 jsf', 'f-35 joint strike fighter', 'f-35 lightning ii', 'joint strike fighter', 'lightning ii', 'jsf'], 'https://fr.wikipedia.org/wiki/Lockheed_Martin_F-35_Lightning_II', '{"max_speed_kmh":["https://www.af.mil/About-Us/Fact-Sheets/Display/Article/478441/f-35a-lightning-ii/"],"length_m":["https://www.af.mil/About-Us/Fact-Sheets/Display/Article/478441/f-35a-lightning-ii/"],"wingspan_m":["https://www.af.mil/About-Us/Fact-Sheets/Display/Article/478441/f-35a-lightning-ii/"],"height_m":["https://www.af.mil/About-Us/Fact-Sheets/Display/Article/478441/f-35a-lightning-ii/"],"units_built":["https://f35.com/assets/uploads/downloads/F-35_Fast_Facts_-_January_2021.pdf"],"service_entry":["http://www.lockheedmartin.com/us/aeronautics/media-center/f-35a-takes-flight-at-eglin.html","https://www.f35.com/news/detail/u.s.-marine-corps-declares-the-f-35b-operational","https://lenta.ru/articles/2015/08/18/f35/","https://news.usni.org/2016/08/02/air-force-declares-ioc-f-35a"]}'::jsonb, true),
  -- Boeing 787 (Q6428)
  ('boeing-787-dreamliner', 'Boeing 787', 'Boeing Commercial Airplanes', 'ligne', 'Le Boeing 787, également connu par son surnom Dreamliner, est un avion long-courrier, produit par la société Boeing depuis 2007. Officiellement lancé le 26 avril 2004 pour une mise en service prévue en mai 2008, il accumule par la suite les retards, pour le premier vol et d''autres étapes importantes. Il effectue finalement son premier vol le 15 décembre 2009, puis est certifié le 26 août 2011.', NULL, '2009-12-15', NULL, 56.7, 52, 16.9, NULL, 13100, '2011-10-26', NULL, 'États-Unis', 'General Electric GEnx / Rolls-Royce Trent 1000', 1005, 3, 'https://thumb.wikimedia.org/wikipedia/commons/thumb/f/ff/All_Nippon_Airways%2C_Boeing_787-8_JA828A_NRT_%2823661189691%29.jpg/1280px-All_Nippon_Airways%2C_Boeing_787-8_JA828A_NRT_%2823661189691%29.jpg', 'Masakatsu Ukon', 'CC BY-SA 2.0', 'https://creativecommons.org/licenses/by-sa/2.0', 'https://commons.wikimedia.org/wiki/File:All_Nippon_Airways,_Boeing_787-8_JA828A_NRT_(23661189691).jpg', 'Q6428', 'Boeing 787 Dreamliner', ARRAY['boeing 787 dreamliner', 'boeing 787', 'dreamliner', 'b787', 'b-787', '787', '787 dreamliner'], 'https://fr.wikipedia.org/wiki/Boeing_787', '{"units_built":["http://www.boeing.com/commercial/#/orders-deliveries"]}'::jsonb, true),
  -- B-2 Spirit (Q180285)
  ('northrop-b-2-spirit', 'B-2 Spirit', 'Northrop Grumman Corporation / Northrop Corporation', 'militaire', 'Le Northrop B-2 Spirit, surnommé stealth bomber (en français : bombardier furtif), est un bombardier de l''US Air Force (USAF) développé par Northrop durant la guerre froide. En 2025, le B-2 Spirit est la seule aile volante jamais produite en série (21 exemplaires construits, 18 en service) ; il doit être remplacé par le Northrop Grumman B-21 Raider, de même type qui est plus précis, puissant et plus furtif. Il est l''un des plus célèbres avions furtifs existants.', NULL, '1989-07-17', NULL, 21, 52.4, NULL, NULL, NULL, '1993-12-17', NULL, 'États-Unis', 'General Electric F118', 33, 5, 'https://thumb.wikimedia.org/wikipedia/commons/thumb/7/77/RAF_F-35B_integration_flying_training_with_USAF_B-2_30092019_-_4.jpg/1280px-RAF_F-35B_integration_flying_training_with_USAF_B-2_30092019_-_4.jpg', 'Royal Air Force', 'OGL v1.0', 'http://NationalArchives.gov.uk/doc/open-government-licence/version/1/', 'https://commons.wikimedia.org/wiki/File:RAF_F-35B_integration_flying_training_with_USAF_B-2_30092019_-_4.jpg', 'Q180285', 'Northrop B-2 Spirit', ARRAY['northrop b-2 spirit', 'b-2 spirit', 'northrop grumman b-2 spirit', 'spirit', 'northrop b-2', 'b-2', 'b2', 'boomerang', 'b-2 bomber', 'b2 bomber'], 'https://fr.wikipedia.org/wiki/Northrop_B-2_Spirit', '{"length_m":["https://www.wikidata.org/wiki/Q29042798"],"wingspan_m":["https://www.wikidata.org/wiki/Q29042798"]}'::jsonb, true),
  -- Mikoyan-Gourevitch MiG-29 (Q130681)
  ('mikoyan-mig-29', 'Mikoyan-Gourevitch MiG-29', 'Mikoyan-Gourevitch / Dux Factory', 'militaire', 'Le Mikoyan-Gourevitch MiG-29 (code OTAN Fulcrum) est un avion de chasse de suprématie aérienne soviétique développé au début des années 1970, et dont le premier vol eut lieu le 6 octobre 1977. Il est entré en service dans l''armée soviétique en 1983, mais n''est plus commandé aujourd''hui par l''armée de l''air russe (il devait être théoriquement remplacé à partir de fin 2018 par une version modernisée, le MiG-35 Fulcrum-E). Il est toutefois encore utilisé et commandé par de nombreux autres pays.', NULL, '1977-10-06', NULL, 17.37, 11.4, 4.73, NULL, 18013, '1983-07-01', NULL, 'Union soviétique', 'Klimov RD-33', 1600, 3, 'https://upload.wikimedia.org/wikipedia/commons/d/d9/Russian_Air_Force_Mikoyan-Gurevich_MiG-29S_Naumenko-1.jpg', 'Kirill Naumenko', 'CC BY-SA 3.0', 'https://creativecommons.org/licenses/by-sa/3.0', 'https://commons.wikimedia.org/wiki/File:Russian_Air_Force_Mikoyan-Gurevich_MiG-29S_Naumenko-1.jpg', 'Q130681', 'Mikoyan MiG-29', ARRAY['mikoyan mig-29', 'mikoyan-gourevitch mig-29', 'fulcrum', 'l-18', 'mikoyan-gurevich 29', 'mig-29', 'mikoyan-gourevitch mig-29 fulcrum', 'mig-33', 'mikoyan-gurevitch mig-29 fulcrum', 'mikoyan-gurevitch mig-29', 'mig 29', 'mig-29 fulcrum', 'mikoyan gurevitch mig-29 fulcrum', 'mikoyan-gurevich mig-29 fulcrum'], 'https://fr.wikipedia.org/wiki/Mikoyan-Gourevitch_MiG-29', '{"units_built":["http://www.migavia.ru/corporation/?tid=4#3"],"service_entry":["http://www.airwar.ru/enc/fighter/mig29.html"]}'::jsonb, true),
  -- Boeing 707 (Q6394)
  ('boeing-707', 'Boeing 707', 'Boeing Commercial Airplanes', 'ligne', 'Le Boeing 707 est un avion de ligne quadriréacteur long-courrier à fuselage étroit construit par Boeing Commercial Airplanes entre 1958 et 1979 pour le marché civil, et jusqu''en 1991 pour les dérivés militaires. Son nom est habituellement prononcé « seven o seven » en anglais et « sept cent sept » en français. Selon les versions l''avion a une capacité de 140 à 189 passagers et une distance franchissable comprise entre 4 630 et 10 650 km (2 500 et 5 750 NM).', NULL, '1957-12-20', NULL, 46.61, 44.2, NULL, NULL, NULL, '1958-10-01', NULL, 'États-Unis', NULL, 1010, 3, 'https://upload.wikimedia.org/wikipedia/commons/e/ea/Ecuatoriana_Boeing_707-321C_Hoppe.jpg', 'Perry Hoppe', 'GFDL 1.2', 'http://www.gnu.org/licenses/old-licenses/fdl-1.2.html', 'https://commons.wikimedia.org/wiki/File:Ecuatoriana_Boeing_707-321C_Hoppe.jpg', 'Q6394', 'Boeing 707', ARRAY['boeing 707', 'b707', '707', 'b-707'], 'https://fr.wikipedia.org/wiki/Boeing_707', '{"length_m":["https://www.wikidata.org/wiki/Q29042798"],"wingspan_m":["https://www.wikidata.org/wiki/Q29042798"]}'::jsonb, true),
  -- MiG-21 (Q150609)
  ('mikoyan-gurevich-mig-21', 'MiG-21', 'Mikoyan-Gourevitch / Sokol', 'militaire', 'Le Mikoyan-Gourevitch MiG-21 (en russe : Микояна и Гуревича МиГ-21) est un avion de combat soviétique, également connu sous le code OTAN Fishbed. C''est l''avion de combat supersonique le plus produit de tous les temps, avec presque 14 000 exemplaires. Entré en service en 1960, il restait le 5e avion de combat le plus utilisé dans le monde en 2012 avec, selon une estimation, 793 appareils en activité, soit 5 % de la flotte mondiale d''avions de combat.', NULL, '1956-02-14', NULL, 15.76, 7.15, 4.12, 450, 19000, '1959-01-01', NULL, 'Union soviétique', 'Toumansky R-25', NULL, 3, 'https://upload.wikimedia.org/wikipedia/commons/b/b2/Czechoslovak_Air_Force_Mikoyan-Gurevich_MiG-21R_Lofting-4.jpg', 'Chris Lofting', 'GFDL 1.2', 'http://www.gnu.org/licenses/old-licenses/fdl-1.2.html', 'https://commons.wikimedia.org/wiki/File:Czechoslovak_Air_Force_Mikoyan-Gurevich_MiG-21R_Lofting-4.jpg', 'Q150609', 'Mikoyan-Gurevich MiG-21', ARRAY['mikoyan-gurevich mig-21', 'mig-21', 'mikoyan mig-21', 'balalaika', 'fishbed', 'mig-21 fishbed', 'mikoyan-gurevitch mig-21', 'mig 21'], 'https://fr.wikipedia.org/wiki/Mikoyan-Gourevitch_MiG-21', '{"length_m":["https://www.wikidata.org/wiki/Q29042798"],"wingspan_m":["https://www.wikidata.org/wiki/Q29042798"]}'::jsonb, true),
  -- Antonov An-225 (Q178351)
  ('antonov-an-225-mriya', 'Antonov An-225', 'Aviant', 'militaire', 'L''Antonov An-225 Mriya (en ukrainien : « Ан-225 Мрія », signifiant « aspiration », « désir ardent vers un objectif » ou « rêve » en français, Code OTAN : Cossack) est un avion de transport très gros porteur, conçu dans les années 1980 en unique exemplaire par l''OKB Antonov en République socialiste soviétique d''Ukraine. 01 et son lanceur Energuia avant l''annulation du programme spatial Bourane en 1993.', NULL, '1988-12-21', NULL, 84, 88.4, 18.2, 15400, 13716, '1989-01-01', NULL, 'Union soviétique', 'Progress D-18T', 1, 5, 'https://thumb.wikimedia.org/wikipedia/commons/thumb/c/cc/Antonov_An-225_Beltyukov-1.jpg/1280px-Antonov_An-225_Beltyukov-1.jpg', 'mark steven', 'CC BY-SA 3.0', 'https://creativecommons.org/licenses/by-sa/3.0', 'https://commons.wikimedia.org/wiki/File:Antonov_An-225_Beltyukov-1.jpg', 'Q178351', 'Antonov An-225 Mriya', ARRAY['antonov an-225 mriya', 'antonov an-225', 'an-225', 'mriya', 'cossack', 'an-225 mriya', 'an225', 'a225', 'antonov 225', 'antonov 225 mriya'], 'https://fr.wikipedia.org/wiki/Antonov_An-225_Mriya', '{"first_flight":["https://www.antonov.com/en/history/an-225-mriya","https://www.popularmechanics.com/flight/a2951/1280771/"],"length_m":["https://www.wikidata.org/wiki/Q29042798","https://www.antonov.com/en/history/an-225-mriya","https://www.antonov.com/en/file/V5hQc2hGrJGRs?inline=1","https://contentzone.eurocontrol.int/aircraftperformance/details.aspx?ICAO=A225","https://www.popularmechanics.com/flight/a2951/1280771/"],"wingspan_m":["https://www.antonov.com/en/history/an-225-mriya","https://www.antonov.com/en/file/V5hQc2hGrJGRs?inline=1","https://contentzone.eurocontrol.int/aircraftperformance/details.aspx?ICAO=A225","https://www.popularmechanics.com/flight/a2951/1280771/"],"height_m":["https://www.antonov.com/en/history/an-225-mriya","https://contentzone.eurocontrol.int/aircraftperformance/details.aspx?ICAO=A225","https://www.popularmechanics.com/flight/a2951/1280771/"],"range_km":["https://www.antonov.com/en/history/an-225-mriya","https://aviatorinsider.com/airplane-brands/antonov-an-225/"],"ceiling_m":["https://contentzone.eurocontrol.int/aircraftperformance/details.aspx?ICAO=A225"],"units_built":["https://aviatorinsider.com/airplane-brands/antonov-an-225/"],"service_entry":["https://www.aerospace-technology.com/projects/an225hta/"]}'::jsonb, true),
  -- Boeing B-52 Stratofortress (Q174534)
  ('boeing-b-52-stratofortress', 'Boeing B-52 Stratofortress', 'Boeing', 'militaire', 'Le Boeing B-52 Stratofortress est un bombardier stratégique subsonique à réaction et à long rayon d''action mis en service en 1955 dans l''United States Air Force (USAF). La société Boeing, qui l''a conçu et construit, participe encore à sa maintenance et à son amélioration. Il peut transporter jusqu''à 31 500 kg de munitions air-sol et parcourir plus de 14 000 km sans ravitaillement.', NULL, '1952-04-15', NULL, 48.03, 56.42, 12.4, NULL, 15000, '1955-01-01', NULL, 'États-Unis', 'JT3D', 744, 3, 'https://thumb.wikimedia.org/wikipedia/commons/thumb/2/27/An_air-to-air_left_underside_view_of_the_92nd_Bombardment_Wing%27s_new_camouflaged_B-52G_Stratofortress_aircraft_DF-ST-85-12450.jpg/1280px-An_air-to-air_left_underside_view_of_the_92nd_Bombardment_Wing%27s_new_camouflaged_B-52G_Stratofortress_aircraft_DF-ST-85-12450.jpg', 'Staff Sgt. Bob Simons', 'Public domain', NULL, 'https://commons.wikimedia.org/wiki/File:An_air-to-air_left_underside_view_of_the_92nd_Bombardment_Wing%27s_new_camouflaged_B-52G_Stratofortress_aircraft_DF-ST-85-12450.jpg', 'Q174534', 'Boeing B-52 Stratofortress', ARRAY['boeing b-52 stratofortress', 'stratofortress', 'boeing model 464-67', 'boeing 464-67', 'buff', 'boeing stratofortress', 'b-52 stratofortress', 'b52', 'boeing 464'], 'https://fr.wikipedia.org/wiki/Boeing_B-52_Stratofortress', '{"first_flight":["http://www.boeing.com/resources/boeingdotcom/history/pdf/Boeing_Chronology.pdf","http://www.boeing.com/history/chronology/chron08.html"],"length_m":["https://www.wikidata.org/wiki/Q29042798"],"wingspan_m":["https://www.wikidata.org/wiki/Q29042798"],"units_built":["https://media.defense.gov/2010/May/26/2001330264/-1/-1/0/AFD-100526-026.pdf"]}'::jsonb, true),
  -- Lockheed C-130 Hercules (Q182027)
  ('lockheed-c-130-hercules', 'Lockheed C-130 Hercules', 'Lockheed Martin', 'militaire', 'Le Lockheed C-130 Hercules est un avion de transport militaire conçu par les États-Unis au début des années 1950. Il a rencontré un succès remarquable avec plus de 2 700 exemplaires construits pour près de soixante-dix pays utilisateurs. Le C-130 est en 2025 encore largement utilisé et toujours produit dans des versions améliorées. Bien qu''il conserve l''aspect extérieur du C-130, le C-130J Super Hercules est en fait une nouvelle machine reconnaissable à ses 6 pales d''hélice courbées.', NULL, '1954-08-23', NULL, 29.78, 40.41, 11.66, NULL, NULL, '1956-01-01', NULL, 'États-Unis', 'Allison 501 family', 2600, 2, 'https://thumb.wikimedia.org/wikipedia/commons/thumb/c/cc/Lockheed_C-130_Hercules.jpg/1280px-Lockheed_C-130_Hercules.jpg', 'U.S. Air Force photo by Tech. Sgt. Howard Blair', 'Public domain', NULL, 'https://commons.wikimedia.org/wiki/File:Lockheed_C-130_Hercules.jpg', 'Q182027', 'Lockheed C-130 Hercules', ARRAY['lockheed c-130 hercules', 'hercules', 'c130', 'lockheed c-130', 'lockheed martin c-130', 'cc-130', 'cc130', 'hercules airlifter', 'lockheed hercules', 'c-130 hercules', 'hercules c-130', 'cc-130e hercules', 'c 130', 'c-130b hercules', 'c-130', 'hercule c 130'], 'https://fr.wikipedia.org/wiki/Lockheed_C-130_Hercules', '{"length_m":["https://www.wikidata.org/wiki/Q29042798"],"wingspan_m":["https://www.wikidata.org/wiki/Q29042798"],"units_built":["https://web.archive.org/web/20150709115647/http://lockheedmartin.com/us/news/features/2015/C130FamilyTies.html"]}'::jsonb, true),
  -- Boeing 727 (Q6409)
  ('boeing-727', 'Boeing 727', 'Boeing Commercial Airplanes / Boeing', 'ligne', 'Le Boeing 727 est un avion de ligne triréacteur à fuselage étroit conçu et construit par Boeing Commercial Airplanes entre le début des années 1960 et 1984. Selon les versions, il peut emporter de 149 à 189 passagers et les derniers modèles peuvent voler sur une distance de 5 000 km. Destiné aux vols court et moyen-courriers, le 727 peut être utilisé depuis des pistes relativement courtes sur de petits aéroports.', NULL, '1963-02-09', NULL, 46.7, 32.9, 10.3, NULL, 12192, '1964-02-01', NULL, 'États-Unis', NULL, 1832, 3, 'https://thumb.wikimedia.org/wikipedia/commons/thumb/5/57/B-727_Iberia_%28cropped%29.jpg/1280px-B-727_Iberia_%28cropped%29.jpg', 'Iberia Airlines', 'CC BY 2.0', 'https://creativecommons.org/licenses/by/2.0', 'https://commons.wikimedia.org/wiki/File:B-727_Iberia_(cropped).jpg', 'Q6409', 'Boeing 727', ARRAY['boeing 727', 'b727', '727', 'b-727'], 'https://fr.wikipedia.org/wiki/Boeing_727', '{}'::jsonb, true),
  -- Tupolev Tu-154 (Q172957)
  ('tupolev-tu-154', 'Tupolev Tu-154', 'Tupolev', 'ligne', 'Le Tupolev Tu-154 (en russe : « Туполев Ту-154 »), code OTAN : « Careless », est un avion de ligne triréacteur soviétique conçu au milieu des années 1960. Avec son empennage en T caractéristique et ses trois moteurs installés en position rapprochée à l''arrière du fuselage, il n''est pas sans rappeler son cousin américain de chez Boeing, le 727. La production en série de l''appareil s''est terminée en février 2013.', NULL, '1968-10-04', NULL, 47.9, 37.55, NULL, NULL, NULL, '1972-02-09', NULL, 'Union soviétique / Russie', 'Kouznetsov NK-8 / Soloviev D-30', 1026, 3, 'https://thumb.wikimedia.org/wikipedia/commons/thumb/7/73/RA-85019_T154%28M%29_Special_Flight_Squadron_Rossiya_%28Russian_Government%29_VKO_UUWW_%2832966735944%29.jpg/1280px-RA-85019_T154%28M%29_Special_Flight_Squadron_Rossiya_%28Russian_Government%29_VKO_UUWW_%2832966735944%29.jpg', 'Papas Dos from Moscow, Russia', 'CC BY 2.0', 'https://creativecommons.org/licenses/by/2.0', 'https://commons.wikimedia.org/wiki/File:RA-85019_T154(M)_Special_Flight_Squadron_Rossiya_(Russian_Government)_VKO_UUWW_(32966735944).jpg', 'Q172957', 'Tupolev Tu-154', ARRAY['tupolev tu-154', 'careless', 'tupolev tu-154 careless', 'tupolev 154', 'tu154', 'tu-154'], 'https://fr.wikipedia.org/wiki/Tupolev_Tu-154', '{"length_m":["https://www.wikidata.org/wiki/Q29042798"],"wingspan_m":["https://www.wikidata.org/wiki/Q29042798"]}'::jsonb, true),
  -- Sukhoi Su-27 (Q173680)
  ('sukhoi-su-27', 'Sukhoi Su-27', 'Soukhoï / Komsomolsk-on-Amur Aircraft Production Association', 'militaire', '5, conçu par le bureau d''études Soukhoï (SDB) et mis en service en 1985. Il a donné naissance à de nombreuses variantes, dont certaines ont reçu une nouvelle désignation : Su-30, Su-33, Su-35, Su-37. En 2009, l''avion est en service dans les pays de l''ex-URSS et dans plusieurs autres pays, notamment en Afrique et en Asie (en particulier la république populaire de Chine sous la dénomination Shenyang J-11 et l''Inde).', NULL, '1977-05-20', NULL, 21.9, 14.7, 5.93, 3530, 18500, '1985-01-01', NULL, 'Union soviétique / Russie', 'Saturn AL-31', 809, 3, 'https://thumb.wikimedia.org/wikipedia/commons/thumb/4/49/Su-27SM3_in_flight%2C_Celebration_of_the_100th_anniversary_of_Russian_Air_Force.jpg/1280px-Su-27SM3_in_flight%2C_Celebration_of_the_100th_anniversary_of_Russian_Air_Force.jpg', 'Vitaly V. Kuzmin', 'CC BY-SA 4.0', 'https://creativecommons.org/licenses/by-sa/4.0', 'https://commons.wikimedia.org/wiki/File:Su-27SM3_in_flight,_Celebration_of_the_100th_anniversary_of_Russian_Air_Force.jpg', 'Q173680', 'Sukhoi Su-27', ARRAY['sukhoi su-27', 'su27', 'sukhoi su-27 flanker b', 'sukhoi flanker', 'flanker', 'soukhoï su-27', 'p-42', 'soukhoi su-27 flanker', 'su-27 flanker', 'sukhoï su-27 flanker', 'sukhoï su-27'], 'https://fr.wikipedia.org/wiki/Soukho%C3%AF_Su-27', '{"length_m":["https://www.wikidata.org/wiki/Q29042798"],"units_built":["http://nvo.ng.ru/wars/2001-08-24/6_plane.html"]}'::jsonb, true),
  -- McDonnell Douglas F-15 Eagle (Q29251)
  ('mcdonnell-douglas-f-15-eagle', 'McDonnell Douglas F-15 Eagle', 'McDonnell Douglas / Boeing', 'militaire', 'Le McDonnell Douglas F-15 Eagle (désormais Boeing) est un avion de chasse tout temps dit de supériorité aérienne, conçu par l''avionneur américain McDonnell Douglas dans les années 1970. Produit à plus de mille exemplaires, il est utilisé principalement par l''armée de l''air américaine (USAF), mais il a également été exporté vers quelques pays, dont Israël et le Japon, ce dernier l''ayant même construit sous licence.', NULL, '1972-07-27', NULL, 19.44, 13, 5.6, NULL, NULL, '1976-01-09', NULL, 'États-Unis', 'Pratt & Whitney F100', 1198, 3, 'https://thumb.wikimedia.org/wikipedia/commons/thumb/a/a6/F-15C_Eagle_from_the_44th_Fighter_Squadron_flies_during_a_routine_training_exercise_April_15%2C_2019.jpg/1280px-F-15C_Eagle_from_the_44th_Fighter_Squadron_flies_during_a_routine_training_exercise_April_15%2C_2019.jpg', 'Airman 1st Class Matthew Seefeldt', 'Public domain', NULL, 'https://commons.wikimedia.org/wiki/File:F-15C_Eagle_from_the_44th_Fighter_Squadron_flies_during_a_routine_training_exercise_April_15,_2019.jpg', 'Q29251', 'McDonnell Douglas F-15 Eagle', ARRAY['mcdonnell douglas f-15 eagle', 'boeing f-15', 'eagle', 'mcdonnell douglas eagle', 'f-15 eagle', 'f-15e strike eagle', 'f-15c'], 'https://fr.wikipedia.org/wiki/McDonnell_Douglas_F-15_Eagle', '{"length_m":["https://www.wikidata.org/wiki/Q29042798"]}'::jsonb, true),
  -- Eurofighter Typhoon (Q151384)
  ('eurofighter-typhoon', 'Eurofighter Typhoon', 'Eurofighter Jagdflugzeug', 'militaire', 'L''Eurofighter Typhoon est un avion de combat multirôle biréacteur, à ailes delta et plans canards, développé par le Royaume-Uni (BAE Systems Military Air & Information), l''Italie (Leonardo) ainsi que l''Allemagne et l''Espagne (Airbus Defense and Space) regroupés dans le consortium Eurofighter GmbH. Ces pays ont reçu leurs premiers appareils de série en 2004. L''Autriche, Oman, le Koweït, l''Arabie saoudite et le Qatar s''en sont également portés acquéreurs, portant le total des commandes à 681.', NULL, '1994-03-27', NULL, 15.96, 10.95, 5.28, 1389, 16765, '2003-08-04', NULL, 'Royaume-Uni / Allemagne', 'Eurojet EJ200', 926, 3, 'https://upload.wikimedia.org/wikipedia/commons/3/3c/RAF_Eurofighter_EF-2000_Typhoon_F2_Lofting-1.jpg', 'Chris Lofting', 'GFDL 1.2', 'http://www.gnu.org/licenses/old-licenses/fdl-1.2.html', 'https://commons.wikimedia.org/wiki/File:RAF_Eurofighter_EF-2000_Typhoon_F2_Lofting-1.jpg', 'Q151384', 'Eurofighter Typhoon', ARRAY['eurofighter typhoon', 'ef2000', 'typhoon aircraft', 'eurofighter ef-2000', 'typhoon', 'european fighter aircraft', 'avion de chasse européen', 'ef-2000', 'eurofighter 2000', 'eurofighter'], 'https://fr.wikipedia.org/wiki/Eurofighter_Typhoon', '{}'::jsonb, true),
  -- Soukhoï Su-30 (Q204331)
  ('sukhoi-su-30', 'Soukhoï Su-30', 'Soukhoï / Komsomolsk-on-Amur Aircraft Production Association', 'militaire', 'Le Soukhoï Su-30 (en russe : « Сухой Су-30 », Code OTAN « Flanker-C ») est un avion de combat à réaction multirôle soviétique puis russe, toujours en production dans les années 2020.', NULL, '1989-12-31', NULL, 21.93, 14.7, 6.36, 3000, 17300, '1992-01-01', NULL, NULL, 'Saturn AL-31', NULL, 3, 'https://upload.wikimedia.org/wikipedia/commons/9/9e/Sukhoi_Su-30MK_of_the_Russian_Air_Force.jpg', 'Sergey Krivchikov', 'GFDL 1.2', 'http://www.gnu.org/licenses/old-licenses/fdl-1.2.html', 'https://commons.wikimedia.org/wiki/File:Sukhoi_Su-30MK_of_the_Russian_Air_Force.jpg', 'Q204331', 'Sukhoi Su-30', ARRAY['sukhoi su-30', 'soukhoï su-30', 'flanker-c', 'su-30', 'sukhoï su-30', 'soukhoi su-30'], 'https://fr.wikipedia.org/wiki/Soukho%C3%AF_Su-30', '{}'::jsonb, true),
  -- Airbus A330 (Q6478)
  ('airbus-a330', 'Airbus A330', 'Airbus Commercial Aircraft', 'ligne', 'L''Airbus A330 est un avion de ligne long-courrier de taille moyenne conçu et fabriqué par l''avionneur européen Airbus depuis 1992. Il partage son programme de développement avec le quadriréacteur A340, à la différence près que l''A330 s''attaque directement au marché ETOPS des avions biréacteurs gros porteurs.', NULL, '1992-11-02', NULL, 58.82, 60.3, 16.79, 13450, 12527, '1994-01-17', NULL, 'Allemagne / France', 'General Electric CF6 / Pratt & Whitney PW4000', 1378, 3, 'https://thumb.wikimedia.org/wikipedia/commons/thumb/f/ff/F-WWCB_A330-203_Airbus_Industrie_TLS_27SEP13_%289972134676%29.jpg/1280px-F-WWCB_A330-203_Airbus_Industrie_TLS_27SEP13_%289972134676%29.jpg', 'Ken Fielding', 'CC BY-SA 3.0', 'https://creativecommons.org/licenses/by-sa/3.0', 'https://commons.wikimedia.org/wiki/File:F-WWCB_A330-203_Airbus_Industrie_TLS_27SEP13_(9972134676).jpg', 'Q6478', 'Airbus A330', ARRAY['airbus a330', 'a330', 'a330ceo'], 'https://fr.wikipedia.org/wiki/Airbus_A330', '{}'::jsonb, true),
  -- Boeing 767 (Q6423)
  ('boeing-767', 'Boeing 767', 'Boeing Commercial Airplanes', 'ligne', 'Le Boeing 767 est un avion de ligne à réaction gros-porteur de taille moyenne construit depuis 1979 par Boeing Commercial Airplanes. Il est le premier biréacteur à fuselage large du constructeur et le premier avion de ligne à être équipé d''un cockpit à deux membres d''équipage avec une planche de bord tout écran. L''avion est équipé de deux turboréacteurs à double flux, d''un empennage conventionnel et, pour réduire la traînée aérodynamique, d''un profil de voilure supercritique.', NULL, '1981-09-26', NULL, NULL, 47.57, NULL, NULL, NULL, NULL, NULL, 'États-Unis', NULL, 1326, 3, 'https://thumb.wikimedia.org/wikipedia/commons/thumb/4/43/Delta_Air_Lines_B767-332_N130DL.jpg/1280px-Delta_Air_Lines_B767-332_N130DL.jpg', 'Delta_Air_Lines_B767-300_N130DL.jpg: Richard Snyder from San Jose, CA, United States of America derivative work: Altair78 (talk)', 'CC BY-SA 2.0', 'https://creativecommons.org/licenses/by-sa/2.0', 'https://commons.wikimedia.org/wiki/File:Delta_Air_Lines_B767-332_N130DL.jpg', 'Q6423', 'Boeing 767', ARRAY['boeing 767', 'b767', '767', 'b-767'], 'https://fr.wikipedia.org/wiki/Boeing_767', '{"wingspan_m":["https://www.wikidata.org/wiki/Q29042798"]}'::jsonb, true),
  -- Boeing B-17 Flying Fortress (Q185000)
  ('boeing-b-17-flying-fortress', 'Boeing B-17 Flying Fortress', 'Boeing', 'collection', 'Le Boeing B-17 Flying Fortress, en français : « Forteresse volante », est l''un des bombardiers américains, voire alliés, les plus connus de la Seconde Guerre mondiale. Il est celui qui a largué le plus gros tonnage de bombes tout au long du conflit. Conçu dans la seconde moitié des années 1930, le B-17 a été construit à 12 677 exemplaires et a servi sur tous les théâtres d''opération jusqu''en 1945.', NULL, '1935-07-28', NULL, 22.8, 31.6, 5.8, NULL, 10850, '1938-04-01', '1968-01-01', 'États-Unis', NULL, 12731, 1, 'https://thumb.wikimedia.org/wikipedia/commons/thumb/0/0b/B17_-_Chino_Airshow_2014_%28framed%29.jpg/1280px-B17_-_Chino_Airshow_2014_%28framed%29.jpg', 'Airwolfhound', 'CC BY-SA 2.0', 'https://creativecommons.org/licenses/by-sa/2.0', 'https://commons.wikimedia.org/wiki/File:B17_-_Chino_Airshow_2014_(framed).jpg', 'Q185000', 'Boeing B-17 Flying Fortress', ARRAY['boeing b-17 flying fortress', 'bomber design 17', 'boeing flying fortress', 'flying fortress', 'b-17', 'forteresse volante', 'b-17 flying fortress'], 'https://fr.wikipedia.org/wiki/Boeing_B-17_Flying_Fortress', '{}'::jsonb, true),
  -- Tupolev Tu-144 (Q188513)
  ('tupolev-tu-144', 'Tupolev Tu-144', 'Tupolev / Voronezh Aircraft Production Association', 'ligne', 'Le Tupolev Tu-144 (en russe : Tyполев Ту-144, nom de code OTAN : « Charger ») est un avion de ligne supersonique quadriréacteur développé en URSS par le bureau d''études Tupolev. Avec le Concorde franco-britannique, ils sont les seuls avions civils supersoniques à avoir atteint la production.', NULL, '1968-12-31', NULL, NULL, NULL, NULL, NULL, NULL, '1975-12-26', '1978-06-01', 'Union soviétique', 'Kolesov RD-36-51', 16, 5, 'https://thumb.wikimedia.org/wikipedia/commons/thumb/b/bd/.00_0896_Supersonic_Airliner_Concorde.jpg/1280px-.00_0896_Supersonic_Airliner_Concorde.jpg', 'W. Bulach', 'CC BY-SA 4.0', 'https://creativecommons.org/licenses/by-sa/4.0', 'https://commons.wikimedia.org/wiki/File:.00_0896_Supersonic_Airliner_Concorde.jpg', 'Q188513', 'Tupolev Tu-144', ARRAY['tupolev tu-144', 'tu-144', 'charger', 'tupolev 144', 'konkordski', 'concordski'], 'https://fr.wikipedia.org/wiki/Tupolev_Tu-144', '{}'::jsonb, true),
  -- Airbus A340 (Q6481)
  ('airbus-a340', 'Airbus A340', 'Airbus Commercial Aircraft', 'ligne', 'L''Airbus A340 est un avion de ligne quadriréacteur long-courrier de grande capacité fabriqué par Airbus de 1991 à 2011. Il est décliné en plusieurs versions suivant la capacité ou le rayon d''action désirés par chaque compagnie. Cette famille d''appareils a été conçue avec un design semblable à celui de l''Airbus A330, dont elle est dérivée. Mais elle est équipée de quatre turboréacteurs au lieu de deux.', NULL, '1991-10-25', NULL, 59.4, 60.3, 16.8, 14800, 12500, '1993-03-01', NULL, NULL, 'CFM International CFM56 / Rolls-Royce Trent 500', 377, 4, 'https://thumb.wikimedia.org/wikipedia/commons/thumb/3/33/A340-600.jpg/1280px-A340-600.jpg', 'Iberia Airlines', 'CC BY 2.0', 'https://creativecommons.org/licenses/by/2.0', 'https://commons.wikimedia.org/wiki/File:A340-600.jpg', 'Q6481', 'Airbus A340', ARRAY['airbus a340', 'airbus 340', 'a340'], 'https://fr.wikipedia.org/wiki/Airbus_A340', '{}'::jsonb, true),
  -- F-14 Tomcat (Q34945)
  ('grumman-f-14-tomcat', 'F-14 Tomcat', 'Grumman', 'militaire', 'Le Grumman F-14 Tomcat est un avion de chasse biréacteur embarqué, dont la particularité est de posséder des ailes à géométrie variable. Destiné à protéger la flotte d''attaques aériennes, il est le premier chasseur conçu aux États-Unis à intégrer les leçons de la guerre du Viêt Nam. Il est devenu mondialement célèbre en 1986, grâce au film Top Gun, avec Tom Cruise.', NULL, '1970-12-21', 2485, 19, 19.55, 4.8, 3000, 18000, '1974-01-01', '2006-09-22', 'États-Unis', 'General Electric F110 / Pratt & Whitney TF30', 712, 3, 'https://thumb.wikimedia.org/wikipedia/commons/thumb/1/19/F-14A_Tomcat_over_Iraq_during_Southern_Watch.jpg/1280px-F-14A_Tomcat_over_Iraq_during_Southern_Watch.jpg', 'Cdr. David Baranek, U.S. Navy photo 330-CFD-DN-SD-00-03487', 'Public domain', NULL, 'https://commons.wikimedia.org/wiki/File:F-14A_Tomcat_over_Iraq_during_Southern_Watch.jpg', 'Q34945', 'Grumman F-14 Tomcat', ARRAY['grumman f-14 tomcat', 'f-14 tomcat', 'grumman f-14', 'f-14 "tomcat" cesar', 'g-303 tomcat', 'tomcat', 'tomcat aircraft', 'g-303', 'f14 tomcat', 'grumman g-303', 'grumman g-303 tomcat', 'f-14'], 'https://fr.wikipedia.org/wiki/Grumman_F-14_Tomcat', '{"max_speed_kmh":["https://www.history.navy.mil/content/history/museums/nnam/explore/collections/aircraft/f/f-14a-tomcat.html"],"wingspan_m":["https://www.wikidata.org/wiki/Q29042798"]}'::jsonb, true),
  -- Lockheed F-117 Nighthawk (Q184491)
  ('lockheed-f-117-nighthawk', 'Lockheed F-117 Nighthawk', 'Skunk Works', 'militaire', 'Le Lockheed-Martin F-117 Nighthawk est un avion d''attaque au sol conçu par les États-Unis dans la seconde moitié des années 1970. C''est le premier avion militaire au monde étudié dès le départ pour avoir la signature la plus réduite possible. Il a été retiré du service actif le 21 avril 2008 et fut mis définitivement hors service à partir de 2018 mais une quarantaine d''appareils servent toujours, tenant le rôle d''agresseurs lors d''exercices en 2024.', NULL, '1981-06-18', NULL, 20.09, 13.21, 3.78, 1722, 13700, '1983-10-01', '2008-04-22', 'États-Unis', 'General Electric F404', 64, 4, 'https://thumb.wikimedia.org/wikipedia/commons/thumb/a/a1/F-117_Nighthawk_Front.jpg/1280px-F-117_Nighthawk_Front.jpg', 'Staff Sgt. Aaron Allmon II', 'Public domain', NULL, 'https://commons.wikimedia.org/wiki/File:F-117_Nighthawk_Front.jpg', 'Q184491', 'Lockheed F-117 Nighthawk', ARRAY['lockheed f-117 nighthawk', 'lockheed martin f-117 nighthawk', 'lockheed martin f-117 night hawk', 'lockheed f-117 night hawk', 'f-117 nighthawk', 'f-117 night hawk', 'nighthawk', 'night hawk', 'f-117', 'f117', 'f 117'], 'https://fr.wikipedia.org/wiki/Lockheed_F-117_Nighthawk', '{"first_flight":["https://www.holloman.af.mil/About/Fact-Sheets/Display/Article/317344/f-117a-nighthawk/"],"length_m":["https://www.nationalmuseum.af.mil/Visit/Museum-Exhibits/Fact-Sheets/Display/Article/198056/lockheed-f-117a-nighthawk/","https://www.sacmuseum.org/visit/exhibit/f-117-nighthawk/"],"wingspan_m":["https://www.nationalmuseum.af.mil/Visit/Museum-Exhibits/Fact-Sheets/Display/Article/198056/lockheed-f-117a-nighthawk/","https://www.sacmuseum.org/visit/exhibit/f-117-nighthawk/"],"height_m":["https://www.nationalmuseum.af.mil/Visit/Museum-Exhibits/Fact-Sheets/Display/Article/198056/lockheed-f-117a-nighthawk/","https://www.sacmuseum.org/visit/exhibit/f-117-nighthawk/"],"range_km":["https://www.sacmuseum.org/visit/exhibit/f-117-nighthawk/"],"ceiling_m":["https://www.nationalmuseum.af.mil/Visit/Museum-Exhibits/Fact-Sheets/Display/Article/198056/lockheed-f-117a-nighthawk/","https://www.sacmuseum.org/visit/exhibit/f-117-nighthawk/"],"units_built":["https://www.lockheedmartin.com/content/dam/lockheed-martin/aero/documents/F-117/F117%20Fast%20Facts_FINAL.pdf"],"service_entry":["https://www.lockheedmartin.com/content/dam/lockheed-martin/aero/documents/F-117/F117%20Fast%20Facts_FINAL.pdf"],"retirement":["https://www.sacmuseum.org/visit/exhibit/f-117-nighthawk/"]}'::jsonb, true),
  -- Boeing 757 (Q6418)
  ('boeing-757', 'Boeing 757', 'Boeing Commercial Airplanes', 'ligne', 'Le Boeing 757 est un avion de ligne moyen-courrier biréacteur à fuselage étroit produit par Boeing Commercial Airplanes de 1981 à 2004. C''est le plus grand avion passager monocouloir de cet avionneur. Prévu pour remplacer le triréacteur Boeing 727 sur des itinéraires courts et moyen-courriers, le 757 a une plus grande capacité (200 à 289 passagers) sur une distance maximale de 5 830 à 7 600 km, selon la version.', NULL, '1982-02-19', NULL, 47.32, 37.95, NULL, NULL, NULL, '1983-01-01', NULL, 'États-Unis', NULL, 1050, 3, 'https://thumb.wikimedia.org/wikipedia/commons/thumb/c/c8/American_Airlines_Boeing_757-200_N605AA_SJC.jpg/1280px-American_Airlines_Boeing_757-200_N605AA_SJC.jpg', 'Dylan Ashe from San Jose, USA', 'CC BY-SA 2.0', 'https://creativecommons.org/licenses/by-sa/2.0', 'https://commons.wikimedia.org/wiki/File:American_Airlines_Boeing_757-200_N605AA_SJC.jpg', 'Q6418', 'Boeing 757', ARRAY['boeing 757', 'b757', '757', 'b-757'], 'https://fr.wikipedia.org/wiki/Boeing_757', '{"length_m":["https://www.wikidata.org/wiki/Q29042798"],"wingspan_m":["https://www.wikidata.org/wiki/Q29042798"],"units_built":["http://www.boeing.com/commercial/#/orders-deliveries"]}'::jsonb, true),
  -- Airbus A300 (Q6437)
  ('airbus-a300', 'Airbus A300', 'Airbus Commercial Aircraft', 'ligne', 'L''Airbus A300 est une famille d''avions de ligne à large fuselage construits par Airbus de 1972 à 2007. L''A300 est à l''origine de la création du groupe Airbus et constitue son premier modèle commercialisé. La dernière version de l''avion, l''A300B4-600R, est améliorée en tant qu''appareil moyen-courrier, ouvrant le marché à sa version long-courrier, désormais connue sous le nom d''A310.', NULL, '1972-10-28', 917, 53.62, 44.84, 16.53, 3430, 11000, '1974-05-30', NULL, 'France / Allemagne', 'General Electric CF6 / JT9D', 561, 3, 'https://thumb.wikimedia.org/wikipedia/commons/thumb/2/2c/Airbus_A300B4-603%2C_Lufthansa_AN0520385.jpg/1280px-Airbus_A300B4-603%2C_Lufthansa_AN0520385.jpg', 'Raimund Stehmann', 'GFDL', 'http://www.gnu.org/copyleft/fdl.html', 'https://commons.wikimedia.org/wiki/File:Airbus_A300B4-603,_Lufthansa_AN0520385.jpg', 'Q6437', 'Airbus A300', ARRAY['airbus a300', 'a300'], 'https://fr.wikipedia.org/wiki/Airbus_A300', '{"length_m":["https://www.wikidata.org/wiki/Q29042798"],"wingspan_m":["https://www.wikidata.org/wiki/Q29042798"]}'::jsonb, true),
  -- Saab JAS 39 Gripen (Q150088)
  ('saab-jas-39-gripen', 'Saab JAS 39 Gripen', 'Saab', 'militaire', 'Le Saab JAS 39 Gripen (en français : « griffon ») est un avion multirôle de quatrième génération développé par la Suède dans les années 1980 et construit par Saab. Mis en service en 1996 dans la Force aérienne suédoise, il a été exporté en Hongrie, République tchèque, Afrique du Sud, Thaïlande et Brésil (où il prend le nom de F-39 Gripen) avec 323 exemplaires commandés fin 2025, dont 204 pour la Suède.', NULL, '1988-12-09', NULL, NULL, 8.4, 4.5, NULL, 15240, '1997-01-01', NULL, 'Suède', 'General Electric F404', 264, 4, 'https://thumb.wikimedia.org/wikipedia/commons/thumb/e/ef/Saab_JAS-39_Gripen_of_the_Czech_Air_Force_taking_off_from_AFB_%C4%8C%C3%A1slav.jpg/1280px-Saab_JAS-39_Gripen_of_the_Czech_Air_Force_taking_off_from_AFB_%C4%8C%C3%A1slav.jpg', 'Milan Nykodym from Kutna Hora, Czech Republic', 'CC BY-SA 2.0', 'https://creativecommons.org/licenses/by-sa/2.0', 'https://commons.wikimedia.org/wiki/File:Saab_JAS-39_Gripen_of_the_Czech_Air_Force_taking_off_from_AFB_%C4%8C%C3%A1slav.jpg', 'Q150088', 'Saab JAS 39 Gripen', ARRAY['saab jas 39 gripen', 'saab 39 gripen', 'jas 39', 'jas-39', 'gripen', 'jas 39 gripen', 'saab jas-39 gripen', 'jas-39 gripen', 'saab gripen'], 'https://fr.wikipedia.org/wiki/Saab_JAS_39_Gripen', '{"units_built":["http://www.saabgroup.com/en/Air/Gripen-Fighter-System/Gripen/Gripen/In-use/"],"service_entry":["http://www.saabgroup.com/en/Air/Gripen-Fighter-System/Gripen/Gripen/In-use/"]}'::jsonb, true),
  -- McDonnell Douglas F-4 Phantom II (Q151432)
  ('mcdonnell-douglas-f-4-phantom-ii', 'McDonnell Douglas F-4 Phantom II', 'McDonnell Aircraft Corporation / McDonnell Douglas', 'militaire', 'Le F-4 Phantom II est un avion militaire de troisième génération conçu par le constructeur américain McDonnell à partir de 1953. Il s''agit de l''un des avions militaires américains les plus importants du XXe siècle et l''avion de combat occidental ayant été le plus produit depuis la guerre de Corée : le 5 195e et dernier exemplaire a été livré en 1981, après plus de 20 ans de production ininterrompue. Pendant la guerre du Viêt Nam, la cadence de production du F-4 était de 72 exemplaires par mois.', NULL, '1958-05-27', NULL, 19.2, 11.68, 5, 2800, NULL, '1959-01-01', NULL, 'États-Unis', 'General Electric J79', 5195, 2, 'https://thumb.wikimedia.org/wikipedia/commons/thumb/0/01/McDonnell_F-4B_Phantom_II_of_VF-111_in_flight%2C_in_1973.jpg/1280px-McDonnell_F-4B_Phantom_II_of_VF-111_in_flight%2C_in_1973.jpg', 'U.S. Navy', 'Public domain', NULL, 'https://commons.wikimedia.org/wiki/File:McDonnell_F-4B_Phantom_II_of_VF-111_in_flight,_in_1973.jpg', 'Q151432', 'McDonnell Douglas F-4 Phantom II', ARRAY['mcdonnell douglas f-4 phantom ii', 'f-110 spectre', 'phantom', 'mcdonnell aircraft phantom ii', 'mcdonnell aircraft f-4', 'mcdonnell aircraft f4h', 'f-4 phantom ii', 'f4h', 'f-4', 'f-4 phantom', 'phantom ii'], 'https://fr.wikipedia.org/wiki/McDonnell_Douglas_F-4_Phantom_II', '{}'::jsonb, true),
  -- Boeing B-29 Superfortress (Q184870)
  ('boeing-b-29-superfortress', 'Boeing B-29 Superfortress', 'Boeing', 'collection', 'Le Boeing B-29 Superfortress est un bombardier lourd quadrimoteur à hélices et à long rayon d''action utilisé par les États-Unis pendant la Seconde Guerre mondiale et la guerre de Corée. Conçu par Boeing comme le Model 345 et développé à partir de 1938, le B-29 est l''un des plus gros avions utilisés pendant ces conflits. Lors de son entrée en service, il est à la pointe de la technologie.', NULL, '1942-09-21', NULL, 30.18, 43.06, 8.45, NULL, 9710, '1944-05-08', '1960-06-21', 'États-Unis', NULL, 3970, 2, 'https://upload.wikimedia.org/wikipedia/commons/9/9d/Boeing_B-29_Superfortress_Bockscar_2_USAF.jpg', 'USAF Museum', 'Public domain', NULL, 'https://commons.wikimedia.org/wiki/File:Boeing_B-29_Superfortress_Bockscar_2_USAF.jpg', 'Q184870', 'Boeing B-29 Superfortress', ARRAY['boeing b-29 superfortress', 'superfortress', 'boeing washington', 'b-29 superfortress', 'b29 superfortress', 'rb-29 superfortress', 'f-13 superfortress', 'fb-29j superfortress', 'boeing b-29'], 'https://fr.wikipedia.org/wiki/Boeing_B-29_Superfortress', '{"units_built":["https://www.britannica.com/technology/B-29","https://www.wikidata.org/wiki/Q5375741"]}'::jsonb, true),
  -- Mikoyan-Gourevitch MiG-15 (Q187377)
  ('mikoyan-gurevich-mig-15', 'Mikoyan-Gourevitch MiG-15', 'Mikoyan-Gourevitch / centre national de recherche et de production Progress', 'collection', 'Le Mikoyan-Gourevitch MiG-15 est un avion de chasse à réaction construit en grande série par les Soviétiques au début de la guerre froide. Réalisé après la livraison de vingt-cinq turboréacteurs Rolls-Royce Nene par le Royaume-Uni, il se révéla supérieur aux meilleures réalisations occidentales lors de la guerre de Corée, sauf le North American F-86 Sabre (le bilan des combats aériens entre MiG-15 et Sabre a été évalué en 2013 à 100 Sabre abattus contre 566 MiG-15 [réf. nécessaire]).', NULL, '1947-12-30', NULL, 10.08, 10.08, 3.6, NULL, NULL, '1949-01-01', '2006-01-01', 'Union soviétique', 'RD-45 / WP-5', 15560, 1, 'https://upload.wikimedia.org/wikipedia/commons/3/32/MiG-15_RB1.jpg', NULL, 'CC BY-SA 3.0', 'http://creativecommons.org/licenses/by-sa/3.0/', 'https://commons.wikimedia.org/wiki/File:MiG-15_RB1.jpg', 'Q187377', 'Mikoyan-Gurevich MiG-15', ARRAY['mikoyan-gurevich mig-15', 'mikoyan-gourevitch mig-15', 'mikoyan-gurevich fagot', 'mig-15', 'fagot', 'mikoyan-gurevich 15'], 'https://fr.wikipedia.org/wiki/Mikoyan-Gourevitch_MiG-15', '{"retirement":["http://lenta.ru/news/2006/11/07/mig/"]}'::jsonb, true),
  -- Soukhoï Su-35 (Q245275)
  ('sukhoi-su-35', 'Soukhoï Su-35', 'Soukhoï / Komsomolsk-on-Amur Aircraft Production Association', 'militaire', 'Le Soukhoï Su-35 (en russe : Сухой Су-35, code OTAN Flanker-E) est un chasseur multirôle russe. Il a été créé dans le but d''accroître les capacités offensives du Su-27 et de lui donner la possibilité de détruire tant les cibles aériennes que les cibles de surface.', NULL, '2008-02-19', NULL, 21.9, 15.3, 5.9, NULL, 18000, '2014-02-12', NULL, NULL, 'Saturn AL-31', NULL, 3, 'https://upload.wikimedia.org/wikipedia/commons/b/be/Sukhoi_Su-35_on_MAKS-2011.jpg', 'Rulexip', 'CC BY-SA 3.0', 'https://creativecommons.org/licenses/by-sa/3.0', 'https://commons.wikimedia.org/wiki/File:Sukhoi_Su-35_on_MAKS-2011.jpg', 'Q245275', 'Sukhoi Su-35', ARRAY['sukhoi su-35', 'soukhoï su-35', 'flanker-e', 'su35', 'sukhoi su-27m', 'su-27m', 'su27m', 'su-35', 'soukhoi su-35', 'sukhoï su-35'], 'https://fr.wikipedia.org/wiki/Soukho%C3%AF_Su-35', '{}'::jsonb, true),
  -- Messerschmitt Bf 109 (Q155639)
  ('messerschmitt-bf-109', 'Messerschmitt Bf 109', 'Messerschmitt', 'collection', 'Le Messerschmitt Bf 109 est un chasseur monomoteur monoplace allemand conçu par l''ingénieur allemand Willy Messerschmitt en réponse à un appel d''offres du ministère de l''Aviation du Reich pour la conception d''un chasseur moderne devant équiper la Luftwaffe naissante en 1935.', NULL, '1935-05-01', NULL, 8.95, 9.93, 2.6, NULL, 12000, '1937-01-01', '1965-12-27', 'Reich allemand', 'Junkers Jumo 210 / Daimler-Benz DB 601', NULL, 3, 'https://upload.wikimedia.org/wikipedia/commons/0/00/Me109_G-6_D-FMBB_1.jpg', 'Kogo', 'CC BY-SA 2.0', 'https://creativecommons.org/licenses/by-sa/2.0', 'https://commons.wikimedia.org/wiki/File:Me109_G-6_D-FMBB_1.jpg', 'Q155639', 'Messerschmitt Bf 109', ARRAY['messerschmitt bf 109', 'messerschmitt 109', 'bf 109', 'messerschmitt me 109', 'me 109'], 'https://fr.wikipedia.org/wiki/Messerschmitt_Bf_109', '{}'::jsonb, true),
  -- Su-24 (Q210413)
  ('sukhoi-su-24', 'Su-24', 'Soukhoï / Novosibirsk Aircraft Production Association', 'militaire', 'Le Soukhoï Su-24 (code OTAN Fencer) est un bombardier tout-temps avec une voilure à géométrie variable de première ligne soviétique. Environ 1 400 exemplaires ont été produits.', NULL, '1970-01-17', NULL, 22.53, 17.5, 6.19, NULL, 11000, '1975-02-04', NULL, 'Union soviétique / Russie', 'Lyulka AL-21', NULL, 3, 'https://upload.wikimedia.org/wikipedia/commons/7/76/Sukhoi_Su-24_inflight_Mishin-3.jpg', 'Alexander Mishin', 'CC BY-SA 3.0', 'https://creativecommons.org/licenses/by-sa/3.0', 'https://commons.wikimedia.org/wiki/File:Sukhoi_Su-24_inflight_Mishin-3.jpg', 'Q210413', 'Sukhoi Su-24', ARRAY['sukhoi su-24', 'su-24', 'fencer', 'sukhoi su-24 fencer', 'su-24 fencer', 'sukhoi fencer', 'sukhoï su-24', 'soukhoi su-24'], 'https://fr.wikipedia.org/wiki/Soukho%C3%AF_Su-24', '{"wingspan_m":["https://www.wikidata.org/wiki/Q29042798"]}'::jsonb, true),
  -- MiG-31 (Q150050)
  ('mikoyan-mig-31', 'MiG-31', 'Mikoyan-Gourevitch / Sokol', 'militaire', 'Mikoyan-Gourevitch MiG-31 (code OTAN : « Foxhound ») est un intercepteur d''origine soviétique (actuellement russe). Il est dérivé du célèbre MiG-25 Foxbat, dont il conserve l''allure générale et les performances élevées, mais en diffère notamment par la présence d''un second membre d''équipage et d''un radar à capacité « look-down/shoot-down » (détection et tir sur des cibles volant à une altitude inférieure).', NULL, '1975-09-16', NULL, 22.69, 13.46, 6.15, 3300, 20600, '1981-05-06', NULL, NULL, 'Soloviev D-30', 519, 3, 'https://upload.wikimedia.org/wikipedia/commons/c/c3/MiG-31_Pichugin-1.jpg', 'Dmitriy Pichugin', 'GFDL 1.2', 'http://www.gnu.org/licenses/old-licenses/fdl-1.2.html', 'https://commons.wikimedia.org/wiki/File:MiG-31_Pichugin-1.jpg', 'Q150050', 'Mikoyan MiG-31', ARRAY['mikoyan mig-31', 'mig-31', 'foxhound', 'mikoyan-gurevich mig-31 foxhound', 'mikoyan-gurevich mig-31'], 'https://fr.wikipedia.org/wiki/Mikoyan-Gourevitch_MiG-31', '{}'::jsonb, true),
  -- Mikoyan-Gourevitch MiG-25 (Q199570)
  ('mikoyan-gurevich-mig-25', 'Mikoyan-Gourevitch MiG-25', 'Mikoyan-Gourevitch / Sokol', 'militaire', 'Le Mikoyan-Gourevitch MiG-25 (en russe : Микоян и Гуревич МиГ-25) est un avion d''interception et de reconnaissance soviétique, connu sous le nom de code OTAN « Foxbat ». Avec le MiG-31, et le SR-71, il est un des seuls avions de combat capables d''atteindre une vitesse de Mach 3 à avoir été mis en service dans le monde.', NULL, '1964-03-05', NULL, 19.75, 14.01, 6.1, NULL, 20700, '1970-01-01', NULL, 'Union soviétique', 'Toumanski R-15', 1190, 3, 'https://upload.wikimedia.org/wikipedia/commons/a/a4/MiG-25RBS_Pichugin-1.jpg', 'Dmitriy Pichugin', 'GFDL 1.2', 'http://www.gnu.org/licenses/old-licenses/fdl-1.2.html', 'https://commons.wikimedia.org/wiki/File:MiG-25RBS_Pichugin-1.jpg', 'Q199570', 'Mikoyan-Gurevich MiG-25', ARRAY['mikoyan-gurevich mig-25', 'mikoyan-gourevitch mig-25', 'mig-25 foxbat', 'mikoyan mig-25', 'foxbat', 'mig-25'], 'https://fr.wikipedia.org/wiki/Mikoyan-Gourevitch_MiG-25', '{}'::jsonb, true)
