  -- Mikoyan-Gurevich MiG-23 (Q155679)
  ('mikoyan-gurevich-mig-23', 'Mikoyan-Gurevich MiG-23', 'Mikoyan-Gourevitch', 'militaire', 'Le Mikoyan-Gourevitch MiG-23 (Микоян и Гуревич МиГ-23 en russe, code OTAN Flogger) est un avion de chasse soviétique à géométrie variable, capable d''opérer depuis des aérodromes petits et mal entretenus. Conçu par Mikoyan-Gourevitch, c''est le premier chasseur soviétique capable de repérer et d''engager des cibles volant plus bas que lui, et hors de portée visuelle. Une version spécialisée dans l''attaque au sol a également été réalisée.', NULL, '1967-06-10', NULL, 16.7, 13.97, 4.82, NULL, 18500, '1970-01-01', NULL, 'Union soviétique', NULL, 5047, 2, 'https://thumb.wikimedia.org/wikipedia/commons/thumb/5/57/MiG-23-red12.jpg/1280px-MiG-23-red12.jpg', 'US military', 'Public domain', NULL, 'https://commons.wikimedia.org/wiki/File:MiG-23-red12.jpg', 'Q155679', 'Mikoyan-Gurevich MiG-23', ARRAY['mikoyan-gurevich mig-23', 'flogger', 'mikoyan-gurevich flogger', 'mig-23', 'mig 23', 'mikoyan-gourevitch mig-23'], 'https://fr.wikipedia.org/wiki/Mikoyan-Gourevitch_MiG-23', '{}'::jsonb, true),
  -- Su-57 (Q194455)
  ('sukhoi-su-57', 'Su-57', 'Komsomolsk-on-Amur Aircraft Production Association', 'militaire', 'Le Soukhoï Su-57 (en russe : Сухой Су-57, Code OTAN : Felon, depuis septembre 2019) est un avion de combat polyvalent furtif russe de cinquième génération. Une version issue d''une coopération indo-russe développée par Soukhoï aurait dû voir le jour sous la désignation HAL FGFA. L''appellation « PAK-FA » (en russe : Перспективный Авиационный Комплекс Фронтовой Авиации) peut être traduite en français par « Futur Système aéronautique de l''aviation du front », mais a été abandonnée.', NULL, '2010-01-29', NULL, 19.8, 14, 6.06, 5500, 20000, '2018-01-01', NULL, 'Russie', 'Saturn AL-41', 10, 5, 'https://upload.wikimedia.org/wikipedia/commons/9/93/Sukhoi_T-50_in_2011_%284%29.jpg', 'Dmitry Zherdin', 'CC BY-SA 3.0', 'https://creativecommons.org/licenses/by-sa/3.0', 'https://commons.wikimedia.org/wiki/File:Sukhoi_T-50_in_2011_(4).jpg', 'Q194455', 'Sukhoi Su-57', ARRAY['sukhoi su-57', 'su-57', 'cuidado con los peruanos', 'sukhoi pak fa', 'sukhoi t-50', 'pak fa', 't-50 aircraft', 'sukhoi 57', 'su57', 'felon', 'soukhoï pak-fa', 't-50', 'soukhoï t-50'], 'https://fr.wikipedia.org/wiki/Soukho%C3%AF_Su-57', '{}'::jsonb, true),
  -- Ilyushin Il-76 (Q142549)
  ('ilyushin-il-76', 'Ilyushin Il-76', 'Iliochine / Association de construction aéronautique de Tachkent', 'militaire', 'L''Iliouchine II-76 est un avion de transport militaire moyen/long courrier quadriréacteur à double flux conçu en Union soviétique à partir de 1967, mais dont le programme a débuté au début des années 1960. Sa désignation OTAN est Candid. Il existe également en version avion ravitailleur nommée Iliouchine Il-78 (code OTAN : Midas) et en version système de détection et de commandement aéroporté, nommée Iliouchine A-50 (code OTAN : Mainstay).', NULL, '1971-03-25', NULL, 46.59, 50.5, NULL, NULL, NULL, '1974-01-01', NULL, 'Union soviétique', 'Aviadvigatel PS-90', 950, 3, 'https://thumb.wikimedia.org/wikipedia/commons/thumb/7/7e/Ilyushin_IL-76MD_-_Ukrainian_Air_Force_-_76683_%2848367735331_cropped%29.jpg/1280px-Ilyushin_IL-76MD_-_Ukrainian_Air_Force_-_76683_%2848367735331_cropped%29.jpg', 'Steve Lynes from Sandshurst, United Kingdom', 'CC BY 2.0', 'https://creativecommons.org/licenses/by/2.0', 'https://commons.wikimedia.org/wiki/File:Ilyushin_IL-76MD_-_Ukrainian_Air_Force_-_76683_(48367735331_cropped).jpg', 'Q142549', 'Ilyushin Il-76', ARRAY['ilyushin il-76', 'candid', 'il-76', 'iliouchine il-76 candid', 'illiouchine il-76 candid', 'ilyushin il-76 candid'], 'https://fr.wikipedia.org/wiki/Iliouchine_Il-76', '{"length_m":["https://www.wikidata.org/wiki/Q29042798"],"wingspan_m":["https://www.wikidata.org/wiki/Q29042798"],"units_built":["http://www.soldiering.ru/avia/airplane/il76.php"]}'::jsonb, true),
  -- Lockheed SR-71 Blackbird (Q190114)
  ('lockheed-sr-71-blackbird', 'Lockheed SR-71 Blackbird', 'Skunk Works', 'militaire', 'Le Lockheed SR-71 Blackbird (Merle) est un avion de reconnaissance à long rayon d''action et à haute altitude, construit par Lockheed Corporation pour l''armée de l''air américaine, qui l''utilisa principalement de 1968 à 1990. Il a été développé à partir de l''avion-espion Lockheed A-12 Oxcart.', NULL, '1964-12-22', 3445, 32.74, 16.94, 5.64, 2700, 25908, '1966-01-07', '1999-10-09', 'États-Unis', 'Pratt & Whitney J58', 29, 5, 'https://thumb.wikimedia.org/wikipedia/commons/thumb/a/ae/SR-71A_in_flight_near_Beale_AFB_1988.JPEG/1280px-SR-71A_in_flight_near_Beale_AFB_1988.JPEG', 'TSgt. Michael Haggerty, USAF', 'Public domain', NULL, 'https://commons.wikimedia.org/wiki/File:SR-71A_in_flight_near_Beale_AFB_1988.JPEG', 'Q190114', 'Lockheed SR-71 Blackbird', ARRAY['lockheed sr-71 blackbird', 'blackbird', 'sr71 blackbird', 'rs-71 blackbird', 'sr-71 blackbird', 'lockheed sr-71', 'sr 71'], 'https://fr.wikipedia.org/wiki/Lockheed_SR-71_Blackbird', '{"first_flight":["https://www.smithsonianmag.com/smithsonian-institution/why-sr-71-blackbird-epitome-cold-war-spycraft-180953402/","https://www.lockheedmartin.com/en-us/news/features/history/blackbird.html","https://appel.nasa.gov/wp-content/uploads/2013/03/Blackbird-FAQ.pdf"],"max_speed_kmh":["https://www.nasa.gov/wp-content/uploads/2021/09/495839main_fs-030_sr-71.pdf","https://www.sr-71.org/blackbird/manual/5/5-9.php","https://aerotoolbox.com/airspeed-conversions/"],"length_m":["https://airandspace.si.edu/collection-objects/lockheed-sr-71-blackbird/nasm_A19920072000"],"wingspan_m":["https://airandspace.si.edu/collection-objects/lockheed-sr-71-blackbird/nasm_A19920072000"],"height_m":["https://airandspace.si.edu/collection-objects/lockheed-sr-71-blackbird/nasm_A19920072000"],"range_km":["https://pacificcoastairmuseum.org/aircraft/sr-71-blackbird-nose/"],"ceiling_m":["https://www.nasa.gov/centers/armstrong/news/FactSheets/FS-030-DFRC.html"],"units_built":["https://www.codeonemagazine.com/article.html?item_id=154","https://appel.nasa.gov/wp-content/uploads/2013/03/Blackbird-FAQ.pdf"],"service_entry":["https://www.codeonemagazine.com/article.html?item_id=153"],"retirement":["https://www.nasa.gov/centers/armstrong/news/FactSheets/FS-030-DFRC.html"]}'::jsonb, true),
  -- Su-25 (Q192137)
  ('sukhoi-su-25', 'Su-25', 'Soukhoï / Tbilisi Aircraft Manufacturing', 'militaire', 'Le Soukhoï Su-25 Gratch (en russe : Су-25 Грач, « corbeau freux » ; code OTAN Frogfoot) est un avion d''attaque au sol, de soutien aérien rapproché et de lutte antichar développé par l''URSS dans les années 1970. Il fut construit à plus d''un millier d''exemplaires et exporté dans de nombreux pays.', NULL, '1975-02-22', NULL, 14.5, 14.3, 4.95, 1000, 17000, '1981-01-01', NULL, 'Union soviétique / Russie', 'R-95Sh', 1320, 3, 'https://thumb.wikimedia.org/wikipedia/commons/thumb/b/b3/Su-25_in_flight_01.JPEG/1280px-Su-25_in_flight_01.JPEG', 'Unknown authorUnknown author', 'Public domain', NULL, 'https://commons.wikimedia.org/wiki/File:Su-25_in_flight_01.JPEG', 'Q192137', 'Sukhoi Su-25', ARRAY['sukhoi su-25', 'su-25', 'frogfoot', 'sukhoi su-25 frogfoot', 'soukhoï-25', 'soukhoï su-39', 'soukhoi su-25', 'soukhoï 25'], 'https://fr.wikipedia.org/wiki/Soukho%C3%AF_Su-25', '{"wingspan_m":["https://www.wikidata.org/wiki/Q29042798"],"units_built":["http://www.arms-expo.ru/site.xp/049049056053124049054052056.html"]}'::jsonb, true),
  -- Rockwell B-1 Lancer (Q218636)
  ('rockwell-b-1-lancer', 'Rockwell B-1 Lancer', 'Rockwell International / Boeing', 'militaire', 'Le Rockwell B-1 Lancer est un bombardier stratégique à long rayon d''action et à géométrie variable développé par les États-Unis dans les années 1970. Il a été construit, hors prototypes, à 100 exemplaires et 60 sont toujours en service en 2020, flotte passant à 45 à partir du 23 septembre 2021. Il est surnommé « The Bone » au sein de l''armée américaine, en référence à sa désignation « B-One » (« B-1 » en anglais).', NULL, '1974-12-23', NULL, 44.5, NULL, 10.4, 11997, NULL, '1986-10-01', NULL, 'États-Unis', 'General Electric F101', 100, 4, 'https://thumb.wikimedia.org/wikipedia/commons/thumb/5/50/B-1B.jpg/1280px-B-1B.jpg', 'Master Sgt. Andy Dunaway by U.S. Air Force', 'Public domain', NULL, 'https://commons.wikimedia.org/wiki/File:B-1B.jpg', 'Q218636', 'Rockwell B-1 Lancer', ARRAY['rockwell b-1 lancer', 'lancer', 'b-1 lancer', 'b-1', 'bone', 'the bone', 'b-1b'], 'https://fr.wikipedia.org/wiki/Rockwell_B-1_Lancer', '{"first_flight":["https://israelnoticias.com/militar/rockwell-b-1-lancer-historia-y-evolucion-del-bombardero/"]}'::jsonb, true),
  -- Mitsubishi A6M (Q40156)
  ('mitsubishi-a6m-zero', 'Mitsubishi A6M', 'Mitsubishi Heavy Industries', 'collection', 'Le Mitsubishi A6M est un chasseur-bombardier japonais léger embarqué utilisé par la Marine impériale japonaise de 1940 à 1945. Alors que le nom de code officiel utilisé du côté allié pour cet avion était Zeke, il était plus connu sous le nom de Zero dans la Marine impériale japonaise et sous la désignation complète de Chasseur embarqué de Type 0 (零式艦上戦闘機, rei shiki kanjō sentōki), officiellement abrégé en Rei-sen du côté japonais.', NULL, '1939-04-01', NULL, NULL, NULL, NULL, NULL, NULL, '1940-01-01', '1945-01-01', NULL, 'Nakajima Sakae', 11000, 1, 'https://thumb.wikimedia.org/wikipedia/commons/thumb/7/70/Mitsubishi_A6M_Zero_Replica.jpg/1280px-Mitsubishi_A6M_Zero_Replica.jpg', 'D. Miller', 'CC BY 2.0', 'https://creativecommons.org/licenses/by/2.0', 'https://commons.wikimedia.org/wiki/File:Mitsubishi_A6M_Zero_Replica.jpg', 'Q40156', 'Mitsubishi A6M Zero', ARRAY['mitsubishi a6m zero', 'mitsubishi a6m', 'navy type 0 carrier fighter', 'zero', 'type 0', 'reisen', 'zeke', 'mitsubishi carrier fighter design 6', 'a6m reisen', 'mitsubishi navy 12-shi carrier fighter', 'a6m zero', 'zéro', 'rufe', 'zero-sen', 'mitsubishi a6m2', 'a6m'], 'https://fr.wikipedia.org/wiki/Mitsubishi_A6M', '{}'::jsonb, true),
  -- Mikoyan-Gourevitch MiG-17 (Q152976)
  ('mikoyan-gurevich-mig-17', 'Mikoyan-Gourevitch MiG-17', 'Mikoyan-Gourevitch / république socialiste fédérative soviétique de Russie', 'collection', 'Le Mikoyan-Gourevitch MiG-17 (en russe : МиГ-17) est un chasseur soviétique mis en service en 1952. Il équipe les forces aériennes des pays du pacte de Varsoviedurant de nombreuses années et reçut le nom de code OTANde Fresco. Le MiG-17 est construit à plus de 6 000 exemplaires en URSS et est fabriqué sous licence en Pologne et en Chine. Son successeur est le MiG-19.', NULL, '1950-01-14', NULL, 11.36, 9.63, 3.8, NULL, 16600, '1951-01-01', '1970-01-01', 'Union soviétique', 'WP-5', 10649, 1, 'https://thumb.wikimedia.org/wikipedia/commons/thumb/1/1f/Wingsoverpgh_IMG_2448_%2834572173392%29.jpg/1280px-Wingsoverpgh_IMG_2448_%2834572173392%29.jpg', 'Clemens Vasters from Viersen, Germany, Germany', 'CC BY 2.0', 'https://creativecommons.org/licenses/by/2.0', 'https://commons.wikimedia.org/wiki/File:Wingsoverpgh_IMG_2448_(34572173392).jpg', 'Q152976', 'Mikoyan-Gurevich MiG-17', ARRAY['mikoyan-gurevich mig-17', 'mikoyan-gourevitch mig-17', 'fresco', 'mikoyan mig-17', 'mikoyan-gurevich fresco', 'mig-17', 'mig 17'], 'https://fr.wikipedia.org/wiki/Mikoyan-Gourevitch_MiG-17', '{"wingspan_m":["https://www.wikidata.org/wiki/Q29042798"]}'::jsonb, true),
  -- Lockheed U-2 (Q189064)
  ('lockheed-u-2', 'Lockheed U-2', 'Lockheed', 'militaire', 'Le Lockheed U-2 est un avion de reconnaissance qui a été utilisé de manière intensive durant la guerre froide par les États-Unis, notamment pour observer les territoires soviétiques. Ayant été modernisé, il est toujours en service, son retrait étant programmé selon les prévisions de 2023 durant l''année fiscale 2026.', NULL, '1955-08-01', NULL, NULL, NULL, NULL, NULL, NULL, '1956-06-20', NULL, 'États-Unis', NULL, 104, 4, 'https://thumb.wikimedia.org/wikipedia/commons/thumb/2/23/5th_Reconnaissance_Squadron_-_U-2_Osan.jpg/1280px-5th_Reconnaissance_Squadron_-_U-2_Osan.jpg', 'United States Air Force', 'Public domain', NULL, 'https://commons.wikimedia.org/wiki/File:5th_Reconnaissance_Squadron_-_U-2_Osan.jpg', 'Q189064', 'Lockheed U-2', ARRAY['lockheed u-2', 'u-2 spy plane', 'u-2 dragon lady', 'u-2 aircraft', 'dragon lady', 'u2 aircraft', 'lockheed tr-1', 'avion u2', 'avion u-2'], 'https://fr.wikipedia.org/wiki/Lockheed_U-2', '{"first_flight":["https://www.cia.gov/stories/story/area-51-and-the-accidental-test-flight/","https://www.beale.af.mil/News/Article-Display/Article/2186374/making-history-reserve-pilot-flies-the-u-2-for-the-first-time/"],"units_built":["https://www.nationalmuseum.af.mil/Visit/Museum-Exhibits/Fact-Sheets/Display/Article/197569/old-design-young-airplane/"],"service_entry":["https://www.wikidata.org/wiki/Q135179958"]}'::jsonb, true),
  -- Fairchild A-10 Thunderbolt II (Q192443)
  ('fairchild-republic-a-10-thunderbolt-ii', 'Fairchild A-10 Thunderbolt II', 'Fairchild Republic', 'militaire', 'Le Fairchild Republic A-10 Thunderbolt II, également connu sous le nom de « Warthog » (phacochère en anglais) ou « Hog », est un avion américain d''appui aérien rapproché, en service depuis 1975. Il fut spécialement conçu pour ce rôle durant la guerre du Vietnam à partir des leçons tirées de l''usage du Skyraider. Il est construit autour de son armement principal : le canon automatique de 30 mm GAU-8 Avenger. C''est un avion simple et rustique, qui peut utiliser des aérodromes rudimentaires.', NULL, '1972-05-10', NULL, 16.56, 17.53, NULL, NULL, NULL, '1977-01-01', NULL, 'États-Unis', 'General Electric TF34', 716, 3, 'https://upload.wikimedia.org/wikipedia/commons/1/1a/A10Thunderbolt2_990422-F-7910D-517.jpg', 'U.S. Air Force photo by Senior Airman Greg L. Davis', 'Public domain', NULL, 'https://commons.wikimedia.org/wiki/File:A10Thunderbolt2_990422-F-7910D-517.jpg', 'Q192443', 'Fairchild Republic A-10 Thunderbolt II', ARRAY['fairchild republic a-10 thunderbolt ii', 'fairchild a-10 thunderbolt ii', 'warthog', 'a10 thunderbolt ii', 'thunderbolt ii', 'a-10', 'fairchild thunderbolt ii', 'republic a-10 thunderbolt ii', 'a-10 warthog', 'a-10 thunderbolt ii', 'fairchild a-10 thunderbolt'], 'https://fr.wikipedia.org/wiki/Fairchild_A-10_Thunderbolt_II', '{"length_m":["https://www.wikidata.org/wiki/Q29042798"],"wingspan_m":["https://www.wikidata.org/wiki/Q29042798"]}'::jsonb, true),
  -- Antonov An-124 (Q193487)
  ('antonov-an-124-ruslan', 'Antonov An-124', 'Aviastar-SP / Aviant', 'militaire', 'L''Antonov An 124-100 surnommé Ruslan (Code OTAN : Condor) est le second plus gros avion du monde produit en série (le premier étant l''Airbus A380), l''avion le plus gros du monde hors série était l''Antonov An-225. Il permet de transporter les charges les plus diverses telles que locomotives, grues, satellites, bateaux. Cet avion est équipé de deux ponts roulants disposant chacun de deux palans pouvant supporter une masse maximale de 20 tonnes.', NULL, '1982-12-26', NULL, 69.1, 73.3, NULL, NULL, NULL, '1987-01-01', NULL, 'Union soviétique', 'Progress D-18T', 55, 4, 'https://upload.wikimedia.org/wikipedia/commons/b/b6/%D0%90%D0%BD%D1%82%D0%BE%D0%BD%D0%BE%D0%B2_%D0%90%D0%BD-124_9773054055093%2C_%D0%9C%D0%BE%D1%81%D0%BA%D0%B2%D0%B0_-_%D0%94%D0%BE%D0%BC%D0%BE%D0%B4%D0%B5%D0%B4%D0%BE%D0%B2%D0%BE_RP2297.jpg', 'Alex Beltyukov', 'CC BY-SA 3.0', 'https://creativecommons.org/licenses/by-sa/3.0', 'https://commons.wikimedia.org/wiki/File:%D0%90%D0%BD%D1%82%D0%BE%D0%BD%D0%BE%D0%B2_%D0%90%D0%BD-124_9773054055093,_%D0%9C%D0%BE%D1%81%D0%BA%D0%B2%D0%B0_-_%D0%94%D0%BE%D0%BC%D0%BE%D0%B4%D0%B5%D0%B4%D0%BE%D0%B2%D0%BE_RP2297.jpg', 'Q193487', 'Antonov An-124 Ruslan', ARRAY['antonov an-124 ruslan', 'antonov an-124', 'antonov an-124 condor', 'an124', 'ruslan', 'an-124', 'antonov 124', 'condor'], 'https://fr.wikipedia.org/wiki/Antonov_An-124', '{"length_m":["https://www.wikidata.org/wiki/Q29042798"],"wingspan_m":["https://www.wikidata.org/wiki/Q29042798"]}'::jsonb, true),
  -- Boeing 717 (Q6401)
  ('boeing-717', 'Boeing 717', 'Boeing', 'ligne', 'Le Boeing 717 est un avion de ligne construit par la société Boeing. Il s''agissait du plus petit appareil de sa gamme. Lancé en 1995 sous le nom de MD-95, c''était le dernier vestige de la marque McDonnell Douglas, rachetée par Boeing en 1997. À l''origine, le numéro 717 est attribué à l''avion ravitailleur KC-135 et ses dérivés ; toutefois, n''étant pas utilisé, il revient au MD-95.', NULL, '1998-09-02', NULL, 37.8, 28.47, 8.92, NULL, 11277, '1999-10-12', NULL, 'États-Unis', NULL, 156, 4, 'https://upload.wikimedia.org/wikipedia/commons/c/c3/Blue1_Boeing_717-200_OH-BLJ_ARN_2012-6-30.png', 'Alan Lebeda', 'GFDL 1.2', 'http://www.gnu.org/licenses/old-licenses/fdl-1.2.html', 'https://commons.wikimedia.org/wiki/File:Blue1_Boeing_717-200_OH-BLJ_ARN_2012-6-30.png', 'Q6401', 'Boeing 717', ARRAY['boeing 717', 'b717', 'md-95', '717', 'mcdonnell douglas md-95', 'md95', 'boeing 717-200', 'b-717'], 'https://fr.wikipedia.org/wiki/Boeing_717', '{"service_entry":["https://www.transponder1200.com/historia-del-boeing-717-el-ultimo-legado-de-mcdonnell-douglas/"]}'::jsonb, true),
  -- Airbus A310 (Q6471)
  ('airbus-a310', 'Airbus A310', 'Airbus Commercial Aircraft', 'ligne', 'L''Airbus A310 est un modèle d''avion de ligne long courrier biréacteur à fuselage large produit par le constructeur aéronautique Airbus de 1982 à 1998. Il se présente comme une version raccourcie de l''Airbus A300, mais s''en démarque par plusieurs innovations, notamment une voilure entièrement nouvelle aux performances aérodynamiques accrues, une électronique plus avancée permettant de se contenter de deux membres d''équipage, et un usage accru de matériaux composites.', NULL, '1982-04-03', NULL, 46.66, 43.9, 15.8, NULL, 12300, NULL, NULL, 'France / Allemagne', 'General Electric CF6 / JT9D', 255, 4, 'https://upload.wikimedia.org/wikipedia/commons/5/5d/Air_Transat_A310_%28C-GTSF%29_%40_LHR%2C_Aug_2009.jpg', 'Konstantin Von Wedelstaedt', 'GFDL 1.2', 'http://www.gnu.org/licenses/old-licenses/fdl-1.2.html', 'https://commons.wikimedia.org/wiki/File:Air_Transat_A310_(C-GTSF)_@_LHR,_Aug_2009.jpg', 'Q6471', 'Airbus A310', ARRAY['airbus a310', 'a300b10', 'a310'], 'https://fr.wikipedia.org/wiki/Airbus_A310', '{"wingspan_m":["https://www.wikidata.org/wiki/Q29042798"]}'::jsonb, true),
  -- F-86 Sabre (Q153826)
  ('north-american-f-86-sabre', 'F-86 Sabre', 'North American Aviation / Canadair', 'collection', 'Le North American F-86 Sabre est le premier avion de chasse à réaction et ailes en flèche conçu et construit par la société américaine North American, juste après la Seconde Guerre mondiale. Construit à plusieurs milliers d''exemplaires, cet appareil a été utilisé par une trentaine de pays. Son affrontement avec le MiG-15 pendant la guerre de Corée est un épisode notoire de l''histoire du combat aérien.', NULL, '1947-10-01', NULL, 11.4, 11.4, 4.5, 2454, NULL, '1949-01-01', '1994-01-01', 'États-Unis', NULL, 8740, 2, 'https://upload.wikimedia.org/wikipedia/commons/1/1e/F-86_Sabre_hertiage_flight.jpg', 'U.S. Air Force photo by J.M. Eddins Jr.', 'Public domain', NULL, 'https://commons.wikimedia.org/wiki/File:F-86_Sabre_hertiage_flight.jpg', 'Q153826', 'North American F-86 Sabre', ARRAY['north american f-86 sabre', 'f-86 sabre', 'sabre', 'f86', 'f-86d sabre', 'f-86'], 'https://fr.wikipedia.org/wiki/North_American_F-86_Sabre', '{}'::jsonb, true),
  -- Soukhoï Su-34 (Q309177)
  ('sukhoi-su-34', 'Soukhoï Su-34', 'Soukhoï / Novosibirsk Aircraft Production Association', 'militaire', 'Le Soukhoï Su-34 (désignation d''exportation : Su-32) (Code OTAN Fullback) est un bombardier tactique russe avec des capacités de lutte antinavire.', NULL, '1990-04-13', NULL, 23.3, 14.7, 6.09, NULL, NULL, '2014-03-21', NULL, 'Russie', 'Saturn AL-31', 143, 4, 'https://upload.wikimedia.org/wikipedia/commons/d/d6/Russian_Air_Force_Sukhoi_Su-34_Beltyukov-1.jpg', 'Alex Beltyukov', 'CC BY-SA 3.0', 'https://creativecommons.org/licenses/by-sa/3.0', 'https://commons.wikimedia.org/wiki/File:Russian_Air_Force_Sukhoi_Su-34_Beltyukov-1.jpg', 'Q309177', 'Sukhoi Su-34', ARRAY['sukhoi su-34', 'soukhoï su-34', 'fullback', 'su-32', 'sukhoi su-32', 'su-34', 'soukhoi su-34', 'sukhoï su-34'], 'https://fr.wikipedia.org/wiki/Soukho%C3%AF_Su-34', '{"units_built":["https://bmpd.livejournal.com/4103348.html"],"service_entry":["http://lenta.ru/news/2014/03/21/su34/"]}'::jsonb, true),
  -- Ju 87 (Q26795)
  ('junkers-ju-87', 'Ju 87', 'Junkers / Junkers Motorenbau und Junkers Flugzeugwerk', 'collection', 'Le Junkers Ju 87 est un bombardier en piqué de la Luftwaffe employé durant la Seconde Guerre mondiale. En allemand, « bombardier en piqué » se traduit par Sturzkampfflugzeug, composé de trois mots : « Sturz » (chute), « Kampf » (combat) et « Flugzeug » (avion), soit littéralement « avion de combat en piqué ».', NULL, '1935-09-17', NULL, NULL, 13.8, 4.01, NULL, NULL, '1937-01-01', '1945-01-01', NULL, NULL, 6500, 2, 'https://upload.wikimedia.org/wikipedia/commons/8/87/StukaRA.jpg', 'Andrea Nicola, Fotografia di mio padre, fotografo nella Regia Aeronautica nel periodo 1940/1942. --Elwood 00:43, 6 December 2005 (UTC)', 'CC BY-SA 3.0', 'http://creativecommons.org/licenses/by-sa/3.0/', 'https://commons.wikimedia.org/wiki/File:StukaRA.jpg', 'Q26795', 'Junkers Ju 87', ARRAY['junkers ju 87', 'ju 87', 'ju-87 stuka', 'ju87 stuka', 'junker 87', 'stuka'], 'https://fr.wikipedia.org/wiki/Junkers_Ju_87', '{}'::jsonb, true),
  -- Messerschmitt Me 262 (Q140254)
  ('messerschmitt-me-262', 'Messerschmitt Me 262', 'Messerschmitt', 'collection', 'Le Messerschmitt Me 262, surnommé Schwalbe (Hirondelle en français) pour les versions de combat ou Sturmvogel (Oiseau de tempête) pour les versions chasseur-bombardier, fut le premier avion de chasse opérationnel à moteur à réaction de l''Histoire, construit en série par la société allemande Messerschmitt pendant la Seconde Guerre mondiale. Les travaux de conception débutèrent avant le début de la Seconde Guerre mondiale.', NULL, '1942-07-18', NULL, 10.58, 12.5, 3.83, 1050, 11450, '1944-01-01', '1945-01-01', 'Reich allemand', 'Junkers Jumo 004', 1433, 3, 'https://upload.wikimedia.org/wikipedia/commons/a/a2/Me_262_flight_show_at_ILA_2006_%28cropped%29.jpg', 'Noop1958', 'GPLv3', 'http://www.gnu.org/licenses/gpl-3.0.html', 'https://commons.wikimedia.org/wiki/File:Me_262_flight_show_at_ILA_2006_(cropped).jpg', 'Q140254', 'Messerschmitt Me 262', ARRAY['messerschmitt me 262', 'messerschmitt me 262 schwalbe', 'me 262'], 'https://fr.wikipedia.org/wiki/Messerschmitt_Me_262', '{}'::jsonb, true),
  -- Republic P-47 Thunderbolt (Q207089)
  ('republic-p-47-thunderbolt', 'Republic P-47 Thunderbolt', 'Republic Aviation Company / Buffalo', 'collection', 'Le Republic P-47 Thunderbolt fut l''un des principaux chasseurs américains de la Seconde Guerre mondiale. Il est même l''avion de chasse américain le plus produit lors du conflit avec 15 660 exemplaires construits. Les pilotes américains le surnommèrent The Jug (« la cruche ») en raison de sa forme trapue évoquant un broc ou une cruche (stubby jug-like).', NULL, '1941-05-06', NULL, NULL, 12.42, 4.42, NULL, 13100, '1942-01-01', '1966-01-01', 'États-Unis', 'R-2800 Double Wasp', 15686, 1, 'https://thumb.wikimedia.org/wikipedia/commons/thumb/e/ea/P47_Thunderbolt_-_Chino_Airshow_2014.jpg/1280px-P47_Thunderbolt_-_Chino_Airshow_2014.jpg', 'Tim Felce', 'CC BY-SA 2.0', 'https://creativecommons.org/licenses/by-sa/2.0', 'https://commons.wikimedia.org/wiki/File:P47_Thunderbolt_-_Chino_Airshow_2014.jpg', 'Q207089', 'Republic P-47 Thunderbolt', ARRAY['republic p-47 thunderbolt', 'pursuit design 47', 'f-47 thunderbolt', 'republic thunderbolt', 'thunderbolt', 'p-47 thunderbolt', 'p-47'], 'https://fr.wikipedia.org/wiki/Republic_P-47_Thunderbolt', '{}'::jsonb, true),
  -- Antonov An-2 (Q207700)
  ('antonov-an-2', 'Antonov An-2', 'Hongdu', 'autre', 'L''An-2, aussi connu sous le nom de Kukuruznik, est un avion biplan monomoteur polyvalent conçu par le bureau constructeur Antonov. Il fit son premier vol le 31 août 1947 et fut produit à plus de 18 000 exemplaires en URSS, Pologne, Chine et Colombie.', NULL, '1947-08-31', NULL, 12.74, 18.18, NULL, NULL, NULL, '1947-01-01', NULL, 'Union soviétique', 'Shvetsov ASh-62IR', 18000, 1, 'https://thumb.wikimedia.org/wikipedia/commons/thumb/6/61/Antonov_An-2_OK-HFL_amk_%28cropped%29.jpg/1280px-Antonov_An-2_OK-HFL_amk_%28cropped%29.jpg', 'AngMoKio', 'CC BY-SA 3.0', 'https://creativecommons.org/licenses/by-sa/3.0', 'https://commons.wikimedia.org/wiki/File:Antonov_An-2_OK-HFL_amk_(cropped).jpg', 'Q207700', 'Antonov An-2', ARRAY['antonov an-2', 'an-2 colt', 'annie', 'antonov an-3', 'antonov an-4', 'antonov an-6', 'an-2'], 'https://fr.wikipedia.org/wiki/Antonov_An-2', '{"first_flight":["https://www.wikidata.org/wiki/Q15048646"],"length_m":["https://www.wikidata.org/wiki/Q29042798"],"wingspan_m":["https://www.wikidata.org/wiki/Q29042798"],"units_built":["http://ria.ru/infografika/20110831/427668887.html"]}'::jsonb, true),
  -- ATR 72 (Q219764)
  ('atr-72', 'ATR 72', 'Avions de transport régional', 'ligne', 'L''ATR 72 est un avion de transport de passagers à turbopropulseurs construit par ATR, société italo-française de type GIE entre Aérospatiale et Aeritalia. Cette version allongée de l''ATR 42, pouvant accueillir jusqu''à 78 passagers, a été mise en service en 1989. Il est disponible en version tout cargo 75 m3, 8 400 kg.', NULL, '1988-10-27', NULL, NULL, NULL, NULL, NULL, NULL, '1989-10-27', NULL, 'France / Italie', 'Pratt & Whitney Canada PW100', 1500, 3, 'https://upload.wikimedia.org/wikipedia/commons/9/9e/ATR_ATR-72-202%2C_LOT_-_Polish_Airlines_-_Polskie_Linie_Lotnicze_%28EuroLOT%29_AN2020929.jpg', 'Konstantin von Wedelstaedt', 'GFDL 1.2', 'http://www.gnu.org/licenses/old-licenses/fdl-1.2.html', 'https://commons.wikimedia.org/wiki/File:ATR_ATR-72-202,_LOT_-_Polish_Airlines_-_Polskie_Linie_Lotnicze_(EuroLOT)_AN2020929.jpg', 'Q219764', 'ATR 72', ARRAY['atr 72', 'atr-72', 'atr72'], 'https://fr.wikipedia.org/wiki/ATR_72', '{"units_built":["https://www.aerotelegraph.com/atr-in-37-jahren-von-0-auf-1500"]}'::jsonb, true),
  -- Boeing F/A-18E/F Super Hornet (Q223318)
  ('boeing-f-a-18e-f-super-hornet', 'Boeing F/A-18E/F Super Hornet', 'McDonnell Douglas / Boeing Integrated Defense Systems', 'militaire', 'Le Boeing F/A-18E et F/A-18F Super Hornet est un chasseur de combat multirôle américain dérivé du McDonnell Douglas F/A-18 Hornet. Embarqué à bord de porte-avions de l''US Navy, il est également en service au sein de la Force aérienne royale australienne.', NULL, '1995-11-29', NULL, NULL, NULL, NULL, NULL, NULL, '2001-09-01', NULL, 'États-Unis', NULL, NULL, 3, 'https://thumb.wikimedia.org/wikipedia/commons/thumb/a/ae/081102-N-0000C-002.jpg/1280px-081102-N-0000C-002.jpg', 'U.S. Navy photo by Lt. Adam Cohen/Released', 'Public domain', NULL, 'https://commons.wikimedia.org/wiki/File:081102-N-0000C-002.jpg', 'Q223318', 'Boeing F/A-18E/F Super Hornet', ARRAY['boeing f/a-18 super hornet', 'boeing f/a-18e/f super hornet', 'boeing f/a-18e/f', 'f/a-18e/f', 'f/a-18e/f super hornet', 'super hornet', 'f/a-18 super hornet', 'rhino'], 'https://fr.wikipedia.org/wiki/Boeing_F/A-18E/F_Super_Hornet', '{}'::jsonb, true),
  -- Lockheed P-38 Lightning (Q172913)
  ('lockheed-p-38-lightning', 'Lockheed P-38 Lightning', 'Lockheed', 'collection', 'Le Lockheed P-38 Lightning est un avion militaire de la Seconde Guerre mondiale conçu par Hall Hibbard et Clarence Johnson pour l''avionneur américain Lockheed. Doté d''une silhouette inhabituelle en raison de sa conception bimoteur bipoutre à nacelle centrale contenant le cockpit et l''armement, il est développé comme intercepteur à long rayon d''action et utilisé pendant le conflit mondial pour la chasse, l''escorte à longue distance de bombardiers, l''attaque au sol, la photographie aérienne.', NULL, '1939-01-27', NULL, 11.53, 15.85, 3, NULL, NULL, '1943-01-01', '1949-01-01', 'États-Unis', NULL, 10037, 1, 'https://upload.wikimedia.org/wikipedia/commons/f/f7/Lockheed_P-38J_Lightning%2C_Chino%2C_California.jpg', 'Greg Goebel', 'CC BY-SA 2.0', 'https://creativecommons.org/licenses/by-sa/2.0', 'https://commons.wikimedia.org/wiki/File:Lockheed_P-38J_Lightning,_Chino,_California.jpg', 'Q172913', 'Lockheed P-38 Lightning', ARRAY['lockheed p-38 lightning', 'pursuit design 38', 'lightning', 'lockheed lightning', 'lockheed f-5 lightning', 'p-38', 'p-38 lightning'], 'https://fr.wikipedia.org/wiki/Lockheed_P-38_Lightning', '{}'::jsonb, true),
  -- Mikoyan-Gourevitch MiG-19 (Q153307)
  ('mikoyan-gurevich-mig-19', 'Mikoyan-Gourevitch MiG-19', 'Mikoyan-Gourevitch / Sokol', 'militaire', 'Le Mikoyan-Gourevitch MiG-19 (code OTAN : Farmer) est un avion de combat de troisième génération conçu par l''URSS. Biréacteur à ailes en flèches, il a été construit à plusieurs milliers d''exemplaires, principalement sous licence par la Chine utilisé par la Force aérienne de l''Armée populaire de libération, et largement exporté. Il s''agit du premier avion de production soviétique capable d''atteindre des vitesses supersoniques en vol horizontal.', NULL, '1953-09-18', NULL, 12.54, 9, 3.88, NULL, 15600, '1955-01-01', NULL, NULL, 'RD-9B', 6500, 2, 'https://thumb.wikimedia.org/wikipedia/commons/thumb/e/ed/0312_a_MiG-19S_preserved_at_Horni_Nemci_Czech_Republic_%283117339353%29.jpg/1280px-0312_a_MiG-19S_preserved_at_Horni_Nemci_Czech_Republic_%283117339353%29.jpg', 'Jerry Gunner from Lincoln, UK', 'CC BY 2.0', 'https://creativecommons.org/licenses/by/2.0', 'https://commons.wikimedia.org/wiki/File:0312_a_MiG-19S_preserved_at_Horni_Nemci_Czech_Republic_(3117339353).jpg', 'Q153307', 'Mikoyan-Gurevich MiG-19', ARRAY['mikoyan-gurevich mig-19', 'mikoyan-gourevitch mig-19', 'mikoyan mig-19', 'mig-19 farmer', 'mikoyan-gurevich farmer', 'mikoyan-gurevich 19', 'farmer', 'mikoyan-gourevitch mig-19 farmer'], 'https://fr.wikipedia.org/wiki/Mikoyan-Gourevitch_MiG-19', '{"wingspan_m":["https://www.wikidata.org/wiki/Q29042798"]}'::jsonb, true),
  -- Junkers Ju 88 (Q155661)
  ('junkers-ju-88', 'Junkers Ju 88', 'Junkers / Junkers Motorenbau und Junkers Flugzeugwerk', 'collection', 'Le Junkers Ju 88 fut l''avion le plus polyvalent de la Luftwaffe, utilisé selon ses versions pour le bombardement horizontal ou en piqué, le torpillage, la chasse lourde (destroyer) et la chasse de nuit, la reconnaissance, l''entraînement ainsi qu''a la détection radar des navires. Il a été conçu en Allemagne en 1935 par Junkers et mis en production en 1939 en tant que bombardier moyen et rapide. Un total de 14 676 Ju 88 furent produits de 1936 à 1945, dont 104 prototypes.', NULL, '1936-12-21', NULL, 15.5, 20.08, 5.07, 2500, 9900, '1939-09-01', '1951-01-01', 'Reich allemand', NULL, 14882, 1, 'https://upload.wikimedia.org/wikipedia/commons/f/f4/Bundesarchiv_Bild_101I-417-1766-03A%2C_Flugzeug_Junkers_Ju_88.jpg', 'Ellerbrock', 'CC BY-SA 3.0 de', 'https://creativecommons.org/licenses/by-sa/3.0/de/deed.en', 'https://commons.wikimedia.org/wiki/File:Bundesarchiv_Bild_101I-417-1766-03A,_Flugzeug_Junkers_Ju_88.jpg', 'Q155661', 'Junkers Ju 88', ARRAY['junkers ju 88', 'junkers ju 88 g', 'ju-88', 'ju 88'], 'https://fr.wikipedia.org/wiki/Junkers_Ju_88', '{}'::jsonb, true),
  -- Boeing C-17 Globemaster III (Q211369)
  ('boeing-c-17-globemaster-iii', 'Boeing C-17 Globemaster III', 'Boeing / McDonnell Douglas', 'militaire', 'Le C-17 Globemaster III est un avion de transport (de matériel principalement) construit par McDonnell Douglas (qui fusionne avec Boeing en 1997 conduisant à l''appellation officielle de Boeing C-17A) au début des années 1990. Il est utilisé par l''United States Air Force, la Royal Air Force, la Royal Australian Air Force, l''Aviation Royale du Canada, la force aérienne indienne, la Force aérienne koweïtienne, l''OTAN et le Qatar.', NULL, '1991-09-15', NULL, 53, 52, 16.79, NULL, 14000, '1995-01-17', NULL, 'États-Unis', NULL, 279, 4, 'https://thumb.wikimedia.org/wikipedia/commons/thumb/d/d3/C-17_4.jpg/1280px-C-17_4.jpg', 'Technical Sergeant James E. Lotz', 'Public domain', NULL, 'https://commons.wikimedia.org/wiki/File:C-17_4.jpg', 'Q211369', 'Boeing C-17 Globemaster III', ARRAY['boeing c-17 globemaster iii', 'mcdonnell douglas c-17', 'c17', 'globemaster iii', 'globemaster 3', 'c-17', 'c 17', 'cc-177', 'boeing c-17', 'c-17 globemaster iii', 'mcdonnell-douglas c-17 globemaster iii'], 'https://fr.wikipedia.org/wiki/McDonnell_Douglas_C-17_Globemaster_III', '{}'::jsonb, true),
  -- Il-2 Sturmovik (Q211443)
  ('ilyushin-il-2', 'Il-2 Sturmovik', 'Iliochine', 'collection', 'L''Iliouchine Il-2 Chtourmovik (ou Šturmovik, en russe : Ильюшин ИЛ-2 Штурмовик) était l''un des meilleurs avions d''attaque au sol de la Seconde Guerre mondiale et il fut produit par l''URSS en grande quantité : plus de 36 163 exemplaires, ce qui constitue le record absolu de production pour un appareil militaire. Il fut surnommé « le Bossu » par les Soviétiques et « la Mort noire » par les Allemands.', NULL, '1939-10-02', NULL, NULL, NULL, NULL, NULL, NULL, '1941-01-01', '1954-01-01', NULL, 'Mikulin AM-38', 36163, 1, 'https://thumb.wikimedia.org/wikipedia/commons/thumb/d/d1/Ilyushin_Il-2M3_-_%D0%98%D0%BB%D1%8C%D1%8E%D1%88%D0%B8%D0%BD_%D0%98%D0%BB-2M3_30May1945_over_Berlin.png/1280px-Ilyushin_Il-2M3_-_%D0%98%D0%BB%D1%8C%D1%8E%D1%88%D0%B8%D0%BD_%D0%98%D0%BB-2M3_30May1945_over_Berlin.png', 'Umeyou', 'CC BY-SA 3.0', 'https://creativecommons.org/licenses/by-sa/3.0', 'https://commons.wikimedia.org/wiki/File:Ilyushin_Il-2M3_-_%D0%98%D0%BB%D1%8C%D1%8E%D1%88%D0%B8%D0%BD_%D0%98%D0%BB-2M3_30May1945_over_Berlin.png', 'Q211443', 'Ilyushin Il-2', ARRAY['ilyushin il-2 shturmovik', 'il-2 sturmovik', 'ilyushin il-2', 'ilyusha', 'shturmovik', 'hunchback', 'flying tank', 'flying infantryman', 'bark', 'bark aircraft', 'il-2 aircraft', 'ilyushin shturmovik', 'il-2', 'iliouchine il-2 sturmovik', 'sturmovik', 'iliouchine il-2'], 'https://fr.wikipedia.org/wiki/Iliouchine_Il-2', '{}'::jsonb, true),
  -- Airbus A300-600ST Beluga (Q6486)
  ('airbus-beluga', 'Airbus A300-600ST Beluga', 'Airbus Commercial Aircraft / EADS CASA', 'ligne', 'L''Airbus A300-600ST, également connu sous le surnom de Beluga en raison de sa forme ou encore Super Transporter, est un avion-cargo construit entre 1992 et 2000 par Airbus. Dérivé de l''avion de ligne A300-600R, le Beluga peut, grâce à sa soute de 37,7 m de long et 7,1 m de diamètre, emporter une charge de plus de 40 tonnes sur une distance maximale de 2 779 km.', NULL, '1994-09-13', 865, 56.15, 44.84, 17.24, 2779, 10668, '1995-10-01', NULL, 'France', 'General Electric CF6-80C2', 5, 5, 'https://thumb.wikimedia.org/wikipedia/commons/thumb/0/02/Airbus_Beluga_Airbus_A300B4-608ST_F-GSTA_%2828858044414%29.jpg/1280px-Airbus_Beluga_Airbus_A300B4-608ST_F-GSTA_%2828858044414%29.jpg', 'Brian Bukowski', 'CC BY-SA 2.0', 'https://creativecommons.org/licenses/by-sa/2.0', 'https://commons.wikimedia.org/wiki/File:Airbus_Beluga_Airbus_A300B4-608ST_F-GSTA_(28858044414).jpg', 'Q6486', 'Airbus Beluga', ARRAY['airbus a300-600st beluga', 'airbus beluga', 'a300 beluga', 'a300-600st', 'beluga', 'airbus a300f4-600st', 'airbus a300f4-608st', 'a300-608st', 'a300f4-608st', 'super transporter', 'airbus a300-600st'], 'https://fr.wikipedia.org/wiki/Airbus_A300-600ST', '{"first_flight":["https://www.cnn.com/travel/article/inside-airbus-beluga"],"max_speed_kmh":["https://airmacs.com/aircraft-guide/beluga-st/"],"length_m":["http://www.airbus.com/en/aircraftfamilies/beluga/specifications"],"wingspan_m":["http://www.airbus.com/en/aircraftfamilies/beluga/specifications"],"height_m":["http://www.airbus.com/en/aircraftfamilies/beluga/specifications"],"range_km":["http://www.airbus.com/en/aircraftfamilies/beluga/specifications"],"ceiling_m":["http://easa.europa.eu/system/files/dfu/EASA-TCDS-A.014_A300--600ST_Beluga-03-05052010.pdf"],"units_built":["https://www.cnn.com/travel/article/inside-airbus-beluga","https://newatlas.com/go/4199/"],"service_entry":["http://easa.europa.eu/system/files/dfu/EASA-TCDS-A.0