  -- Tupolev Tu-134 (Q159067)
  ('tupolev-tu-134', 'Tupolev Tu-134', 'Tupolev / KhAZ', 'ligne', 'Le Tupolev Tu-134 (Code OTAN Crusty) est un avion civil biréacteur soviétique, similaire au Douglas DC-9 américain. Il était l''un des avions les plus utilisés par les pays du pacte de Varsovie. Le nombre de ces aéronefs actuellement en service est en diminution à cause des normes de limitation des nuisances sonores ; le dernier vol commercial de cet avion a eu lieu le 22 mai 2019.', NULL, '1963-07-29', NULL, 34.35, 29, NULL, NULL, NULL, '1967-01-01', NULL, 'Union soviétique', 'Soloviev D-30', 854, 3, 'https://upload.wikimedia.org/wikipedia/commons/b/bc/Tupolev_Tu-134_of_Aviogenex.jpg', 'Eduard Marmet', 'CC BY-SA 3.0', 'http://creativecommons.org/licenses/by-sa/3.0/', 'https://commons.wikimedia.org/wiki/File:Tupolev_Tu-134_of_Aviogenex.jpg', 'Q159067', 'Tupolev Tu-134', ARRAY['tupolev tu-134', 'crusty', 'tupolev tu-134 crusty', 'tu 134', 'tu-134'], 'https://fr.wikipedia.org/wiki/Tupolev_Tu-134', '{"length_m":["https://www.wikidata.org/wiki/Q29042798"],"wingspan_m":["https://www.wikidata.org/wiki/Q29042798"],"units_built":["http://russianplanes.net/planelist/Tupolev/Tu-134"]}'::jsonb, true),
  -- Mikoyan-Gourevitch MiG-35 (Q220529)
  ('mikoyan-mig-35', 'Mikoyan-Gourevitch MiG-35', 'Mikoyan-Gourevitch / Sokol', 'militaire', 'Le Mikoyan-Gourevitch MiG-35 (en russe : « Микоян МиГ-35 »), de son nom de code OTAN « Fulcrum-F », est un avion militaire russe multirôle conçu par Mikoyan-Gourevitch. 5 des avions de combat.', NULL, '2007-02-07', NULL, 19, 15, 6, NULL, 17500, '2019-06-17', NULL, 'Russie', 'Klimov RD-33', 6, 5, 'https://upload.wikimedia.org/wikipedia/commons/e/e7/Mikoyan-Gurevich_MiG-35_MAKS%272007_Pichugin.jpg', 'Dmitriy Pichugin', 'GFDL 1.2', 'http://www.gnu.org/licenses/old-licenses/fdl-1.2.html', 'https://commons.wikimedia.org/wiki/File:Mikoyan-Gurevich_MiG-35_MAKS%272007_Pichugin.jpg', 'Q220529', 'Mikoyan MiG-35', ARRAY['mikoyan mig-35', 'mikoyan-gourevitch mig-35', 'mig-35 fulcrum-f', 'fulcrum-f', 'mikoyan-gurevich mig-35', 'mig-35 (stíhací letadla)', 'mig 35', 'mig-35'], 'https://fr.wikipedia.org/wiki/Mikoyan-Gourevitch_MiG-35', '{"units_built":["https://ria.ru/20210312/istrebiteli-1600916383.html"]}'::jsonb, true),
  -- Cessna 172 Skyhawk (Q244479)
  ('cessna-172', 'Cessna 172 Skyhawk', 'Cessna', 'autre', 'Le Cessna 172 Skyhawk est un avion de tourisme monomoteur à quatre places, construit par la société Cessna depuis 1955. C''est l''avion le plus populaire au monde par le nombre d''exemplaires produits, plus de 44 000 en 2017 et plus de 45 000 en 2023.', NULL, '1955-01-01', NULL, 8.2, 10.92, NULL, NULL, NULL, '1956-01-01', NULL, 'États-Unis', NULL, 44000, 1, 'https://thumb.wikimedia.org/wikipedia/commons/thumb/c/ca/Cessna_172S_Skyhawk_%E2%80%98G-JMKE%E2%80%99_%2845077563364%29.jpg/1280px-Cessna_172S_Skyhawk_%E2%80%98G-JMKE%E2%80%99_%2845077563364%29.jpg', 'Alan Wilson from Stilton, Peterborough, Cambs, UK', 'CC BY-SA 2.0', 'https://creativecommons.org/licenses/by-sa/2.0', 'https://commons.wikimedia.org/wiki/File:Cessna_172S_Skyhawk_%E2%80%98G-JMKE%E2%80%99_(45077563364).jpg', 'Q244479', 'Cessna 172', ARRAY['cessna 172 skyhawk', 'cessna 172', 'cessna skyhawk', 'skyhawk', '172 skyhawk', 'c172', 'cessna model 172 skyhawk'], 'https://fr.wikipedia.org/wiki/Cessna_172', '{"length_m":["https://www.wikidata.org/wiki/Q29042798"],"wingspan_m":["https://www.wikidata.org/wiki/Q29042798"]}'::jsonb, true),
  -- Heinkel He 111 (Q154532)
  ('heinkel-he-111', 'Heinkel He 111', 'Heinkel / Arado Flugzeugwerke GmbH', 'collection', 'Le Heinkel He 111 est un avion allemand de la Seconde Guerre mondiale construit par la société Ernst Heinkel Flugzeugwerke à Rostock, et qui vit le jour à l''époque de la renaissance clandestine de la Luftwaffe. C''est un bimoteur développé comme bombardier, mais aussi comme avion de ligne pouvant transporter dans cette version dix passagers en plus des quatre hommes d''équipage. L''expérience acquise avec le Heinkel He 70 fut déterminante pour le développement du He 111.', NULL, '1935-02-24', NULL, 16.39, 22.6, 4, 2000, 8500, '1936-01-01', '1945-01-01', 'Allemagne', 'Junkers Jumo 211', 6508, 2, 'https://upload.wikimedia.org/wikipedia/commons/c/cc/Bundesarchiv_Bild_101I-343-0694-21%2C_Belgien-Frankreich%2C_Flugzeug_Heinkel_He_111.jpg', 'Schödl (e)', 'CC BY-SA 3.0 de', 'https://creativecommons.org/licenses/by-sa/3.0/de/deed.en', 'https://commons.wikimedia.org/wiki/File:Bundesarchiv_Bild_101I-343-0694-21,_Belgien-Frankreich,_Flugzeug_Heinkel_He_111.jpg', 'Q154532', 'Heinkel He 111', ARRAY['heinkel he 111', 'heinkel he-111', 'he-111', 'he 111', 'heinkel 111'], 'https://fr.wikipedia.org/wiki/Heinkel_He_111', '{}'::jsonb, true),
  -- Mikoyan-Gourevitch MiG-3 (Q271446)
  ('mikoyan-gurevich-mig-3', 'Mikoyan-Gourevitch MiG-3', 'Mikoyan-Gourevitch / centre national de recherche et de production Progress', 'collection', 'Le Mikoyan-Gourevitch MiG-3 (en russe : Микоян-Гуревич МиГ-3) constitue, avec le MiG-1, le premier avion conçu par le bureau d''étude des ingénieurs Artem Mikoyan et Mikhaïl Gourevitch. C''est pour la conception et la mise en production de cette famille de chasseurs soviétiques que fut formé le futur OKB MiG. Leur premier essai fut réussi car l''avion connut une production importante.', NULL, '1940-01-01', NULL, 8.25, 10.2, 3.3, 820, 12000, '1940-01-01', '1943-01-01', 'Union soviétique', 'ASh-82', 3172, 2, 'https://upload.wikimedia.org/wikipedia/commons/c/c0/Mikoyan-Gurevich_MiG-3_%28MAKS-2007%29_cropped.jpg', 'МиГ-3_в_полете_(МАКС-2007).jpg: Россин Денис derivative work: Threecharlie (talk)', 'Public domain', NULL, 'https://commons.wikimedia.org/wiki/File:Mikoyan-Gurevich_MiG-3_(MAKS-2007)_cropped.jpg', 'Q271446', 'Mikoyan-Gurevich MiG-3', ARRAY['mikoyan-gurevich mig-3', 'mikoyan-gourevitch mig-3', 'mig-3', 'mikoyan mig-3', 'mikoyan-gurevitch mig-3'], 'https://fr.wikipedia.org/wiki/Mikoyan-Gourevitch_MiG-3', '{}'::jsonb, true),
  -- Airbus A400M Atlas (Q6496)
  ('airbus-a400m-atlas', 'Airbus A400M Atlas', 'Airbus Military', 'militaire', 'L''Airbus A400M Atlas est un avion de transport militaire polyvalent conçu par Airbus Defence and Space, entré en service en 2013. Au 30 novembre 2022, il totalise 178 commandes dont 115 livrées. Le projet sélectionné en 2000 à l''issue d''un appel d''offres a connu de nombreux retards et surcoûts. Assemblé à Séville, il sort d''usine en juin 2008 mais ne sera finalement certifié pour un usage militaire qu''en août 2013.', NULL, '2009-12-11', 750, 45.1, 42.36, 14.7, 3300, 11275, '2013-01-01', NULL, 'France / Allemagne', 'Europrop International TP400', 80, 4, 'https://thumb.wikimedia.org/wikipedia/commons/thumb/7/74/EC-402_-_A400M_-_Airbus_industrie_-_TLS_-_En_finale_sur_32L_-_04550-2.jpg/1280px-EC-402_-_A400M_-_Airbus_industrie_-_TLS_-_En_finale_sur_32L_-_04550-2.jpg', 'Dval027', 'CC BY-SA 3.0', 'https://creativecommons.org/licenses/by-sa/3.0', 'https://commons.wikimedia.org/wiki/File:EC-402_-_A400M_-_Airbus_industrie_-_TLS_-_En_finale_sur_32L_-_04550-2.jpg', 'Q6496', 'Airbus A400M Atlas', ARRAY['airbus a400m atlas', 'a400m atlas', 'a-400m', 'a400m'], 'https://fr.wikipedia.org/wiki/Airbus_A400M_Atlas', '{"service_entry":["http://www.lenta.ru/news/2012/04/17/a400m/"]}'::jsonb, true),
  -- Lockheed C-5 Galaxy (Q182012)
  ('lockheed-c-5-galaxy', 'Lockheed C-5 Galaxy', 'Lockheed Martin', 'militaire', 'Le Lockheed C-5 Galaxy est un avion de transport militaire lourd de l''Armée de l''air des États-Unis conçu par le constructeur aéronautique américain Lockheed. Sa vocation est le transport à longue distance de charges très lourdes, pour le soutien logistique d''un corps expéditionnaire. Il est capable d''emporter pratiquement tous les équipements des forces armées américaines, dont des chars de bataille, des engins de génie, des hélicoptères et même des sous-marins de sauvetage.', NULL, '1968-06-30', NULL, 75.3, 67.89, 19.84, NULL, NULL, '1970-06-01', NULL, 'États-Unis', NULL, 131, 4, 'https://thumb.wikimedia.org/wikipedia/commons/thumb/e/e6/C5_galaxy.jpg/1280px-C5_galaxy.jpg', 'U.S. Air Force photo by Tech. Sgt. Charlie Miller', 'Public domain', NULL, 'https://commons.wikimedia.org/wiki/File:C5_galaxy.jpg', 'Q182012', 'Lockheed C-5 Galaxy', ARRAY['lockheed c-5 galaxy', 'l500', 'galaxy', 'l-500', 'lockheed galaxy', 'c-5 galaxy'], 'https://fr.wikipedia.org/wiki/Lockheed_C-5_Galaxy', '{}'::jsonb, true),
  -- Avro Lancaster (Q203622)
  ('avro-lancaster', 'Avro Lancaster', 'Avro', 'collection', 'L''Avro 683 Lancaster (familièrement appelé Lanc) est un bombardier quadrimoteur de la Seconde Guerre mondiale, initialement produit par la société Avro pour l''armée de l''air britannique. Entré en service en 1942, il est construit à plus de 7 000 exemplaires et est, avec le Handley Page Halifax, le Short Stirling et le Vickers Wellington, le principal bombardier de la Royal Air Force durant cette période. Il se rend célèbre pour ses bombardements de nuit.', NULL, '1941-01-09', NULL, 21.11, 31.09, 5.94, NULL, 7500, NULL, NULL, 'Royaume-Uni', 'Rolls-Royce Merlin', 7377, 2, 'https://thumb.wikimedia.org/wikipedia/commons/thumb/f/f5/The_Royal_Air_Force_in_Britain%2C_29_September_1942_TR197.jpg/1280px-The_Royal_Air_Force_in_Britain%2C_29_September_1942_TR197.jpg', 'Royal Air Force official photographer', 'Public domain', NULL, 'https://commons.wikimedia.org/wiki/File:The_Royal_Air_Force_in_Britain,_29_September_1942_TR197.jpg', 'Q203622', 'Avro Lancaster', ARRAY['avro lancaster', 'avro 683 lancaster', 'lancaster aircraft', 'lancaster bomber'], 'https://fr.wikipedia.org/wiki/Avro_Lancaster', '{}'::jsonb, true),
  -- Curtiss P-40 Warhawk (Q206409)
  ('curtiss-p-40-warhawk', 'Curtiss P-40 Warhawk', 'Curtiss-Wright Corporation', 'collection', 'Le Curtiss P-40 Warhawk fut le troisième avion de chasse le plus produit des États-Unis pendant la Seconde Guerre mondiale. Dernier développement de la série des chasseurs Hawk de Curtiss, il vola pour la première fois en 1938. Il traîne une réputation d''avion de chasse dépassé et surclassé par ses adversaires, ce qui provoqua même une enquête après la Seconde Guerre mondiale, visant à déterminer pourquoi il avait été maintenu en production envers et contre tout.', NULL, '1938-10-14', NULL, 9.66, 11.38, 3.76, 1100, NULL, '1938-01-01', '1958-01-01', NULL, 'Allison V-1710', 13738, 1, 'https://thumb.wikimedia.org/wikipedia/commons/thumb/8/8c/Curtiss_P-40_Warhawk_airshow.jpg/1280px-Curtiss_P-40_Warhawk_airshow.jpg', '"TMWolf"', 'CC BY-SA 2.0', 'https://creativecommons.org/licenses/by-sa/2.0', 'https://commons.wikimedia.org/wiki/File:Curtiss_P-40_Warhawk_airshow.jpg', 'Q206409', 'Curtiss P-40 Warhawk', ARRAY['curtiss p-40 warhawk', 'warhawk', 'p-40 warhawk', 'curtiss warhawk', 'warhawk aircraft', 'pursuit design 40', 'curtiss p-40', 'p-40', 'p40', 'p 40'], 'https://fr.wikipedia.org/wiki/Curtiss_P-40_Warhawk', '{}'::jsonb, true),
  -- Mosquito (Q221344)
  ('de-havilland-mosquito', 'Mosquito', 'De Havilland Aircraft Company', 'collection', 'Le de Havilland Mosquito (en français : « Moustique », en rappel de la fonction de harcèlement initialement prévue pour cet appareil) est un avion multirôle britannique qui s''est distingué en tant que chasseur-bombardier. Il a servi au sein de la Royal Air Force et de nombreuses forces aériennes durant la Seconde Guerre mondiale et l’après-guerre.', NULL, '1940-11-25', NULL, 13.57, 16.52, 5.3, 2400, NULL, '1941-01-01', '1953-01-01', 'Royaume-Uni', NULL, 7781, 2, 'https://thumb.wikimedia.org/wikipedia/commons/thumb/0/03/RAF_Mosquito_with_Molins_gun_WWII_IWM_CH_14114.jpg/1280px-RAF_Mosquito_with_Molins_gun_WWII_IWM_CH_14114.jpg', 'Royal Air Force official photographer : Forward (Fg Off)', 'Public domain', NULL, 'https://commons.wikimedia.org/wiki/File:RAF_Mosquito_with_Molins_gun_WWII_IWM_CH_14114.jpg', 'Q221344', 'De Havilland Mosquito', ARRAY['de havilland mosquito', 'mosquito', 'wooden wonder', 'mossie', 'de havilland dh.98 mosquito', 'dh.98 mosquito', 'dh 98 mosquito'], 'https://fr.wikipedia.org/wiki/De_Havilland_DH.98_Mosquito', '{}'::jsonb, true),
  -- Airbus A220 (Q426074)
  ('airbus-a220', 'Airbus A220', 'Airbus Canada', 'ligne', 'L''Airbus A220, initialement Bombardier CSeries, est un avion de ligne civil moyen-courrier à cinq sièges de front conçu par l''avionneur canadien Bombardier Aéronautique en 2012 et produit par Airbus depuis 2020. Entré en service commercial le 15 juillet 2016, la série comporte deux modèles : le BD-500-1A10 (CS100) de 110 places et le BD-500-1A11 (CS300) de 135 places.', NULL, '2015-02-27', NULL, NULL, NULL, NULL, NULL, NULL, '2016-07-15', NULL, 'Canada', 'Pratt & Whitney PW1000G', 455, 4, 'https://thumb.wikimedia.org/wikipedia/commons/thumb/8/8c/Airbus_A220-300.jpg/1280px-Airbus_A220-300.jpg', 'Romain COUPY', 'CC BY-SA 4.0', 'https://creativecommons.org/licenses/by-sa/4.0', 'https://commons.wikimedia.org/wiki/File:Airbus_A220-300.jpg', 'Q426074', 'Airbus A220', ARRAY['airbus a220', 'bombardier cs100', 'bombardier cs300', 'bombardier cseries', 'a220'], 'https://fr.wikipedia.org/wiki/Airbus_A220', '{"units_built":["https://www.airbus.com/en/products-services/commercial-aircraft/orders-and-deliveries"]}'::jsonb, true),
  -- McDonnell Douglas DC-10 (Q208075)
  ('mcdonnell-douglas-dc-10', 'McDonnell Douglas DC-10', 'McDonnell Douglas', 'ligne', 'Le McDonnell Douglas DC-10 est un avion tri-réacteur long-courrier produit entre 1968 et 1989 par le constructeur aéronautique américain McDonnell Douglas. Le DC-10 est le successeur du long-courrier Douglas DC-8. Son premier vol a lieu le 29 août 1970 avant sa mise en service par American Airlines le 5 août 1971. Sa production cesse en 1989 après un total de 386 exemplaires sortis d''usine ainsi que de 60 KC-10, un modèle ravitailleur construit pour l''US Air Force.', NULL, '1970-08-29', NULL, 51.97, 50.4, 17.7, NULL, 12802, '1971-08-05', NULL, 'États-Unis', NULL, 446, 4, 'https://upload.wikimedia.org/wikipedia/commons/d/d9/Continental_Airlines_DC-10.jpg', 'Danielkang7744 at English Wikipedia', 'Public domain', NULL, 'https://commons.wikimedia.org/wiki/File:Continental_Airlines_DC-10.jpg', 'Q208075', 'McDonnell Douglas DC-10', ARRAY['mcdonnell douglas dc-10', 'douglas dc-10', 'mcdonnell douglas/boeing dc-10', 'dc10', 'dc 10', 'dc-10'], 'https://fr.wikipedia.org/wiki/McDonnell_Douglas_DC-10', '{}'::jsonb, true),
  -- ATR 42 (Q218637)
  ('atr-42', 'ATR 42', 'Avions de transport régional', 'ligne', 'L''ATR 42 est un avion de transport de passagers à turbopropulseurs. Le premier vol a eu lieu le 16 août 1984 et l''appareil a été mis en service le 9 décembre 1985. Il existe une variante cargo (sur la base de l''ATR 42-300) et quick change (ATR 42-500). La version actuellement produite par ATR est l''ATR 42-600. 12 ATR 42 ont également été spécialement aménagés pour la surveillance des espaces maritimes par Alenia et livrés aux garde-côtes et à la douane italiens.', NULL, '1984-08-16', 500, 22.67, 24.57, 7.59, 850, NULL, '1985-12-03', NULL, 'France', 'Pratt & Whitney Canada PW100', NULL, 3, 'https://thumb.wikimedia.org/wikipedia/commons/thumb/a/aa/D-BCRS_European_Air_Express_%28EAE%29_%282185550037%29.jpg/1280px-D-BCRS_European_Air_Express_%28EAE%29_%282185550037%29.jpg', 'Pieter van Marion from Netherlands', 'CC BY-SA 2.0', 'https://creativecommons.org/licenses/by-sa/2.0', 'https://commons.wikimedia.org/wiki/File:D-BCRS_European_Air_Express_(EAE)_(2185550037).jpg', 'Q218637', 'ATR 42', ARRAY['atr 42', 'atr42', 'atr-42'], 'https://fr.wikipedia.org/wiki/ATR_42', '{}'::jsonb, true),
  -- McDonnell Douglas F-15E Strike Eagle (Q844500)
  ('mcdonnell-douglas-f-15e-strike-eagle', 'McDonnell Douglas F-15E Strike Eagle', 'McDonnell Douglas / Boeing Integrated Defense Systems', 'militaire', 'Le McDonnell Douglas F-15E Strike Eagle est un chasseur-bombardier d''assaut tout-temps américain en grande partie dérivé du F-15 Eagle, avion de chasse tout-temps dit de « supériorité aérienne ». Il a été conçu dans les années 1980, afin d''effectuer des opérations d''interdiction en profondeur à grande vitesse sans le support de chasseurs d''escorte ou d''avions de guerre électronique.', NULL, '1986-12-11', NULL, 19.45, 13, 5.64, NULL, 18228, '1988-12-01', NULL, NULL, 'Pratt & Whitney F100', 470, 4, 'https://thumb.wikimedia.org/wikipedia/commons/thumb/2/2c/F-15E_Strike_Eagle_over_Afghanistan.jpg/1280px-F-15E_Strike_Eagle_over_Afghanistan.jpg', 'U.S. Air Force photo/Staff Sgt. Aaron Allmon', 'Public domain', NULL, 'https://commons.wikimedia.org/wiki/File:F-15E_Strike_Eagle_over_Afghanistan.jpg', 'Q844500', 'McDonnell Douglas F-15E Strike Eagle', ARRAY['mcdonnell douglas f-15e strike eagle', 'f-15 strike eagle', 'strike eagle', 'f15e', 'boeing f-15e strike eagle', 'mcdonnell douglas strike eagle', 'f-15e', 'f-15e strike eagle'], 'https://fr.wikipedia.org/wiki/McDonnell_Douglas_F-15E_Strike_Eagle', '{"length_m":["https://www.af.mil/About-Us/Fact-Sheets/Display/Article/104499/f-15e-strike-eagle/"],"wingspan_m":["https://www.af.mil/About-Us/Fact-Sheets/Display/Article/104499/f-15e-strike-eagle/"],"height_m":["https://www.af.mil/About-Us/Fact-Sheets/Display/Article/104499/f-15e-strike-eagle/"],"ceiling_m":["https://www.af.mil/About-Us/Fact-Sheets/Display/Article/104499/f-15e-strike-eagle/"]}'::jsonb, true),
  -- F4U Corsair (Q465806)
  ('vought-f4u-corsair', 'F4U Corsair', 'Vought / Goodyear Aerospace', 'collection', 'Le Chance Vought F4U Corsair est un avion militaire américain, utilisé lors de la Seconde Guerre mondiale et jusqu''en 1968. Il est l''un des appareils les plus connus de la Seconde Guerre mondiale, notamment grâce à la série télévisée Les Têtes brûlées, laquelle a popularisé sa silhouette trapue et son aile en W (aile en mouette inversée) qui rendent le Corsair presque immédiatement reconnaissable.', NULL, '1940-05-29', NULL, 10.2, 12.5, 4.5, 1633, NULL, '1942-12-28', '1979-01-01', 'États-Unis', 'R-2800 Double Wasp', 12618, 1, 'https://upload.wikimedia.org/wikipedia/commons/6/66/Vought_F4U_Corsair_%28USMC%29.jpg', 'Gerry Metzler', 'CC BY-SA 2.0', 'https://creativecommons.org/licenses/by-sa/2.0', 'https://commons.wikimedia.org/wiki/File:Vought_F4U_Corsair_(USMC).jpg', 'Q465806', 'Vought F4U Corsair', ARRAY['vought f4u corsair', 'f4u corsair', 'corsair', 'goodyear fg corsair', 'fg corsair', 'brewster f3a corsair', 'f3a corsair', 'vought fighter design 4', 'f4u', 'vought corsair', 'f4u-1', 'fg-1', 'f3a-1', 'f4u-1a', 'fg-1a', 'f3a-1a', 'f4u-1c', 'f4u-1d', 'fg-1d', 'f3a-1d', 'f4u-4', 'f4u-5', 'f4u-7', 'corsair mk.i', 'corsair mk.ii', 'corsair f mk.ii', 'corsair fb mk.ii', 'corsair mk.iii', 'corsair mk.iv', 'chance vought f4u corsair', 'chance vought corsair', 'phantom ii', 'vought chance f4u corsair'], 'https://fr.wikipedia.org/wiki/Chance_Vought_F4U_Corsair', '{}'::jsonb, true),
  -- Panavia Tornado (Q152200)
  ('panavia-tornado', 'Panavia Tornado', 'Panavia Aircraft GmbH', 'militaire', 'Le Panavia Tornado est un avion de combat multirôle européen développé par l''Italie, le Royaume-Uni, et l''Allemagne de l’Ouest durant les années 1970. Ce chasseur-bombardier biplace, biréacteur, dispose d''ailes à géométrie variable. Mis en service dans les années 1980, il a été produit à près de 1 000 exemplaires et exporté vers l''Arabie saoudite. Il reprend le nom du Hawker Tornado, un prototype d''avion militaire de 1939.', NULL, '1974-08-14', NULL, 16.7, NULL, 5.95, 2780, 15240, '1980-01-01', NULL, 'Royaume-Uni / Allemagne de l''Ouest', NULL, 992, 3, 'https://thumb.wikimedia.org/wikipedia/commons/thumb/7/70/German_Panavia_Tornado.JPG/1280px-German_Panavia_Tornado.JPG', 'Master Sgt. Kevin J. Gruenwald, United States Air Force (USAF)', 'Public domain', NULL, 'https://commons.wikimedia.org/wiki/File:German_Panavia_Tornado.JPG', 'Q152200', 'Panavia Tornado', ARRAY['panavia tornado', 'tornado aircraft', 'tornado mrca', 'ecr tornado', 'gr.mk1', 'panavia gr.mk1 tornado'], 'https://fr.wikipedia.org/wiki/Panavia_Tornado', '{"service_entry":["http://www.panavia.de/index.php?option=com_content&view=article&id=31&Itemid=48"]}'::jsonb, true),
  -- Douglas DC-8 (Q223315)
  ('douglas-dc-8', 'Douglas DC-8', 'Douglas / McDonnell Douglas', 'ligne', 'Le Douglas DC-8 est un avion de ligne quadriréacteur à fuselage étroit, moyen et long-courrier, produit entre 1958 et 1972 par la Douglas Aircraft Company, puis par McDonnell Douglas, après la fusion de l''avionneur avec la McDonnell Aircraft Corporation en 1967. Le DC-8 est l''un des tout premiers avions de ligne à réaction et est, avec son concurrent direct, le Boeing 707, l''un des emblèmes de l''ère du jet.', NULL, '1958-05-30', NULL, 57.04, 45.24, 13, NULL, 9150, '1959-09-18', NULL, 'États-Unis', 'JT3D-3B', 556, 3, 'https://upload.wikimedia.org/wikipedia/commons/4/49/Iberia_-_Douglas_DC-8-63.jpg', 'Steve Fitzgerald', 'GFDL 1.2', 'http://www.gnu.org/licenses/old-licenses/fdl-1.2.html', 'https://commons.wikimedia.org/wiki/File:Iberia_-_Douglas_DC-8-63.jpg', 'Q223315', 'Douglas DC-8', ARRAY['douglas dc-8', 'dc8', 'dc-8 aircraft', 'douglas c-24', 'dc-8'], 'https://fr.wikipedia.org/wiki/Douglas_DC-8', '{}'::jsonb, true),
  -- Mikoyan-Gourevitch MiG-27 (Q234069)
  ('mikoyan-mig-27', 'Mikoyan-Gourevitch MiG-27', 'Mikoyan-Gourevitch', 'militaire', 'Le Mikoyan-Gourevitch MiG-27 (МиГ-27 en alphabet cyrillique, code OTAN Flogger) est un avion d''attaque au sol russe dérivé du chasseur MiG-23 Flogger. Apparu dans les années 1970, le MiG-27 a été construit à pratiquement 900 exemplaires, dont 165 sous licence en Inde.', NULL, '1970-08-20', NULL, 16.46, 14.25, NULL, NULL, NULL, '1975-01-01', NULL, NULL, 'R-29', 1075, 3, 'https://upload.wikimedia.org/wikipedia/commons/7/7c/MiG-27_take_off.jpg', 'johnxxx84', 'CC BY-SA 2.0', 'https://creativecommons.org/licenses/by-sa/2.0', 'https://commons.wikimedia.org/wiki/File:MiG-27_take_off.jpg', 'Q234069', 'Mikoyan MiG-27', ARRAY['mikoyan mig-27', 'mikoyan-gourevitch mig-27', 'bahadur', 'flogger-d', 'mikoyan-gurevich mig-27', 'mig-27', 'mikoyan-gourevitch mig-27 flogger'], 'https://fr.wikipedia.org/wiki/Mikoyan-Gourevitch_MiG-27', '{"length_m":["https://www.wikidata.org/wiki/Q29042798"],"wingspan_m":["https://www.wikidata.org/wiki/Q29042798"]}'::jsonb, true),
  -- Antonov An-26 (Q62156)
  ('antonov-an-26', 'Antonov An-26', 'Antonov / Aviant', 'militaire', 'L''Antonov An-26 (code OTAN Curl) est un avion moyen-courrier biturbopropulseur produit par le constructeur soviétique Antonov entre 1968 et 1985.', NULL, '1969-05-21', 433, 11.5, 29.2, 1.91, 2248, 7498, '1973-01-01', NULL, 'Union soviétique', 'Ivchenko AI-24VT / AI-24T', 1403, 3, 'https://upload.wikimedia.org/wikipedia/commons/3/3a/Antonov_An-26B%2C_Air-Urga_JP7560169.jpg', 'Pedro Aragão', 'CC BY-SA 3.0', 'https://creativecommons.org/licenses/by-sa/3.0', 'https://commons.wikimedia.org/wiki/File:Antonov_An-26B,_Air-Urga_JP7560169.jpg', 'Q62156', 'Antonov An-26', ARRAY['antonov an-26', 't-70', 'an26', 'curl', 't70', 'an-26'], 'https://fr.wikipedia.org/wiki/Antonov_An-26', '{"max_speed_kmh":["https://www.wikidata.org/wiki/Q56645322"],"length_m":["https://www.wikidata.org/wiki/Q56645322"],"wingspan_m":["https://www.wikidata.org/wiki/Q56645322"],"height_m":["https://www.wikidata.org/wiki/Q56645322"],"range_km":["https://www.wikidata.org/wiki/Q56645322"],"ceiling_m":["https://www.wikidata.org/wiki/Q56645322"]}'::jsonb, true),
  -- Lockheed F-104 Starfighter (Q159881)
  ('lockheed-f-104-starfighter', 'Lockheed F-104 Starfighter', 'Lockheed / Canadair', 'collection', 'Le Lockheed F-104 Starfighter est un chasseur à réaction américain, monoréacteur et supersonique qui a été construit à plus de 2 500 exemplaires à partir de 1954. Il fut utilisé par les États-Unis dans l''USAF (en anglais : United States Air Force) de 1958 à 1969, puis par la garde nationale de Porto Rico jusqu''à ce qu''il soit abandonné en 1975.', NULL, '1956-02-17', NULL, 16.66, 6.36, 4.09, 2623, 15000, '1958-02-20', '2004-10-31', 'États-Unis', 'General Electric J79', 2578, 2, 'https://thumb.wikimedia.org/wikipedia/commons/thumb/8/86/Lockheed_F-104G_Starfighter_D-8114_%289179542542%29.jpg/1280px-Lockheed_F-104G_Starfighter_D-8114_%289179542542%29.jpg', 'Alan Wilson', 'CC BY-SA 2.0', 'https://creativecommons.org/licenses/by-sa/2.0', 'https://commons.wikimedia.org/wiki/File:Lockheed_F-104G_Starfighter_D-8114_(9179542542).jpg', 'Q159881', 'Lockheed F-104 Starfighter', ARRAY['lockheed f-104 starfighter', 'lockheed starfighter', 'starfighter', 'f-104', 'f-104 starfighter'], 'https://fr.wikipedia.org/wiki/Lockheed_F-104_Starfighter', '{}'::jsonb, true),
  -- Iliouchine Il-62 (Q182575)
  ('ilyushin-il-62', 'Iliouchine Il-62', 'Iliochine / Kazan Aircraft Production Association', 'ligne', 'L’Iliouchine Il-62 (en russe : Ильюшин Ил-62) est un avion de ligne soviétique. Premier long courrier à réaction produit par l''URSS, il peut être comparé aux Boeing 707, Douglas DC-8 et Vickers VC10, qu''il dépasse tous légèrement en taille. La configuration aérodynamique de l''avion est caractérisée par la position des moteurs, installés deux par deux à l''arrière du fuselage, sous un empennage en « T ». Il est d''une conception plutôt simple, privilégiant la robustesse et la facilité d''entretien.', NULL, '1963-01-03', NULL, 53.12, 43.2, 12.35, NULL, 12000, '1965-01-01', NULL, 'Union soviétique', 'Soloviev D-30', 292, 4, 'https://upload.wikimedia.org/wikipedia/commons/4/43/Air_Koryo_IL-62M_P-881.JPG', 'No machine-readable author provided. Yaoleilei assumed (based on copyright claims).', 'CC BY-SA 3.0', 'http://creativecommons.org/licenses/by-sa/3.0/', 'https://commons.wikimedia.org/wiki/File:Air_Koryo_IL-62M_P-881.JPG', 'Q182575', 'Ilyushin Il-62', ARRAY['ilyushin il-62', 'iliouchine il-62', 'classic', 'ilyushin 62', 'il-62classic', 'iliouchine il-62 classic', 'il-62', 'iliouchine 62'], 'https://fr.wikipedia.org/wiki/Iliouchine_Il-62', '{"length_m":["https://www.wikidata.org/wiki/Q29042798"],"wingspan_m":["https://www.wikidata.org/wiki/Q29042798"]}'::jsonb, true),
  -- Antonov An-12 (Q271559)
  ('antonov-an-12', 'Antonov An-12', 'Antonov / Irkutsk Aviation Plant', 'militaire', 'L''Antonov An-12 (désignation OTAN Cub) est un avion de transport militaire de moyen tonnage, souvent considéré comme l''équivalent soviétique de l''Hercules américain même s''il n''a pas été produit en aussi grand nombre.', NULL, '1957-12-16', 776, 37, 38, 2.4, 3597, 10200, '1959-01-01', NULL, 'Union soviétique', 'AI-20M / AI-20K', 1248, 3, 'https://upload.wikimedia.org/wikipedia/commons/2/2c/Antonov_An-12B%2C_Antonov_Design_Bureau_AN0373725.jpg', 'Árpád Gordos', 'GFDL 1.2', 'http://www.gnu.org/licenses/old-licenses/fdl-1.2.html', 'https://commons.wikimedia.org/wiki/File:Antonov_An-12B,_Antonov_Design_Bureau_AN0373725.jpg', 'Q271559', 'Antonov An-12', ARRAY['antonov an-12', 'cub', 'an-12'], 'https://fr.wikipedia.org/wiki/Antonov_An-12', '{"max_speed_kmh":["https://www.wikidata.org/wiki/Q56645322"],"length_m":["https://www.wikidata.org/wiki/Q29042798"],"wingspan_m":["https://www.wikidata.org/wiki/Q29042798"],"height_m":["https://www.wikidata.org/wiki/Q56645322"],"range_km":["https://www.wikidata.org/wiki/Q56645322"]}'::jsonb, true),
  -- North American X-15 (Q221269)
  ('north-american-x-15', 'North American X-15', 'North American Aviation', 'collection', 'Le North American X-15 est un avion-fusée hypersonique expérimental de vol suborbital américain, construit dans le cadre d''un programme de recherche sur les vols à très haute vitesse et très haute altitude. De 1960 à 1968, les trois exemplaires construits ont effectué environ 200 vols d''essais pour le compte de la NASA et de l''US Air Force, pulvérisant tous les records de vitesse et d''altitude détenus par un aéronef piloté à aile fixe.', NULL, '1959-06-08', NULL, NULL, NULL, NULL, NULL, NULL, '1959-09-17', '1968-12-01', 'États-Unis', NULL, 4, 5, 'https://thumb.wikimedia.org/wikipedia/commons/thumb/2/26/North_American_X-15.jpg/1280px-North_American_X-15.jpg', 'NASA', 'Public domain', NULL, 'https://commons.wikimedia.org/wiki/File:North_American_X-15.jpg', 'Q221269', 'North American X-15', ARRAY['x-15', 'north american x-15', 'x15'], 'https://fr.wikipedia.org/wiki/North_American_X-15', '{}'::jsonb, true)
