  id, name, manufacturer, category, description, recognition_hints, first_flight, max_speed_kmh, length_m, wingspan_m, height_m, range_km, ceiling_m, service_entry, retirement, country_of_origin, engines, units_built, rarity, image_url, image_author, image_license, image_license_url, image_source_url, wikidata_id, enwiki_title, aliases, wikipedia_url, sources, verified
) VALUES
  -- F6F Hellcat (Q465903)
  ('grumman-f6f-hellcat', 'F6F Hellcat', 'Grumman', 'collection', 'Le Grumman F6F Hellcat est un chasseur embarqué développé pour remplacer le F4F Wildcat au sein de l''United States Navy. Bien que le F6F soit une extrapolation du F4F, il était beaucoup plus puissant avec un moteur Pratt & Whitney R-2800 de 2 000 ch. Souvent appelé « Wildcat''s big brother », le Hellcat, au même titre que le F4U Corsair, fut le principal chasseur de l''US Navy durant la seconde partie de la Seconde Guerre mondiale.', NULL, '1942-06-26', NULL, 10.24, 13.06, 3.99, 1520, 11370, '1943-01-01', '1960-01-01', 'États-Unis', 'R-2800 Double Wasp', 12275, 1, 'https://thumb.wikimedia.org/wikipedia/commons/thumb/e/ec/Grumman_F6F_Hellcat_-_Chino_Airshow_2014_%2816581440362%29.jpg/1280px-Grumman_F6F_Hellcat_-_Chino_Airshow_2014_%2816581440362%29.jpg', 'Airwolfhound from Hertfordshire, UK', 'CC BY-SA 2.0', 'https://creativecommons.org/licenses/by-sa/2.0', 'https://commons.wikimedia.org/wiki/File:Grumman_F6F_Hellcat_-_Chino_Airshow_2014_(16581440362).jpg', 'Q465903', 'Grumman F6F Hellcat', ARRAY['grumman f6f hellcat', 'f6f hellcat', 'f6f', 'grumman fighter type 6', 'hellcat aircraft', 'grumman hellcat', 'grumman gannet', 'gannet aircraft', 'grumman g-50 hellcat', 'grumman g-50', 'g-50 hellcat', 'g-50', 'hellcat', 'grumman fighter design 6', '"hellcat"'], 'https://fr.wikipedia.org/wiki/Grumman_F6F_Hellcat', '{}'::jsonb, true),
  -- Focke-Wulf Fw 190 (Q34775)
  ('focke-wulf-fw-190', 'Focke-Wulf Fw 190', 'Focke-Wulf', 'collection', 'Le Focke-Wulf Fw 190 (surnommé Würger Pie-grièche et Butcherbird) est un chasseur-bombardier monoplace et monomoteur utilisé par l''Allemagne pendant la Seconde Guerre mondiale, entre 1941 et 1945. Il ne supplanta pas complètement le Messerschmitt Bf 109 comme principal chasseur de la Luftwaffe, bien qu''il lui fût supérieur. Il fut produit à plus de 20 000 exemplaires.', NULL, '1939-06-01', NULL, 9, 10.2, 3.95, 800, 11410, '1941-01-01', '1945-05-09', 'Troisième Reich', NULL, 19500, 1, 'https://thumb.wikimedia.org/wikipedia/commons/thumb/6/66/FW190_-_Chino_Airshow_2014_%2815246309761%29.jpg/1280px-FW190_-_Chino_Airshow_2014_%2815246309761%29.jpg', 'Airwolfhound from Hertfordshire, UK', 'CC BY-SA 2.0', 'https://creativecommons.org/licenses/by-sa/2.0', 'https://commons.wikimedia.org/wiki/File:FW190_-_Chino_Airshow_2014_(15246309761).jpg', 'Q34775', 'Focke-Wulf Fw 190', ARRAY['focke-wulf fw 190', 'fw 190'], 'https://fr.wikipedia.org/wiki/Focke-Wulf_Fw_190', '{}'::jsonb, true),
  -- Bf 110 (Q155642)
  ('messerschmitt-bf-110', 'Bf 110', 'Messerschmitt / Augsbourg', 'collection', 'Le Messerschmitt Bf 110 (appelé ensuite Me 110) était un chasseur moyen bimoteur allemand, en service dans la Luftwaffe pendant la Seconde Guerre mondiale. Basé autour du concept du Zerstörer (en français : « destructeur ») à long rayon d''action, cet avion obtint quelques succès lors des campagnes de Pologne et de France, comme lors de l''opération Paula, qui se conclut par la perte de dix appareils allemands, dont seulement quatre Bf 110.', NULL, '1936-05-12', NULL, NULL, NULL, NULL, NULL, NULL, '1939-01-01', '1945-01-01', 'Allemagne', NULL, 6170, 2, 'https://upload.wikimedia.org/wikipedia/commons/c/ce/Bundesarchiv_Bild_101I-360-2095-23%2C_Flugzeuge_Messerschmitt_Me_110.jpg', 'Wanderer, W.', 'CC BY-SA 3.0 de', 'https://creativecommons.org/licenses/by-sa/3.0/de/deed.en', 'https://commons.wikimedia.org/wiki/File:Bundesarchiv_Bild_101I-360-2095-23,_Flugzeuge_Messerschmitt_Me_110.jpg', 'Q155642', 'Messerschmitt Bf 110', ARRAY['messerschmitt bf 110', 'bf 110', 'messerschmitt me 110', 'messerschmitt bf-110', 'me 110', 'bf-110', 'messerschmitt 110'], 'https://fr.wikipedia.org/wiki/Messerschmitt_Bf_110', '{}'::jsonb, true),
  -- Tu-16 (Q192779)
  ('tupolev-tu-16', 'Tu-16', 'Tupolev / Kazan Aircraft Production Association', 'collection', 'Le Tupolev Tu-16 (code OTAN : Badger) est un bombardier biréacteur, conçu par Tupolev en Union soviétique, au début des années 1950. Bien que souvent considéré comme obsolète, sa polyvalence lui a permis de rester en service au sein des forces aériennes russe, ukrainienne et chinoise, ce qui en fait un des rares appareils militaires dont la carrière opérationnelle dépasse le demi-siècle.', NULL, '1952-04-27', NULL, 34.8, 33, 10.36, NULL, NULL, '1954-01-01', '1993-01-01', 'Union soviétique', 'Mikouline AM-3', 1509, 3, 'https://thumb.wikimedia.org/wikipedia/commons/thumb/f/f5/Tu-16badger_2.jpg/1280px-Tu-16badger_2.jpg', 'Unknown authorUnknown author', 'Public domain', NULL, 'https://commons.wikimedia.org/wiki/File:Tu-16badger_2.jpg', 'Q192779', 'Tupolev Tu-16', ARRAY['tupolev tu-16', 'tu-16', 'badger', 'tupolev tu-16 badger', 'tu-16 badger', 'tupolev tu-88'], 'https://fr.wikipedia.org/wiki/Tupolev_Tu-16', '{"length_m":["https://www.wikidata.org/wiki/Q29042798"]}'::jsonb, true),
  -- Consolidated B-24 Liberator (Q220759)
  ('consolidated-b-24-liberator', 'Consolidated B-24 Liberator', 'North American Aviation / Ford', 'collection', 'Le Consolidated B-24 Liberator est un bombardier lourd américain, conçu par Consolidated Aircraft de San Diego (Californie). Il est connu dans la société comme le Model 32, et un petit nombre des premiers modèles sont vendus sous le nom LB-30, pour « Land Bomber ».', NULL, '1939-12-29', NULL, 20.47, 34, 5.37, 7600, 8500, '1941-01-01', '1945-01-01', 'États-Unis', NULL, 18482, 1, 'https://thumb.wikimedia.org/wikipedia/commons/thumb/8/88/B24J-The_Dragon_And_His_Tail.jpg/1280px-B24J-The_Dragon_And_His_Tail.jpg', 'Tequask', 'CC BY-SA 4.0', 'https://creativecommons.org/licenses/by-sa/4.0', 'https://commons.wikimedia.org/wiki/File:B24J-The_Dragon_And_His_Tail.jpg', 'Q220759', 'Consolidated B-24 Liberator', ARRAY['consolidated b-24 liberator', 'b24', 'liberator', 'consolidated lb-30', 'lb-30', 'consolidated xb-24', 'b-24 liberator', 'b-24'], 'https://fr.wikipedia.org/wiki/Consolidated_B-24_Liberator', '{}'::jsonb, true),
  -- Soukhoï Su-33 (Q332637)
  ('sukhoi-su-33', 'Soukhoï Su-33', 'Soukhoï / Komsomolsk-on-Amur Aircraft Production Association', 'militaire', 'Le Soukhoï Su-33 (Code OTAN Flanker-D) initialement appelé Su-27K est un avion de chasse et de lutte antinavire russe embarqué sur porte-avions, dérivé du Soukhoï Su-27 Flanker.', NULL, '1987-08-17', NULL, NULL, NULL, NULL, NULL, NULL, '1998-08-31', NULL, 'Union soviétique', 'Saturn AL-31', NULL, 3, 'https://thumb.wikimedia.org/wikipedia/commons/thumb/3/33/Sukhoi_Su-33_in_2010_%285%29.jpg/1280px-Sukhoi_Su-33_in_2010_%285%29.jpg', 'Igor Bubin', 'GFDL 1.2', 'http://www.gnu.org/licenses/old-licenses/fdl-1.2.html', 'https://commons.wikimedia.org/wiki/File:Sukhoi_Su-33_in_2010_(5).jpg', 'Q332637', 'Sukhoi Su-33', ARRAY['sukhoi su-33', 'soukhoï su-33', 'flanker-d', 'su-27k', 'sukhoi su-27k', 'su-33', 'soukhoi su-33'], 'https://fr.wikipedia.org/wiki/Soukho%C3%AF_Su-33', '{"service_entry":["http://lenta.ru/articles/2012/06/15/su33/"]}'::jsonb, true),
  -- Junkers Ju 52/3m (Q26066)
  ('junkers-ju-52', 'Junkers Ju 52/3m', 'Junkers Motorenbau und Junkers Flugzeugwerk / Junkers', 'collection', 'Le Junkers Ju 52 (surnommé Tante Ju en allemand, Iron Annie par les Anglais) était un avion de transport en tôle ondulée fabriqué par la firme allemande Junkers à partir des années 1930. Construit à plus de 4 845 exemplaires entre 1931 et 1952, il a été utilisé par de nombreuses compagnies aériennes (douze compagnies), mais aussi comme avion de transport militaire et bombardier pendant la Seconde Guerre mondiale.', NULL, '1932-03-07', NULL, 18.9, 29.25, 4.5, 840, 5490, '1932-01-01', NULL, 'Reich allemand', NULL, 4845, 2, 'https://thumb.wikimedia.org/wikipedia/commons/thumb/8/85/100820_Speyer_Museum_%2817%29.jpg/1280px-100820_Speyer_Museum_%2817%29.jpg', 'Bubensteyn', 'CC BY-SA 4.0', 'https://creativecommons.org/licenses/by-sa/4.0', 'https://commons.wikimedia.org/wiki/File:100820_Speyer_Museum_(17).jpg', 'Q26066', 'Junkers Ju 52', ARRAY['junkers ju 52', 'junkers ju 52/3m', 'ju 52', 'junkers 52'], 'https://fr.wikipedia.org/wiki/Junkers_Ju_52', '{}'::jsonb, true),
  -- McDonnell Douglas MD-11 (Q62161)
  ('mcdonnell-douglas-md-11', 'McDonnell Douglas MD-11', 'McDonnell Douglas / Boeing', 'ligne', 'Le McDonnell Douglas MD-11 est un avion tri-réacteur long-courrier du constructeur aéronautique américain McDonnell Douglas. Le MD-11 est le successeur du long-courrier DC-10, dont il est une version allongée de 5,6 mètres et plus performante grâce à ses nouveaux moteurs et diverses améliorations, dont ses ailettes de bout d''aile et son cockpit à l''avionique moderne (glass cockpit) qui permet l''économie d''un poste de mécanicien navigant.', NULL, '1990-01-10', NULL, 61.21, 51.66, 17.6, NULL, 13000, '1990-12-20', NULL, 'États-Unis', NULL, 200, 4, 'https://thumb.wikimedia.org/wikipedia/commons/thumb/3/36/KLM_McDonnell_Douglas_MD-11_PH-KCK_Ingrid_Bergman.jpg/1280px-KLM_McDonnell_Douglas_MD-11_PH-KCK_Ingrid_Bergman.jpg', 'KLM_McDonnell_Douglas_MD-11_PH-KCK.jpg: Boushh_TFA from Kortenhoef, The Netherlands derivative work: Altair78 (talk)', 'CC BY-SA 2.0', 'https://creativecommons.org/licenses/by-sa/2.0', 'https://commons.wikimedia.org/wiki/File:KLM_McDonnell_Douglas_MD-11_PH-KCK_Ingrid_Bergman.jpg', 'Q62161', 'McDonnell Douglas MD-11', ARRAY['mcdonnell douglas md-11', 'md-11'], 'https://fr.wikipedia.org/wiki/McDonnell_Douglas_MD-11', '{"length_m":["https://www.wikidata.org/wiki/Q29042798"],"wingspan_m":["https://www.wikidata.org/wiki/Q29042798"]}'::jsonb, true),
  -- Iliouchine Il-86 (Q62167)
  ('ilyushin-il-86', 'Iliouchine Il-86', 'Iliochine / Voronezh Aircraft Production Association', 'ligne', 'L''Iliouchine Il-86 (code OTAN : Camber) est le premier avion de ligne soviétique à large fuselage, c''est-à-dire présentant des rangées de sièges passagers séparées par deux couloirs. Le projet est annoncé en 1971 et l''avion vole en 1976. Un peu plus de 100 exemplaires sont construits, et furent employés principalement par Aeroflot. L''avion est robuste, bien conçu, et offre une bonne capacité.', NULL, '1976-12-22', NULL, 59.94, 48.06, 15.81, NULL, 11000, '1980-12-26', '2011-01-01', 'Union soviétique', 'Kouznetsov NK-86', 106, 4, 'https://upload.wikimedia.org/wikipedia/commons/a/a0/Aeroflot_RA_Ilyushin_Il-86_von_Wedelstaedt.jpg', 'Konstantin von Wedelstaedt', 'GFDL 1.2', 'http://www.gnu.org/licenses/old-licenses/fdl-1.2.html', 'https://commons.wikimedia.org/wiki/File:Aeroflot_RA_Ilyushin_Il-86_von_Wedelstaedt.jpg', 'Q62167', 'Ilyushin Il-86', ARRAY['iljushin il-86', 'iliouchine il-86', 'ilyushin il-86', 'camber', 'il-86'], 'https://fr.wikipedia.org/wiki/Iliouchine_Il-86', '{"wingspan_m":["https://www.wikidata.org/wiki/Q29042798"]}'::jsonb, true),
  -- AC-130 (Q431231)
  ('lockheed-ac-130', 'AC-130', 'Lockheed Martin', 'militaire', 'Le Lockheed AC-130 est un avion gunship (canonnière volante) d''attaque au sol et d''appui aérien rapproché (close air support (CAS)). La base de l''avion est fabriquée par Lockheed. Boeing est responsable de la conversion en canonnière volante. Il s''agit d''une variante de l''avion de transport C-130 Hercules.', NULL, '1966-01-01', NULL, 29.79, 40.41, 11.73, NULL, NULL, '1968-01-01', NULL, 'États-Unis', NULL, 47, 5, 'https://thumb.wikimedia.org/wikipedia/commons/thumb/0/0a/AC-130H_flies_along_Northwest_Florida_coast.jpg/1280px-AC-130H_flies_along_Northwest_Florida_coast.jpg', 'SrA Julianne Showalter', 'Public domain', NULL, 'https://commons.wikimedia.org/wiki/File:AC-130H_flies_along_Northwest_Florida_coast.jpg', 'Q431231', 'Lockheed AC-130', ARRAY['ac-130', 'lockheed ac-130', 'ac130', 'ac-130 spectre', 'angel of death', 'ac-130 gunship'], 'https://fr.wikipedia.org/wiki/Lockheed_AC-130', '{}'::jsonb, true),
  -- Tupolev Tu-204 (Q466590)
  ('tupolev-tu-204', 'Tupolev Tu-204', 'Kazan Aircraft Production Association / Aviastar-SP', 'ligne', 'Le Tupolev Tu-204 est un biréacteur civil moyen-courrier produit par la société russe Tupolev. Il a été conçu pour succéder au Tupolev Tu-154 et peut être comparé aux avions occidentaux de type Airbus A321 et Boeing 757.', NULL, '1989-01-02', NULL, NULL, NULL, NULL, NULL, NULL, '1996-02-23', NULL, 'Union soviétique / Russie', 'Aviadvigatel PS-90 / Rolls-Royce RB211', 76, 4, 'https://upload.wikimedia.org/wikipedia/commons/a/ad/KMV_T204_RA-64022.jpg', 'Juergen Lehle', 'CC BY-SA 3.0', 'http://creativecommons.org/licenses/by-sa/3.0/', 'https://commons.wikimedia.org/wiki/File:KMV_T204_RA-64022.jpg', 'Q466590', 'Tupolev Tu-204', ARRAY['tupolev tu-204', 'tupolev tu-214', 'tupolev tu-224', 'tupolev tu-234', 'tu-204'], 'https://fr.wikipedia.org/wiki/Tupolev_Tu-204', '{}'::jsonb, true),
  -- Su-17 (Q183146)
  ('sukhoi-su-17', 'Su-17', 'Soukhoï / Komsomolsk-on-Amur Aircraft Production Association', 'militaire', 'Le Soukhoï Su-17 (code OTAN Fitter) est un avion d''attaque au sol soviétique dérivé du Soukhoï Su-7 et doté d''une aile à géométrie variable. Il a été construit à 2 867 exemplaires entre 1969 et 1990, dont 1 165 exportés dans quinze pays différents sous les désignations de Su-20 et Su-22. Il a été retiré du service actif en Russie en 1998, mais figure encore actuellement dans l''inventaire de plusieurs autres forces aériennes.', NULL, '1966-08-02', NULL, 17.75, 13.7, 4.75, NULL, 18000, '1970-01-01', NULL, NULL, 'Lyulka AL-21', 2867, 2, 'https://thumb.wikimedia.org/wikipedia/commons/thumb/5/54/Su-17_%2812387980854%29.jpg/1280px-Su-17_%2812387980854%29.jpg', 'Rob Schleiffert', 'CC BY-SA 2.0', 'https://creativecommons.org/licenses/by-sa/2.0', 'https://commons.wikimedia.org/wiki/File:Su-17_(12387980854).jpg', 'Q183146', 'Sukhoi Su-17', ARRAY['sukhoi su-17', 'su-17', 'fitter', 'sukhoi su-17 fitter', 'soukhoi su-17', 'sukhoï su-17', 'su-20', 'su-17 fitter', 'soukhoï su-22', 'su-22', 'soukhoï su-20', 'soukhoï su-17'], 'https://fr.wikipedia.org/wiki/Soukho%C3%AF_Su-17', '{"wingspan_m":["https://www.wikidata.org/wiki/Q29042798"],"units_built":["http://3v-soft.clan.su/news/istrebitel_bombardirovshhik_su_17/2009-12-23-58"]}'::jsonb, true),
  -- Boeing E-3 Sentry (Q261384)
  ('boeing-e-3-sentry', 'Boeing E-3 Sentry', 'Boeing Integrated Defense Systems / Westinghouse Electric', 'militaire', 'Le Boeing E-3 Sentry (« sentinelle »), communément dénommé AWACS (Airborne Warning & Control System), est un avion de détection et de commandement développé par Boeing en tant que maître d''œuvre.', NULL, '1972-02-09', NULL, 46.61, 44.42, NULL, 9250, 8788, '1977-03-01', NULL, 'États-Unis', 'TF33-PW-100A', 68, 4, 'https://upload.wikimedia.org/wikipedia/commons/b/b9/060610-SKP-E-3-01.jpg', 'user:Pajx', 'Public domain', NULL, 'https://commons.wikimedia.org/wiki/File:060610-SKP-E-3-01.jpg', 'Q261384', 'Boeing E-3 Sentry', ARRAY['boeing e-3 sentry', 'e3 sentry', 'awacs', 'e-3 sentry'], 'https://fr.wikipedia.org/wiki/Boeing_E-3_Sentry', '{"range_km":["https://www.af.mil/About-Us/Fact-Sheets/Display/Article/104504/e-3-sentry-awacs/#:~:text=Pacific%20Air%20Forces%20has%20four%20E-3%20Sentries%20at,France%20has%20four%2C%20and%20Saudi%20Arabia%20has%20five."],"ceiling_m":["https://www.af.mil/About-Us/Fact-Sheets/Display/Article/104504/e-3-sentry-awacs/#:~:text=Pacific%20Air%20Forces%20has%20four%20E-3%20Sentries%20at,France%20has%20four%2C%20and%20Saudi%20Arabia%20has%20five."]}'::jsonb, true),
  -- Iliouchine Il-96 (Q272571)
  ('ilyushin-il-96', 'Iliouchine Il-96', 'Voronezh Aircraft Production Association', 'ligne', 'L''Iliouchine Il-96 est un avion de transport commercial long courrier russe réalisé par la société Iliouchine, et fabriqué dans l''usine de Voronej.', NULL, '1988-09-28', NULL, 64.7, 60.11, 15.7, NULL, 12000, '1993-01-01', NULL, 'Russie / Union soviétique', NULL, 30, 5, 'https://upload.wikimedia.org/wikipedia/commons/e/eb/RA96010_%286715454961%29.jpg', 'Paul Nelhams from Shannon, Ireland', 'CC BY-SA 2.0', 'https://creativecommons.org/licenses/by-sa/2.0', 'https://commons.wikimedia.org/wiki/File:RA96010_(6715454961).jpg', 'Q272571', 'Ilyushin Il-96', ARRAY['iljushin il-96', 'iliouchine il-96', 'ilyushin il-96', 'il96', 'il-96'], 'https://fr.wikipedia.org/wiki/Iliouchine_Il-96', '{}'::jsonb, true),
  -- North American B-25 Mitchell (Q502117)
  ('north-american-b-25-mitchell', 'North American B-25 Mitchell', 'North American Aviation', 'collection', 'Le North American B-25 Mitchell est un bombardier moyen de la Seconde Guerre mondiale. Sa carrière débute en 1942 par une action d''éclat : le raid sur Tokyo. Il est nommé en l''honneur du pionnier de l''aviation militaire et commandant des forces aériennes américaines en France durant la Première Guerre mondiale, le général William Billy Mitchell.', NULL, '1940-08-19', NULL, 16.1, 20.6, 4.8, 2170, 7600, '1941-01-01', '1979-01-01', 'États-Unis', 'R-2600 Twin Cyclone', 9984, 2, 'https://upload.wikimedia.org/wikipedia/commons/f/fd/N9643C_%287938842996%29.jpg', 'Paul Nelhams from Shannon, Ireland', 'CC BY-SA 2.0', 'https://creativecommons.org/licenses/by-sa/2.0', 'https://commons.wikimedia.org/wiki/File:N9643C_(7938842996).jpg', 'Q502117', 'North American B-25 Mitchell', ARRAY['north american b-25 mitchell', 'b25', 'mitchell bomber', 'north american mitchell', 'mitchell aircraft', 'cb25', 'at24', 'at-24', 'bombardier b-25', 'tb25', 'b-25', 'tb-25', 'cb-25'], 'https://fr.wikipedia.org/wiki/North_American_B-25_Mitchell', '{}'::jsonb, true),
  -- An-32 (Q579939)
  ('antonov-an-32', 'An-32', 'Antonov / Aviant', 'ligne', 'L''Antonov An-32 (Code OTAN : Cline) est un avion de transport militaire biturbopropulseur soviétique puis ukrainien. Il s''agit d''une version remotorisée de l''Antonov An-26.', NULL, '1976-07-09', NULL, 23.78, 29.2, 8.75, 2500, 9500, '1984-01-01', NULL, 'Union soviétique', 'AI-24 / Pratt & Whitney Canada PW150A', 361, 4, 'https://thumb.wikimedia.org/wikipedia/commons/thumb/d/d4/Antonov_An-32_9Q-CAC.jpg/1280px-Antonov_An-32_9Q-CAC.jpg', 'Guido Potters', 'GFDL', 'http://www.gnu.org/copyleft/fdl.html', 'https://commons.wikimedia.org/wiki/File:Antonov_An-32_9Q-CAC.jpg', 'Q579939', 'Antonov An-32', ARRAY['antonov an-32', 'an-32', 'antonov an-32 cline', 'an32', 'cline'], 'https://fr.wikipedia.org/wiki/Antonov_An-32', '{"wingspan_m":["https://www.wikidata.org/wiki/Q29042798"],"units_built":["http://www.aviant.ua/1947.html"]}'::jsonb, true),
  -- MiG-1 (Q464247)
  ('mikoyan-gurevich-mig-1', 'MiG-1', 'Mikoyan-Gourevitch', 'collection', 'Le Mikoyan-Gourevitch MiG-1 fut un avion de chasse soviétique de la Seconde Guerre mondiale. Bien qu''il fût difficile à manœuvrer, il servit de base pour le MiG-3, qui prouva ses capacités d''intercepteur à haute altitude et fit la réputation de ses concepteurs.', NULL, '1940-04-05', NULL, 8.16, 10.2, 2.62, 560, 12000, '1940-01-01', '1944-01-01', 'Union soviétique', 'Mikulin AM-35', 100, 4, 'https://upload.wikimedia.org/wikipedia/commons/9/90/MiG-1.jpg', 'Unknown authorUnknown author', 'Public domain', NULL, 'https://commons.wikimedia.org/wiki/File:MiG-1.jpg', 'Q464247', 'Mikoyan-Gurevich MiG-1', ARRAY['mikoyan-gurevich mig-1', 'mig-1', 'mikoyan-gourevitch mig-1'], 'https://fr.wikipedia.org/wiki/Mikoyan-Gourevitch_MiG-1', '{}'::jsonb, true),
  -- Chengdu J-20 (Q560319)
  ('chengdu-j-20', 'Chengdu J-20', 'Chengdu Aircraft Corporation', 'militaire', 'Le Chengdu J-20 (chinois simplifié : 歼-20 ; chinois traditionnel : 殲-20 ; pinyin : jiān-20 ; litt. « Anéantisseur-20 ») est un avion de chasse furtif chinois. Le démonstrateur, qui a fait son premier vol en janvier 2011, préfigure ce que pourrait être un avion de cinquième génération biréacteur développé par le constructeur Chengdu Aircraft Corporation pour l''Armée populaire de libération (destiné à la force aérienne chinoise).', NULL, '2011-01-11', NULL, 23, 15, 4.7, 6000, NULL, '2017-03-09', NULL, 'République populaire de Chine', NULL, NULL, 3, 'https://thumb.wikimedia.org/wikipedia/commons/thumb/a/a2/J-20_at_Airshow_China_2016.jpg/1280px-J-20_at_Airshow_China_2016.jpg', 'Alert5', 'CC BY-SA 4.0', 'https://creativecommons.org/licenses/by-sa/4.0', 'https://commons.wikimedia.org/wiki/File:J-20_at_Airshow_China_2016.jpg', 'Q560319', 'Chengdu J-20', ARRAY['chengdu j-20', 'j-20', 'j-xx'], 'https://fr.wikipedia.org/wiki/Chengdu_J-20', '{}'::jsonb, true),
  -- Northrop Grumman B-21 (Q22960692)
  ('northrop-grumman-b-21-raider', 'Northrop Grumman B-21', 'Northrop Grumman Corporation', 'militaire', 'Le Northrop Grumman B-21 Raider est un bombardier stratégique américain en cours de développement par Northrop Grumman pour l''United States Air Force (USAF). Dans la lignée du Northrop B-2 Spirit, le B-21 doit le remplacer ainsi que le Rockwell B-1 Lancer, le Boeing B-52 Stratofortress devant rester en service à ses côtés.', NULL, '2023-11-10', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'États-Unis', NULL, NULL, 3, 'https://thumb.wikimedia.org/wikipedia/commons/thumb/8/81/B-21_Plant_42_hangar.jpg/1280px-B-21_Plant_42_hangar.jpg', 'Staff Sgt. Jeremy Mosier, United States Air Force', 'Public domain', NULL, 'https://commons.wikimedia.org/wiki/File:B-21_Plant_42_hangar.jpg', 'Q22960692', 'Northrop Grumman B-21 Raider', ARRAY['northrop grumman b-21 raider', 'northrop grumman b-21', 'b-21 raider', 'b-21', 'raider'], 'https://fr.wikipedia.org/wiki/Northrop_Grumman_B-21_Raider', '{"first_flight":["https://www.reuters.com/business/aerospace-defense/us-air-forces-new-b-21-raider-flying-wing-bomber-takes-first-flight-reuters-2023-11-10/","https://www.wikidata.org/wiki/Q130879"]}'::jsonb, true),
  -- Lockheed L-1011 TriStar (Q852)
  ('lockheed-l-1011-tristar', 'Lockheed L-1011 TriStar', 'Lockheed', 'ligne', 'Le Lockheed L-1011 TriStar est un avion long-courrier triréacteur à usage civil et militaire, construit par la société Lockheed dans les années 1970 et 1980. Le numéro associé à l''appareil étant toujours basé sur 1000, les numéros de série commençaient à partir de MSN1001 (prototype).', NULL, '1970-11-16', NULL, 54.17, 47.34, 16.87, NULL, NULL, '1972-04-26', NULL, 'États-Unis', 'Rolls-Royce RB211', 250, 4, 'https://upload.wikimedia.org/wikipedia/commons/4/4d/Lockheed_L-1011-385-1_TriStar_1_demonstrator_with_additional_Court_Line_titles.jpg', 'Richard Vandervord', 'CC BY-SA 4.0', 'https://creativecommons.org/licenses/by-sa/4.0', 'https://commons.wikimedia.org/wiki/File:Lockheed_L-1011-385-1_TriStar_1_demonstrator_with_additional_Court_Line_titles.jpg', 'Q852', 'Lockheed L-1011 TriStar', ARRAY['lockheed l-1011 tristar', 'tristar', 'l1011', 'l-1011 tristar', 'l.1011', 'lockheed tristar'], 'https://fr.wikipedia.org/wiki/Lockheed_L-1011_TriStar', '{"length_m":["https://www.wikidata.org/wiki/Q29042798"],"wingspan_m":["https://www.wikidata.org/wiki/Q29042798"]}'::jsonb, true),
  -- Airbus A320neo (Q6488)
  ('airbus-a320neo-family', 'Airbus A320neo', 'Airbus Commercial Aircraft', 'ligne', 'Airbus A320neo est une famille d''avions de la société européenne Airbus, rénovant sa gamme A320, avec les technologies déployées pour la construction de l''Airbus A380, puis l''A350 XWB. Il complète la gamme de l''Airbus A330neo. Lancé le 1er décembre 2010, il fait son premier vol le 25 septembre 2014, et est déployé pour la première fois commercialement par Lufthansa, le 25 janvier 2016.', NULL, '2014-09-25', NULL, NULL, NULL, NULL, NULL, NULL, '2016-01-25', NULL, 'France / Allemagne', 'CFM International LEAP / Pratt & Whitney PW1000G', 474, 4, 'https://upload.wikimedia.org/wikipedia/commons/9/90/Airbus_A320-271N_NEO_D-AVVA.jpg', 'Pedro Aragão', 'CC BY-SA 3.0', 'https://creativecommons.org/licenses/by-sa/3.0', 'https://commons.wikimedia.org/wiki/File:Airbus_A320-271N_NEO_D-AVVA.jpg', 'Q6488', 'Airbus A320neo family', ARRAY['airbus a320neo family', 'airbus a320neo', 'a320neo', 'a320 neo'], 'https://fr.wikipedia.org/wiki/Airbus_A320neo', '{}'::jsonb, true),
  -- Su-7 (Q170199)
  ('sukhoi-su-7', 'Su-7', 'Soukhoï / Komsomolsk-on-Amur Aircraft Production Association', 'collection', 'Le Soukhoï Su-7 (code OTAN Fitter A) est un chasseur-bombardier à ailes en flèches conçu par l''URSS pendant les années 1950. Il a été construit à plus de 1 800 exemplaires utilisés par une dizaine de pays différents. Le Su-7 est très proche du Soukhoï Su-9 qui dispose lui d''une aile delta. À la fin des années 1960, le Su-7 a été amélioré pour donner naissance au Soukhoï Su-17 à géométrie variable.', NULL, '1955-09-07', NULL, 17.37, 8.93, 4.73, NULL, NULL, '1960-01-01', '1986-01-01', 'Union soviétique', 'Lyulka AL-7', 1874, 3, 'https://thumb.wikimedia.org/wikipedia/commons/thumb/3/34/Su7bkl_mob.jpg/1280px-Su7bkl_mob.jpg', 'Pibwl', 'Public domain', NULL, 'https://commons.wikimedia.org/wiki/File:Su7bkl_mob.jpg', 'Q170199', 'Sukhoi Su-7', ARRAY['sukhoi su-7', 'su-7', 'fitter-a', 'fitter', 'soukhoi su-7'], 'https://fr.wikipedia.org/wiki/Soukho%C3%AF_Su-7', '{"length_m":["https://www.wikidata.org/wiki/Q29042798"]}'::jsonb, true),
  -- Dassault Mirage III (Q234371)
  ('dassault-mirage-iii', 'Dassault Mirage III', 'Dassault Aviation', 'militaire', 'Le Mirage III est un avion multirôle conçu par le constructeur aéronautique français Dassault Aviation à la fin des années 1950. C''est le premier avion de combat de conception française et même européenne capable de dépasser une vitesse de Mach 2 en vol horizontal.', NULL, '1956-11-17', NULL, 14.8, 8.22, 4.25, NULL, 17983, '1961-01-01', NULL, 'France', 'Atar', 1422, 3, 'https://upload.wikimedia.org/wikipedia/commons/7/70/RAAF_Mirage.jpg', 'SSGT Marvin D. Lynchard', 'Public domain', NULL, 'https://commons.wikimedia.org/wiki/File:RAAF_Mirage.jpg', 'Q234371', 'Dassault Mirage III', ARRAY['dassault mirage iii', 'dassault-breguet mirage iii', 'mirage 3', 'mirage iii', 'dassault mirage', 'dassault md 550'], 'https://fr.wikipedia.org/wiki/Dassault_Mirage_III', '{"wingspan_m":["https://www.wikidata.org/wiki/Q29042798"],"units_built":["http://www.airwar.ru/enc/fighter/mirag3.html"]}'::jsonb, true),
  -- Yakovlev Yak-40 (Q505663)
  ('yakovlev-yak-40', 'Yakovlev Yak-40', 'Yakovlev / Saratov Aviation Plant', 'ligne', 'Le Yakovlev Yak-40 (Code OTAN : Codling) est un avion de transport régional triréacteur de la société soviétique puis russe Yakovlev. Son premier vol date de 1966. Il a été mis en service en septembre 1968 par l''Aeroflot.', NULL, '1966-10-21', 600, 20.36, 25, 6.5, 2000, 6000, '1968-09-01', NULL, 'Union soviétique', 'AI-25', 1011, 3, 'https://upload.wikimedia.org/wikipedia/commons/0/00/Tulpar_Air_Yakovlev_Yak-40.jpg', 'Sergey Riabsev', 'GFDL 1.2', 'http://www.gnu.org/licenses/old-licenses/fdl-1.2.html', 'https://commons.wikimedia.org/wiki/File:Tulpar_Air_Yakovlev_Yak-40.jpg', 'Q505663', 'Yakovlev Yak-40', ARRAY['yakovlev yak-40', 'yak-40', 'yak40', 'codling', 'yakovlev yak-40 codling'], 'https://fr.wikipedia.org/wiki/Yakovlev_Yak-40', '{"max_speed_kmh":["https://www.wikidata.org/wiki/Q56645322"],"length_m":["https://www.wikidata.org/wiki/Q29042798"],"wingspan_m":["https://www.wikidata.org/wiki/Q29042798"],"range_km":["https://www.wikidata.org/wiki/Q56645322"]}'::jsonb, true),
  -- Antonov An-22 (Q607444)
  ('antonov-an-22', 'Antonov An-22', 'Antonov / Association de construction aéronautique de Tachkent', 'ligne', 'L''Antonov An-22 Antée (en russe : « Антей », en ukrainien : « Антей » signifiant « Antée »), désigné par l''OTAN « Cock », est un avion cargo quadri-turbopropulseur d''origine soviétique.', NULL, '1965-02-27', 739, 57.8, 64.4, 4.39, 10936, 9100, '1969-01-01', '2024-01-01', 'Union soviétique', 'NK-12MA', 68, 4, 'https://upload.wikimedia.org/wikipedia/commons/6/6a/Antonov_An-22_2.jpg', 'Dmitry A. Mottl', 'CC BY-SA 3.0', 'https://creativecommons.org/licenses/by-sa/3.0', 'https://commons.wikimedia.org/wiki/File:Antonov_An-22_2.jpg', 'Q607444', 'Antonov An-22', ARRAY['antonov an-22', 'an22', 'antonov an-22 antheus', 'antonov an-22 cock', 'antei', 'cock', 'antaeus', 'an-22'], 'https://fr.wikipedia.org/wiki/Antonov_An-22', '{"first_flight":["https://www.wikidata.org/wiki/Q15048646"],"max_speed_kmh":["https://www.wikidata.org/wiki/Q56645322"],"length_m":["https://www.wikidata.org/wiki/Q29042798"],"wingspan_m":["https://www.wikidata.org/wiki/Q29042798"],"height_m":["https://www.wikidata.org/wiki/Q56645322"],"range_km":["https://www.wikidata.org/wiki/Q56645322"]}'::jsonb, true),
  -- X-1 (Q223365)
  ('bell-x-1', 'X-1', 'Bell', 'autre', 'Le XS-1 (rebaptisé X-1 en 1962) est un avion expérimental américain à moteur fusée. Il est le premier appareil à franchir le mur du son en vol horizontal (le 14 octobre 1947). Développé spécifiquement dans ce but dans le cadre du programme X-Planes de recherche de l''USAAF et du NACA (ancêtre de la NASA), il est construit par Bell Aircraft Corporation. Ressemblant à une balle dotée d''ailes minuscules et d''un moteur-fusée, il est conçu pour être largué depuis un bombardier B-29A Superfortress.', NULL, '1946-01-19', NULL, 9.4, 8.5, 3.3, NULL, NULL, NULL, NULL, 'États-Unis', 'Reaction Motors XLR11', NULL, 3, 'https://thumb.wikimedia.org/wikipedia/commons/thumb/0/05/Bell_X-1_in_flight.jpg/1280px-Bell_X-1_in_flight.jpg', 'http://afftc.edwards.af.mil/history/docs_html/aircraft/x-1_test_program.html archive copy at the Wayback Machine (photo link in first paragraph).', 'Public domain', NULL, 'https://commons.wikimedia.org/wiki/File:Bell_X-1_in_flight.jpg', 'Q223365', 'Bell X-1', ARRAY['x-1', 'bell x-1', 'bell x-s1'], 'https://fr.wikipedia.org/wiki/Bell_X-1', '{"first_flight":["https://www.nasa.gov/centers/armstrong/news/FactSheets/FS-085-DFRC.html"]}'::jsonb, true),
  -- Mikoyan-Gourevitch MiG-9 (Q270839)
  ('mikoyan-gurevich-mig-9', 'Mikoyan-Gourevitch MiG-9', 'Inconnu', 'militaire', 'Le Mikoyan-Gourevitch MiG-9 est un avion militaire soviétique à réaction construit après la Seconde Guerre mondiale. Il reçut le nom de code OTAN Fargo. Au total, 610 appareils furent construits, prototypes compris, et entrèrent en service en 1948 dans l''armée de l''air soviétique.', NULL, '1946-04-24', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'Union soviétique', 'BMW 003', 598, 3, 'https://thumb.wikimedia.org/wikipedia/commons/thumb/7/71/MiG-9_VVS_museum.jpg/1280px-MiG-9_VVS_museum.jpg', 'Mike1979 Russia', 'CC BY-SA 3.0', 'https://creativecommons.org/licenses/by-sa/3.0', 'https://commons.wikimedia.org/wiki/File:MiG-9_VVS_museum.jpg', 'Q270839', 'Mikoyan-Gurevich MiG-9', ARRAY['mikoyan-gurevich mig-9', 'mikoyan-gourevitch mig-9', 'type 1', 'fargo', 'mikoyan mig-9', 'mig9', 'mig-9'], 'https://fr.wikipedia.org/wiki/Mikoyan-Gourevitch_MiG-9', '{"units_built":["https://www.militaryfactory.com/aircraft/detail.php?aircraft_id=560"]}'::jsonb, true),
  -- De Havilland DH 106 Comet (Q26159)
  ('de-havilland-comet', 'De Havilland DH 106 Comet', 'De Havilland Aircraft Company', 'collection', 'Le de Havilland DH 106 Comet est le premier avion de ligne à réaction de l''histoire de l''aviation civile. Développé et construit par de Havilland dans son quartier général à Hatfield, dans le Hertfordshire au Royaume-Uni, le prototype Comet 1 effectue son premier vol le 27 juillet 1949. Il est doté d''un style aérodynamique épuré, avec quatre turboréacteurs de Havilland Ghost situés dans les ailes, un fuselage pressurisé et de grands hublots carrés.', NULL, '1949-07-27', NULL, 34, 35, NULL, 5190, NULL, '1952-05-02', '1997-03-14', 'Royaume-Uni', NULL, 114, 4, 'https://upload.wikimedia.org/wikipedia/commons/5/5e/BEA_de_Havilland_DH-106_Comet_4B_Berlin.jpg', 'BEA_De_Havilland_DH-106_Comet_4B_Manteufel.jpg: Ralf Manteufel derivative work: Altair78 (talk)', 'GFDL 1.2', 'http://www.gnu.org/licenses/old-licenses/fdl-1.2.html', 'https://commons.wikimedia.org/wiki/File:BEA_de_Havilland_DH-106_Comet_4B_Berlin.jpg', 'Q26159', 'De Havilland Comet', ARRAY['de havilland comet', 'de havilland dh 106 comet', 'dh 106 comet', 'comet', 'dh comet', 'dh.106'], 'https://fr.wikipedia.org/wiki/De_Havilland_Comet', '{"service_entry":["https://www.britishnewspaperarchive.co.uk/viewer/BL/0001578/19520510/047/0012","https://www.wikidata.org/wiki/Q856192"]}'::jsonb, true),
  -- Mirage F1 (Q319361)
  ('dassault-mirage-f1', 'Mirage F1', 'Dassault Aviation', 'militaire', 'Le Dassault Mirage F1 est un avion militaire conçu et construit en France par Dassault. Il se distingue des autres avions de la famille des Mirage par l''utilisation d''une aile en flèche, au lieu d''une aile delta. Décliné en version de reconnaissance et version d''attaque, il a été construit à plus de 700 exemplaires, utilisés par onze pays différents.', NULL, '1966-12-23', NULL, NULL, NULL, NULL, NULL, NULL, '1973-03-01', NULL, NULL, NULL, 730, 3, 'https://thumb.wikimedia.org/wikipedia/commons/thumb/c/c9/Ecuadorian_Air_Force_Dassault_Mirage_F1E.jpg/1280px-Ecuadorian_Air_Force_Dassault_Mirage_F1E.jpg', 'TSgt. Lou Hernandez, USAF', 'Public domain', NULL, 'https://commons.wikimedia.org/wiki/File:Ecuadorian_Air_Force_Dassault_Mirage_F1E.jpg', 'Q319361', 'Dassault Mirage F1', ARRAY['dassault mirage f1', 'mirage f1', 'mirage f-1'], 'https://fr.wikipedia.org/wiki/Dassault_Mirage_F1', '{}'::jsonb, true),
  -- Grumman F4F Wildcat (Q334612)
  ('grumman-f4f-wildcat', 'Grumman F4F Wildcat', 'Grumman', 'collection', 'Le Grumman F4F Wildcat est un avion de chasse embarqué américain mis en service en décembre 1940. Il fut utilisé par la marine et le corps des Marines américains ainsi que dans l''aéronavale britannique pendant la Seconde Guerre mondiale.', NULL, '1937-09-02', NULL, NULL, 11.6, 2.8, NULL, 10363, '1940-01-01', '1945-01-01', 'États-Unis', NULL, 7885, 2, 'https://thumb.wikimedia.org/wikipedia/commons/thumb/3/3e/FM-2_N86572_150502.JPG/1280px-FM-2_N86572_150502.JPG', 'Goshimini', 'CC BY-SA 4.0', 'https://creativecommons.org/licenses/by-sa/4.0', 'https://commons.wikimedia.org/wiki/File:FM-2_N86572_150502.JPG', 'Q334612', 'Grumman F4F Wildcat', ARRAY['grumman f4f wildcat', 'martlet', 'royal navy martlet', 'wildcat aircraft', 'grumman wildcat', 'general motors fm wildcat', 'fm wildcat', 'grumman g-36 wildcat', 'grumman g-36', 'g-36 wildcat', 'g-36', 'grumman g-52 wildcat', 'grumman g-52', 'g-52 wildcat', 'g-52', 'grumman g-53 wildcat', 'grumman g-53', 'g-53 wildcat', 'g-53', 'g-52 f4f-7', 'g-53 f4f-4', 'wildcat', 'grumman fighter design 4', 'f4f wildcat', '"wildcat"', 'f4f'], 'https://fr.wikipedia.org/wiki/Grumman_F4F_Wildcat', '{}'::jsonb, true),
  -- Antonov An-24 (Q337467)
  ('antonov-an-24', 'Antonov An-24', 'Antonov / Aviant', 'ligne', 'L''Antonov An-24 (Code OTAN : « Coke ») est un avion biturbopropulseur pouvant transporter 44 à 52 passagers fabriqué en URSS, (maintenant en Ukraine) par le bureau d''études Antonov. L''avion était prévu pour évoluer dans un environnement rustique et était particulièrement réussi, même à l’aune des standards occidentaux ; cependant sa rentabilité commerciale était faible, car il était handicapé par une masse à vide trop élevée.', NULL, '1959-12-20', NULL, 23.53, 29.2, 8.32, 2761, 8400, '1962-01-01', NULL, 'Union soviétique', 'AI-24', 1367, 3, 'https://upload.wikimedia.org/wikipedia/commons/e/e1/Mordovia_Airlines_Antonov_An-24.jpg', 'Dmitriy Pichugin', 'GFDL 1.2', 'http://www.gnu.org/licenses/old-licenses/fdl-1.2.html', 'https://commons.wikimedia.org/wiki/File:Mordovia_Airlines_Antonov_An-24.jpg', 'Q337467', 'Antonov An-24', ARRAY['antonov an-24', 'an24', 'coke', 'an-24', 'xian y7', 'antonov an-24rv'], 'https://fr.wikipedia.org/wiki/Antonov_An-24', '{}'::jsonb, true),
  -- Su-15 (Q461651)
  ('sukhoi-su-15', 'Su-15', 'Soukhoï / Novosibirsk Aircraft Production Association', 'militaire', 'Le Soukhoï Su-15 (en russe : « Сухой Су-15 »), code OTAN « Flagon », est un intercepteur tout-temps à long rayon d''action développé par l''URSS dans les années 1960. Construit à environ 1 300 exemplaires, le Su-15 a été mis en service de 1967 à 1996. Sa dernière évolution, le Su-15TM, est désignée Su-21 par certaines sources occidentales, bien qu''il semble que les Soviétiques n''aient jamais utilisé cette désignation.', NULL, '1962-05-30', NULL, 20.25, 9.15, NULL, NULL, NULL, '1965-04-30', '1996-01-01', 'Union soviétique', 'Toumansky R-13', 1300, 3, 'https://thumb.wikimedia.org/wikipedia/commons/thumb/c/c3/Su-15_Flagon.jpg/1280px-Su-15_Flagon.jpg', 'http://www.dodmedia.osd.mil (photo DN-ST-89-08430 - [1]', 'Public domain', NULL, 'https://commons.wikimedia.org/wiki/File:Su-15_Flagon.jpg', 'Q461651', 'Sukhoi Su-15', ARRAY['sukhoi su-15', 'su-15', 'su-15 flagon', 'sukhoi flagon', 'flagon', 'sukhoi su-15 flagon', 'sukhoï su-15', 'soukhoi su-15', 'soukhoï su-15'], 'https://fr.wikipedia.org/wiki/Soukho%C3%AF_Su-15', '{"length_m":["https://www.wikidata.org/wiki/Q29042798"],"wingspan_m":["https://www.wikidata.org/wiki/Q29042798"],"units_built":["http://www.sukhoi.org/planes/museum/su15/"],"service_entry":["http://www.airwar.ru/enc/fighter/su15.html"],"retirement":["http://www.sukhoi.org/planes/museum/su15/"]}'::jsonb, true),
  -- Messerschmitt Me 163 Komet (Q155360)
  ('messerschmitt-me-163-komet', 'Messerschmitt Me 163 Komet', 'Messerschmitt', 'collection', 'Le Messerschmitt Me 163 Komet (comète), conçu par Alexander Lippisch, fut le seul avion-fusée de chasse opérationnel de l''Histoire. Il nécessita un long développement par Messerschmitt et entra dans la guerre d''une manière très limitée seulement, en 1944. Il reste l''avion le plus rapide de la Seconde Guerre mondiale avec des pointes de vitesse à plus de 950 km/h. Il larguait ses roues au décollage, et atterrissait sur un patin ventral placé sous le fuselage.', NULL, '1941-09-01', NULL, NULL, 9.3, 2.5, NULL, NULL, '1944-01-01', NULL, 'Reich allemand', NULL, NULL, 3, 'https://thumb.wikimedia.org/wikipedia/commons/thumb/7/71/Messerschmitt_Me_163B_USAF.jpg/1280px-Messerschmitt_Me_163B_USAF.jpg', 'USAF', 'Public domain', NULL, 'https://commons.wikimedia.org/wiki/File:Messerschmitt_Me_163B_USAF.jpg', 'Q155360', 'Messerschmitt Me 163 Komet', ARRAY['messerschmitt me 163 komet', 'me163', 'komet', 'messerschmitt komet', 'me 163 komet', 'me 163'], 'https://fr.wikipedia.org/wiki/Messerschmitt_Me_163_Komet', '{}'::jsonb, true),
  -- Lockheed P-3 Orion (Q155490)
  ('lockheed-p-3-orion', 'Lockheed P-3 Orion', 'Lockheed / Lockheed Martin', 'militaire', 'Le Lockheed P-3 Orion est un avion de patrouille maritime quadrimoteur à hélices mis en œuvre dans le monde entier. Le P-3 Orion est un dérivé militaire du projet d''avion civil Lockheed L-188 Electra.', NULL, '1959-11-01', NULL, 35.61, 30.37, NULL, NULL, 8626, '1962-01-01', NULL, 'États-Unis', 'Allison 501 family', 757, 3, 'https://thumb.wikimedia.org/wikipedia/commons/thumb/6/67/US_Navy_030129-N-0226M-002_P-3C_Orion.jpg/1280px-US_Navy_030129-N-0226M-002_P-3C_Orion.jpg', 'U.S. Navy photo by Senior Chief Photographer’s Mate Mahlon K. Miller.', 'Public domain', NULL, 'https://commons.wikimedia.org/wiki/File:US_Navy_030129-N-0226M-002_P-3C_Orion.jpg', 'Q155490', 'Lockheed P-3 Orion', ARRAY['lockheed p-3 orion', 'orion maritime patrol aircraft', 'p3v orion', 'lockheed p3v orion', 'p3 orion', 'lockheed orion', 'orion', 'p-3c orion', 'cp-140 aurora', 'lockheed p-3 orions', 'p-3 orion', 'p3v'], 'https://fr.wikipedia.org/wiki/Lockheed_P-3_Orion', '{"length_m":["https://www.wikidata.org/wiki/Q29042798"],"wingspan_m":["https://www.wikidata.org/wiki/Q29042798"]}'::jsonb, true),
  -- HAL Tejas (Q175940)
  ('hal-tejas', 'HAL Tejas', 'Hindustan Aeronautics', 'militaire', 'Le HAL LCA Tejas (du mot tejas signifiant « éclat, brillance » en sanskrit) est un avion multirôle monoplace développé par l''Inde appartenant, selon la presse indienne, à la catégorie des avions de chasse de la quatrième génération. Le premier avion de série a été livré le 17 janvier 2015, une version non définitive de la tranche SP1.', NULL, '2001-01-04', NULL, NULL, NULL, NULL, NULL, NULL, '2016-07-01', NULL, 'Inde', NULL, NULL, 3, 'https://thumb.wikimedia.org/wikipedia/commons/thumb/7/78/HAL_Tejas.jpg/1280px-HAL_Tejas.jpg', 'Rahuldevnath', 'CC BY 3.0', 'https://creativecommons.org/licenses/by/3.0', 'https://commons.wikimedia.org/wiki/File:HAL_Tejas.jpg', 'Q175940', 'HAL Tejas', ARRAY['tejas', 'hal tejas'], 'https://fr.wikipedia.org/wiki/HAL_Tejas', '{"service_entry":["https://www.wikidata.org/wiki/Q112858423"]}'::jsonb, true),
  -- McDonnell Douglas MD-80/MD-90 (Q207400)
  ('mcdonnell-douglas-md-80', 'McDonnell Douglas MD-80/MD-90', 'McDonnell Douglas / Boeing Commercial Airplanes', 'ligne', 'Le McDonnell Douglas MD-80 est un avion de ligne américain qui était fabriqué par le constructeur aéronautique McDonnell Douglas. Ce dernier développa et commercialisa ensuite une évolution, le MD-90. Après avoir racheté McDonnell Douglas en 1997, Boeing fait évoluer l''appareil, sous le nom de Boeing 717.', NULL, '1979-10-18', NULL, 41.3, 32.85, NULL, NULL, NULL, '1980-10-10', NULL, 'États-Unis', NULL, 1191, 3, 'https://thumb.wikimedia.org/wikipedia/commons/thumb/3/33/Andes_L%C3%ADneas_A%C3%A9reas_MD-83_%28LV-BTH%29%2C_February_2009.jpg/1280px-Andes_L%C3%ADneas_A%C3%A9reas_MD-83_%28LV-BTH%29%2C_February_2009.jpg', 'Luis Argerich from Buenos Aires, Argentina', 'CC BY 2.0', 'https://creativecommons.org/licenses/by/2.0', 'https://commons.wikimedia.org/wiki/File:Andes_L%C3%ADneas_A%C3%A9reas_MD-83_(LV-BTH),_February_2009.jpg', 'Q207400', 'McDonnell Douglas MD-80', ARRAY['mcdonnell douglas md-80/md-90 family', 'mcdonnell douglas md-80/md-90', 'mcdonnell douglas md-80', 'md80', 'dc-9 super 80', 'mcdonnell douglas dc-9 series 80', 'mcdonnell douglas dc-9-80', 'dc-9 series 80', 'douglas md-80', 'mcdonnell douglas dc-9 super 80', 'dc-9-80', 'md 83', 'md-83', 'mcdonnell douglas md-80 / md-90', 'mcdonnell douglas md-83', 'mcdonnell douglas md-90'], 'https://fr.wikipedia.org/wiki/McDonnell_Douglas_MD-80', '{"length_m":["https://www.wikidata.org/wiki/Q29042798"],"wingspan_m":["https://www.wikidata.org/wiki/Q29042798"]}'::jsonb, true),
  -- Avro Vulcan (Q218931)
  ('avro-vulcan', 'Avro Vulcan', 'Avro / Hawker-Siddeley', 'collection', '2 est un bombardier stratégique qui a été utilisé par la Royal Air Force de 1953 à 1984. Avec le Handley Page Victor et le Vickers Valiant, il faisait partie du trio des V bombers dont le Royaume-Uni lança le développement en 1947 pour le Royal Air Force Bomber Command.', NULL, '1952-08-30', NULL, NULL, 30.3, NULL, NULL, 16764, '1956-07-20', '1984-03-01', 'Royaume-Uni', NULL, 136, 4, 'https://thumb.wikimedia.org/wikipedia/commons/thumb/f/fc/Avro_Vulcan_Bomber_RAF.JPEG/1280px-Avro_Vulcan_Bomber_RAF.JPEG', 'Sgt. David S. Nolan, US Air Force', 'Public domain', NULL, 'https://commons.wikimedia.org/wiki/File:Avro_Vulcan_Bomber_RAF.JPEG', 'Q218931', 'Avro Vulcan', ARRAY['avro vulcan', 'avro 698 vulcan', 'vulcan bomber', 'hawker siddeley vulcan', 'vulcan aircraft'], 'https://fr.wikipedia.org/wiki/Avro_Vulcan', '{}'::jsonb, true),
  -- Douglas DC-9 (Q221414)
  ('mcdonnell-douglas-dc-9', 'Douglas DC-9', 'McDonnell Douglas / Douglas', 'ligne', 'Le Douglas DC-9 est un avion de ligne court-moyen-courrier à fuselage étroit conçu et développé par la Douglas Aircraft Company dans les années 1960. Produit à partir de 1965 par Douglas devenu McDonnell Douglas après sa fusion avec la McDonnell Aircraft Corporation, il est commandé à plus de 900 exemplaires dont les derniers sont livrés au début des années 1980.', NULL, '1965-02-25', NULL, 31.8, 27.2, 8.38, NULL, 11295, '1965-12-08', NULL, 'États-Unis', NULL, 976, 3, 'https://thumb.wikimedia.org/wikipedia/commons/thumb/b/ba/Northwest_N756NW_DC9.JPG/1280px-Northwest_N756NW_DC9.JPG', 'Anthony92931', 'CC BY-SA 3.0', 'https://creativecommons.org/licenses/by-sa/3.0', 'https://commons.wikimedia.org/wiki/File:Northwest_N756NW_DC9.JPG', 'Q221414', 'McDonnell Douglas DC-9', ARRAY['douglas dc-9', 'mcdonnell douglas dc-9', 'mdd dc-9', 'dc9', 'dc-9', 'mcdonnell-douglas dc-9'], 'https://fr.wikipedia.org/wiki/Douglas_DC-9', '{}'::jsonb, true),
  -- General Dynamics F-111 Aardvark (Q270990)
  ('general-dynamics-f-111-aardvark', 'General Dynamics F-111 Aardvark', 'General Dynamics', 'militaire', 'Le General Dynamics F-111 Aardvark est un bombardier tout-temps à géométrie variable développé par les États-Unis dans les années 1960. La mise au point de cet avion a été difficile mais, une fois tous les problèmes résolus, le F-111 s''est révélé être une arme redoutable et très fiable. Il a été construit à 554 exemplaires. En décembre 2010, il est retiré du service par l''armée australienne, la dernière à en posséder en service.', NULL, '1964-12-21', NULL, 22.4, 19.2, 5.22, NULL, 18290, '1967-07-18', '1998-01-01', 'États-Unis', 'Pratt & Whitney TF30', 563, 3, 'https://thumb.wikimedia.org/wikipedia/commons/thumb/a/aa/F-111_2.jpg/1280px-F-111_2.jpg', NULL, 'Public domain', NULL, 'https://commons.wikimedia.org/wiki/File:F-111_2.jpg', 'Q270990', 'General Dynamics F-111 Aardvark', ARRAY['general dynamics f-111 aardvark', 'aardvark', 'f-111'], 'https://fr.wikipedia.org/wiki/General_Dynamics_F-111_Aardvark', '{"length_m":["https://www.wikidata.org/wiki/Q29042798"],"wingspan_m":["https://www.wikidata.org/wiki/Q29042798"]}'::jsonb, true),
  -- Northrop F-5 (Q308940)
  ('northrop-f-5', 'Northrop F-5', 'Northrop Corporation', 'militaire', 'Le Northrop F-5 est une famille d''avions de chasse légers et maniables, conçus et fabriqués par Northrop aux États-Unis à partir de l''année 1962. Il existe deux modèles principaux : les versions F-5A et F-5B Freedom Fighter originales, et celles F-5E et F-5F Tiger II largement mises à jour.', NULL, '1959-07-30', NULL, 14.45, 8.13, 4.08, NULL, NULL, '1962-01-01', NULL, 'États-Unis', 'J85', NULL, 3, 'https://thumb.wikimedia.org/wikipedia/commons/thumb/8/85/Northrop_F-5E_%28Tail_No._01557%29_061006-F-1234S-073.jpg/1280px-Northrop_F-5E_%28Tail_No._01557%29_061006-F-1234S-073.jpg', 'National Museum of USAF', 'Public domain', NULL, 'https://commons.wikimedia.org/wiki/File:Northrop_F-5E_(Tail_No._01557)_061006-F-1234S-073.jpg', 'Q308940', 'Northrop F-5', ARRAY['northrop f-5', 'rf-5 tiger eye', 'northrop f-5e tiger ii', 'f-5', 'f-5 freedom fighter', 'northrop f-5 freedom fighter'], 'https://fr.wikipedia.org/wiki/Northrop_F-5_Freedom_Fighter', '{"wingspan_m":["https://www.wikidata.org/wiki/Q29042798"]}'::jsonb, true),
  -- Yakovlev Yak-9 (Q562475)
  ('yakovlev-yak-9', 'Yakovlev Yak-9', 'Yakovlev / Tushino Machine-Building Plant', 'collection', 'Le Yakovlev Yak-9 est un avion de chasse soviétique de la Seconde Guerre mondiale employé par l''Armée rouge à partir de 1942 jusqu''à la guerre de Corée. Son point faible était la surpuissance du moteur comparée au poids de l''avion.', NULL, '1942-01-01', NULL, 8.5, 9.74, NULL, 848, 10750, '1942-01-01', '1950-01-01', NULL, 'Klimov M-105', 16769, 1, 'https://thumb.wikimedia.org/wikipedia/commons/thumb/3/37/Yak-9-1978.jpg/1280px-Yak-9-1978.jpg', 'Leo Medvedev/Лев Леонидович Медведев', 'CC BY-SA 4.0', 'https://creativecommons.org/licenses/by-sa/4.0', 'https://commons.wikimedia.org/wiki/File:Yak-9-1978.jpg', 'Q562475', 'Yakovlev Yak-9', ARRAY['yakovlev yak-9', 'frank', 'yak-9', 'yakovlev 9', 'yakovlev yak-9189'], 'https://fr.wikipedia.org/wiki/Yakovlev_Yak-9', '{}'::jsonb, true),
  -- Consolidated PBY Catalina (Q648864)
  ('consolidated-pby-catalina', 'Consolidated PBY Catalina', 'Consolidated Aircraft Corporation / Canadian Vickers', 'collection', 'Le Consolidated PBY Catalina est un hydravion militaire conçu dans les années 1930 aux États-Unis. ). Très fiable et capable de parcourir de grandes distances, le Catalina a été construit à environ 4 000 exemplaires, dont une partie au Canada et en URSS. Il a été utilisé par plus de 25 pays différents, y compris comme avion de transport civil. ], employés comme bombardiers d''eau dans le cadre de la lutte contre les feux de forêt.', NULL, '1935-03-28', NULL, 19.46, 31.7, 6.15, 4030, 4000, '1936-01-01', '1957-01-01', 'États-Unis', 'R-1830 Twin Wasp', 3305, 2, 'https://thumb.wikimedia.org/wikipedia/commons/thumb/6/66/Consolidated_PBY_Catalina%2C_Fantasy_Of_Flight_Museum%2C_Florida_%281%29.jpg/1280px-Consolidated_PBY_Catalina%2C_Fantasy_Of_Flight_Museum%2C_Florida_%281%29.jpg', 'Greg Goebel', 'CC BY-SA 2.0', 'https://creativecommons.org/licenses/by-sa/2.0', 'https://commons.wikimedia.org/wiki/File:Consolidated_PBY_Catalina,_Fantasy_Of_Flight_Museum,_Florida_(1).jpg', 'Q648864', 'Consolidated PBY Catalina', ARRAY['consolidated pby catalina', 'catalina', 'mop', 'pbn nomad', 'nomad', 'consolidated model 28', 'model 28', 'canso', 'pby catalina', 'pby', 'naval aircraft factory pbn'], 'https://fr.wikipedia.org/wiki/Consolidated_PBY_Catalina', '{}'::jsonb, true),
  -- Douglas SBD Dauntless (Q118070)
  ('douglas-sbd-dauntless', 'Douglas SBD Dauntless', 'Douglas', 'collection', 'Le Douglas SBD Dauntless (SB pour Scout Bomber, en français « appareil de reconnaissance et bombardier », D pour Dive en francais en piqué) était un biplace embarqué de bombardement en piqué solide et sûr, qui encaissait assez bien les projectiles adverses. Sous-motorisé, vulnérable, fatigant à piloter, le Dauntless n''en fut pas moins apprécié par ses équipages qui le surnommèrent Slow But Deadly (« Lent mais mortel »).', NULL, '1940-05-01', NULL, NULL, 12.66, 4.14, 1795, 7780, '1940-01-01', '1959-01-01', 'États-Unis', NULL, 5936, 2, 'https://thumb.wikimedia.org/wikipedia/commons/thumb/c/ca/Douglas_SBD-5_Dauntless_Feb1944.png/1280px-Douglas_SBD-5_Dauntless_Feb1944.png', 'U.S. Navy', 'Public domain', NULL, 'https://commons.wikimedia.org/wiki/File:Douglas_SBD-5_Dauntless_Feb1944.png', 'Q118070', 'Douglas SBD Dauntless', ARRAY['douglas sbd dauntless', 'douglas dauntless', 'douglas scout bomber', 'dauntless', 'douglas scout bomber design 1', 'sbd dauntless', 'sbd', 'douglas sbd', 'sdb dauntless', 'douglas a-24 banshee'], 'https://fr.wikipedia.org/wiki/Douglas_SBD_Dauntless', '{}'::jsonb, true),
  -- Bristol Blenheim (Q330417)
  ('bristol-blenheim', 'Bristol Blenheim', 'Bristol Aeroplane Company', 'collection', 'Le Bristol Blenheim (prononciation anglaise /ˈblɛnɪm/) est un bombardier léger rapide triplace britannique de la Seconde Guerre mondiale. Issu d’un projet civil, ce bimoteur a été le premier monoplan métallique à aile cantilever à entrer en service dans la RAF.', NULL, '1935-04-12', NULL, 12.98, 17.17, NULL, 2352, NULL, '1937-01-01', '1944-01-01', NULL, 'Bristol Mercury', 4422, 2, 'https://upload.wikimedia.org/wikipedia/commons/d/d3/Bristol_Blenheim_ExCC.jpg', 'Canadian Forces Expired crown copyright. All images made by canadian forces more than 50 years ago.', 'Public domain', NULL, 'https://commons.wikimedia.org/wiki/File:Bristol_Blenheim_ExCC.jpg', 'Q330417', 'Bristol Blenheim', ARRAY['bristol blenheim', 'bristol 149', 'bristol 142', 'bristol bolingbroke', 'bristol 160', 'bristol 143', 'blenheim'], 'https://fr.wikipedia.org/wiki/Bristol_Blenheim', '{}'::jsonb, true),
  -- Boeing 737 MAX (Q139289)
  ('boeing-737-max', 'Boeing 737 MAX', 'Boeing Commercial Airplanes / Boeing', 'ligne', 'Le Boeing 737 Max, souvent stylisé Boeing 737 MAX ou raccourci Boeing 737-8, est la quatrième génération de la famille d''avions 737. Construite depuis 2015 par Boeing Commercial Airplanes, cette génération est basée sur le 737 Next Generation qu''elle doit remplacer. Le 737 Max se différencie principalement du 737 NG par l''implantation de plus gros moteurs CFM International LEAP-1B et par d''autres modifications aérodynamiques concernant la cellule et les ailettes distinctives.', NULL, '2016-01-29', NULL, NULL, 35.9, NULL, NULL, NULL, '2017-05-22', NULL, 'États-Unis', 'CFM International LEAP', 370, 4, 'https://upload.wikimedia.org/wikipedia/commons/d/d9/C-FSJJ_%2843123199145%29.jpg', 'Mark Harkin', 'CC BY 2.0', 'https://creativecommons.org/licenses/by/2.0', 'https://commons.wikimedia.org/wiki/File:C-FSJJ_(43123199145).jpg', 'Q139289', 'Boeing 737 MAX', ARRAY['boeing 737 max', '737 max', 'b737 max', '737max', 'b737max'], 'https://fr.wikipedia.org/wiki/Boeing_737_Max', '{"wingspan_m":["https://www.boeing.com/commercial/737max/"]}'::jsonb, true),
  -- Yakovlev Yak-42 (Q505649)
  ('yakovlev-yak-42', 'Yakovlev Yak-42', 'Saratov Aviation Plant / usine aéronautique de Smolensk', 'ligne', 'Le Yakovlev Yak-42 est un avion de ligne triréacteur fabriqué par le constructeur aéronautique russe Yakovlev. Il a été développé pour remplacer les Tupolev Tu-134 et les Antonov An-24. Le premier des trois prototypes a volé pour la première fois le 7 mars 1975 (nom de code de l''OTAN : Clobber) et le premier appareil de production est entré en service en 1980 chez le transporteur russe Aeroflot.', NULL, '1975-03-07', NULL, 36.38, 34.9, NULL, NULL, NULL, '1980-12-22', NULL, 'Union soviétique', 'Ivtchenko-Progress D-36', 183, 4, 'https://upload.wikimedia.org/wikipedia/commons/c/c6/Yak-42D_%285742470447%29.jpg', 'Dmitry Terekhov from Odintsovo, Russian Federation', 'CC BY-SA 2.0', 'https://creativecommons.org/licenses/by-sa/2.0', 'https://commons.wikimedia.org/wiki/File:Yak-42D_(5742470447).jpg', 'Q505649', 'Yakovlev Yak-42', ARRAY['yakovlev yak-42', 'yakovlev yak-42 clobber', 'clobber', 'yak42', 'iak-42', 'iakovlev iak-42', 'yakovlev yak-42d'], 'https://fr.wikipedia.org/wiki/Yakovlev_Yak-42', '{"first_flight":["https://www.ecured.cu/Yakovlev_Yak-42"],"length_m":["https://www.wikidata.org/wiki/Q29042798"],"wingspan_m":["https://www.wikidata.org/wiki/Q29042798"]}'::jsonb, true),
  -- Fokker F27 (Q506736)
  ('fokker-f27-friendship', 'Fokker F27', 'Fokker', 'ligne', 'Le Fokker F27 est un avion à turbopropulseurs court courrier de 44 places, développé et produit par le constructeur néerlandais Fokker, et conçu pour succéder au DC-3. Le premier vol eut lieu le 24 novembre 1955 et le premier exemplaire fut livré à Aer Lingus en novembre 1958.', NULL, '1955-11-24', NULL, 25.06, 29, 8.72, NULL, 9935, '1958-06-01', NULL, 'Pays-Bas', NULL, 793, 3, 'https://upload.wikimedia.org/wikipedia/commons/4/4c/Busy_Bee_F-27_at_Basel_1982.jpg', 'Eduard Marmet', 'CC BY-SA 3.0', 'https://creativecommons.org/licenses/by-sa/3.0', 'https://commons.wikimedia.org/wiki/File:Busy_Bee_F-27_at_Basel_1982.jpg', 'Q506736', 'Fokker F27 Friendship', ARRAY['fokker f27 friendship', 'fokker f27', 'fokker friendship', 'f-27 friendship', 'fokker f-27 friendship', 'friendship', 'f27 friendship', 'fokker 27', 'fokker f.27', 'fairchild f.27'], 'https://fr.wikipedia.org/wiki/Fokker_F27', '{}'::jsonb, true),
  -- Polikarpov I-16 (Q641977)
  ('polikarpov-i-16', 'Polikarpov I-16', 'Nikolaï Polikarpov / Moscow Aviation Plant № 39', 'collection', 'Le Polikarpov I-16 Ichak (du russe Ишак, âne ou petit mulet) était un avion de chasse soviétique, qui vola pour la première fois en décembre 1933, et entra en service en 1935. Sa structure était plutôt traditionnelle, mais il fut le premier avion militaire à être pourvu d''un train d''atterrissage entièrement escamotable (manœuvré manuellement par le pilote). À sa sortie il était le chasseur le plus léger et le plus rapide du monde.', NULL, '1933-12-30', 489, 6.13, 9, NULL, 400, 10800, '1934-01-01', '1944-01-01', NULL, 'Bristol Jupiter / R-1820 Cyclone 9', 8644, 2, 'https://upload.wikimedia.org/wikipedia/commons/f/f9/OSH2003_Polikarpov_I-16.jpg', 'Vassilii Khachaturov (en:user:BACbKA) and Alexei Tsekoun (taking the picture)', 'CC BY-SA 3.0', 'http://creativecommons.org/licenses/by-sa/3.0/', 'https://commons.wikimedia.org/wiki/File:OSH2003_Polikarpov_I-16.jpg', 'Q641977', 'Polikarpov I-16', ARRAY['polikarpov i-16', 'mosca', 'rata', 'uti-1', 'tskb-12', 'ishachok', 'uti-4', 'ishak', 'tskb-18', 'i-16uti', 'tskb-29', 'uti-2', 'i-16'], 'https://fr.wikipedia.org/wiki/Polikarpov_I-16', '{"max_speed_kmh":["https://www.wikidata.org/wiki/Q15058267"],"length_m":["https://www.wikidata.org/wiki/Q15058267"],"wingspan_m":["https://www.wikidata.org/wiki/Q15058267"],"range_km":["https://www.wikidata.org/wiki/Q15058267"],"ceiling_m":["https://www.wikidata.org/wiki/Q15058267"]}'::jsonb, true),
  -- Douglas C-47 Skytrain (Q714326)
  ('douglas-c-47-skytrain', 'Douglas C-47 Skytrain', 'Douglas', 'collection', 'Douglas C-47 Skytrain est la désignation officielle donnée par l''United States Army Air Forces à la version militaire la plus construite du DC-3. Avion de transport polyvalent, robuste et d''entretien aisé, il fut utilisé sur tous les fronts durant la Seconde Guerre mondiale. Baptisé Dakota par la Royal Air Force, qui avait utilisé des DC-3 avant les premières commandes militaires américaines, il fut affectueusement surnommé Gooney Bird par ses équipages américains.', NULL, '1941-12-23', NULL, 19.64, 28.95, 5.16, 2400, 7000, NULL, NULL, 'États-Unis', NULL, 10174, 1, 'https://thumb.wikimedia.org/wikipedia/commons/thumb/6/68/C-47_Dakota_-_Chino_Airshow_2014_%2815867578416%29.jpg/1280px-C-47_Dakota_-_Chino_Airshow_2014_%2815867578416%29.jpg', 'Airwolfhound from Hertfordshire, UK', 'CC BY-SA 2.0', 'https://creativecommons.org/licenses/by-sa/2.0', 'https://commons.wikimedia.org/wiki/File:C-47_Dakota_-_Chino_Airshow_2014_(15867578416).jpg', 'Q714326', 'Douglas C-47 Skytrain', ARRAY['douglas c-47', 'douglas c-47 skytrain', 'dakota', 'skytrain', 'gooney bird', 'cc-129', 'c-47 dakota', 'r4d', 'douglas dc-3', 'c-47 skytrooper', 'douglas yc-129 super dakota', 'douglas cc-129 dakota', 'douglas c-117 super dakota', 'c-47 skytrain'], 'https://fr.wikipedia.org/wiki/Douglas_C-47_Skytrain', '{}'::jsonb, true),
  -- Grumman Avenger (Q734103)
  ('grumman-tbf-avenger', 'Grumman Avenger', 'Grumman / General Motors', 'collection', 'Le Grumman TBF Avenger (désigné aussi TBM pour ceux qui ont été construits par la division Eastern Aircraft de General Motors) est un bombardier-torpilleur américain initialement développé pour la Marine des États-Unis et le Corps des Marines des États-Unis et utilisé par un grand nombre de forces aériennes dans le monde. Il entra en service en 1942 et fut utilisé pour la première fois au cours de la bataille de Midway.', NULL, '1941-08-07', NULL, NULL, NULL, NULL, NULL, NULL, '1942-02-01', '1960-01-01', 'États-Unis', NULL, 9839, 2, 'https://thumb.wikimedia.org/wikipedia/commons/thumb/f/fb/Grumman_TBM_Avenger%2C_Chino%2C_California.jpg/1280px-Grumman_TBM_Avenger%2C_Chino%2C_California.jpg', 'Greg Goebel', 'CC BY-SA 2.0', 'https://creativecommons.org/licenses/by-sa/2.0', 'https://commons.wikimedia.org/wiki/File:Grumman_TBM_Avenger,_Chino,_California.jpg', 'Q734103', 'Grumman TBF Avenger', ARRAY['grumman avenger', 'grumman tbf avenger', 'general motors avenger', 'general motors tbm avenger', 'tbm avenger', 'grumman tarpon', 'grumman g-40 avenger', 'g-40 avenger', 'g-40', 'tbm', 'avenger', 'tbf avenger', 'tbf-1 avenger'], 'https://fr.wikipedia.org/wiki/Grumman_TBF_Avenger', '{}'::jsonb, true)
