  ('embraer-e-jet-family', 'E-Jet', 'Embraer', 'ligne', 'famille d’avions régionaux', NULL, '2002-02-19', NULL, NULL, NULL, NULL, NULL, NULL, '2004-03-17', NULL, 'Brésil', NULL, 1544, 3, 'https://thumb.wikimedia.org/wikipedia/commons/thumb/d/d8/EI-RDB_Embraer_175_Alitalia_BCN.jpg/1280px-EI-RDB_Embraer_175_Alitalia_BCN.jpg', 'Bene Riobó', 'CC BY-SA 4.0', 'https://creativecommons.org/licenses/by-sa/4.0', 'https://commons.wikimedia.org/wiki/File:EI-RDB_Embraer_175_Alitalia_BCN.jpg', 'Q3495319', 'Embraer E-Jet family', ARRAY['e-jet', 'embraer e-jet family', 'embraer e-jets'], 'https://en.wikipedia.org/wiki/Embraer_E-Jet_family', '{"units_built":["https://ri.embraer.com.br/Download.aspx?Arquivo=cbPtkHhVECgvyclYjI0N7Q=="]}'::jsonb, true),
  -- Saab 35 Draken (Q461475)
  ('saab-35-draken', 'Saab 35 Draken', 'Saab', 'collection', 'Le Saab J35 Draken (« Dragon » ou « cerf-volant ») est un avion de chasse conçu et construit par la Suède, successeur du Saab J 29 Tunnan. Il se caractérise par une aile en double delta et pouvait atteindre la vitesse de Mach 2,0 à partir de la version J 35D. Environ 600 Draken ont été construits au total, mis en service dans quatre armées de l''air jusqu''au début des années 2000.', NULL, '1955-10-25', NULL, 15.4, 9.4, NULL, NULL, NULL, '1959-01-01', '2005-01-01', 'Suède', 'Rolls-Royce Avon', 644, 3, 'https://thumb.wikimedia.org/wikipedia/commons/thumb/5/5e/Draken_Swedish_Air_Force_%2827882427885%29.jpg/1280px-Draken_Swedish_Air_Force_%2827882427885%29.jpg', 'Rob Schleiffert from Holland', 'CC BY-SA 2.0', 'https://creativecommons.org/licenses/by-sa/2.0', 'https://commons.wikimedia.org/wiki/File:Draken_Swedish_Air_Force_(27882427885).jpg', 'Q461475', 'Saab 35 Draken', ARRAY['saab 35 draken', 'saab draken', 'j 35', 's 35', 'draken', '35 draken'], 'https://fr.wikipedia.org/wiki/Saab_35_Draken', '{"length_m":["https://www.wikidata.org/wiki/Q29042798"],"wingspan_m":["https://www.wikidata.org/wiki/Q29042798"]}'::jsonb, true),
  -- Boeing B-47 Stratojet (Q467649)
  ('boeing-b-47-stratojet', 'Boeing B-47 Stratojet', 'Boeing', 'collection', 'Le Boeing B-47 Stratojet est un bombardier moyen à réaction et à long rayon d''action mis en service en 1951 dans l''United States Air Force (USAF). Conçu par la société Boeing Company et produit par l''avionneur ainsi que par des sous-traitants, il est construit à plus de 2 000 exemplaires. Propulsé par six turboréacteurs, il a une vitesse de croisière de plus de 900 km/h et peut voler à plus de 12 000 mètres d''altitude.', NULL, '1947-12-17', NULL, 32.65, 35.37, 8.54, 7478, NULL, '1951-06-01', '1969-01-01', 'États-Unis', NULL, 2032, 2, 'https://thumb.wikimedia.org/wikipedia/commons/thumb/9/97/Boeing_XB-47D_Stratojet_testbed_for_Wright_YT49_turboprop_engine.jpg/1280px-Boeing_XB-47D_Stratojet_testbed_for_Wright_YT49_turboprop_engine.jpg', 'USAF', 'Public domain', NULL, 'https://commons.wikimedia.org/wiki/File:Boeing_XB-47D_Stratojet_testbed_for_Wright_YT49_turboprop_engine.jpg', 'Q467649', 'Boeing B-47 Stratojet', ARRAY['b-47 stratojet', 'boeing b-47 stratojet', 'b-47', 'boeing b-47', 'canadair cl-52'], 'https://fr.wikipedia.org/wiki/Boeing_B-47_Stratojet', '{}'::jsonb, true),
  -- Fokker 100 (Q257298)
  ('fokker-100', 'Fokker 100', 'Fokker', 'ligne', 'Le Fokker F100 est un biréacteur court courrier (2 500 km d''autonomie à la charge maxi) d''une centaine de places fabriqué par Fokker. Des coûts opérationnels bas et peu de compétition dans sa catégorie ont fait de cet avion un grand succès commercial à la fin des années 1980. Cependant, les améliorations apportées aux Boeing 737 et Airbus A319 affectèrent les ventes de ce modèle. La production s''est arrêtée en 1997 avec, au total, 283 unités livrées.', NULL, '1986-11-30', NULL, 35.53, 28.08, 8.6, 2450, 10668, '1988-04-03', NULL, 'Pays-Bas', 'Rolls-Royce RB.183 Tay', 283, 4, 'https://thumb.wikimedia.org/wikipedia/commons/thumb/b/b3/Klm_cityhopper_fokker100_ph-kle_arp.jpg/1280px-Klm_cityhopper_fokker100_ph-kle_arp.jpg', 'Arpingstone', 'Public domain', NULL, 'https://commons.wikimedia.org/wiki/File:Klm_cityhopper_fokker100_ph-kle_arp.jpg', 'Q257298', 'Fokker 100', ARRAY['fokker 100', 'fokker f100', 'f100', '100'], 'https://fr.wikipedia.org/wiki/Fokker_F100', '{"length_m":["https://www.wikidata.org/wiki/Q29042798"],"wingspan_m":["https://www.wikidata.org/wiki/Q29042798"]}'::jsonb, true),
  -- Antonov An-30 (Q607609)
  ('antonov-an-30', 'Antonov An-30', 'Antonov', 'militaire', 'L''Antonov An-30 (Code OTAN : Clank) est un avion biturbopropulseur dérivé de l''An-24, destiné à la reconnaissance et à la cartographie.', NULL, '1974-01-01', NULL, 24.26, 29.2, NULL, NULL, NULL, '1975-01-01', NULL, 'Union soviétique', 'AI-24', 123, 4, 'https://upload.wikimedia.org/wikipedia/commons/d/d0/An-30_-_RA-26226.jpg', 'Gartenfreuden (Wolfgang)', 'CC BY-SA 3.0', 'https://creativecommons.org/licenses/by-sa/3.0', 'https://commons.wikimedia.org/wiki/File:An-30_-_RA-26226.jpg', 'Q607609', 'Antonov An-30', ARRAY['antonov an-30', 'clank', 'an30'], 'https://fr.wikipedia.org/wiki/Antonov_An-30', '{"first_flight":["https://www.wikidata.org/wiki/Q15048646"],"length_m":["https://www.wikidata.org/wiki/Q29042798"],"wingspan_m":["https://www.wikidata.org/wiki/Q29042798"]}'::jsonb, true),
  -- Vickers Wellington (Q850244)
  ('vickers-wellington', 'Vickers Wellington', 'Vickers-Armstrongs', 'collection', 'Le Vickers Wellington est un bombardier moyen bimoteur britannique conçu dans les années 1930. Il a été employé couramment pendant les deux premières années de la Seconde Guerre mondiale avant d''être remplacé par des bombardiers quadrimoteurs beaucoup plus grands, comme l''Avro Lancaster. Le Wellington a été appelé populairement « Wimpy » par le personnel de service d''après le personnage J. Wellington Wimpy de dessins animés de Popeye.', NULL, '1936-06-15', NULL, 19.68, 26.27, 5.31, 4106, 5490, '1938-10-01', '1953-03-01', 'Royaume-Uni', NULL, 11461, 1, 'https://upload.wikimedia.org/wikipedia/commons/6/62/Vickers_Wellington.jpg', 'Photographer not identified, so UK Copyright contended to have lapsed 50 years after publication.', 'Public domain', NULL, 'https://commons.wikimedia.org/wiki/File:Vickers_Wellington.jpg', 'Q850244', 'Vickers Wellington', ARRAY['vickers wellington', 'wellington bomber', 'wellington'], 'https://fr.wikipedia.org/wiki/Vickers_Wellington', '{}'::jsonb, true),
  -- Heinkel He 178 (Q161540)
  ('heinkel-he-178', 'Heinkel He 178', 'Heinkel', 'collection', 'Le Heinkel He 178 est le premier avion à turboréacteur de l''histoire aéronautique, conçu dans l''entre-deux-guerres par la société allemande Heinkel. Il vola pour la première fois à l''été 1939, juste avant le début de la Seconde Guerre mondiale.', NULL, '1939-08-27', NULL, NULL, NULL, NULL, NULL, NULL, '1939-01-01', NULL, 'Reich allemand', NULL, 2, 5, 'https://thumb.wikimedia.org/wikipedia/commons/thumb/1/16/Heinkel_He_178_050602-F-1234P-002.jpg/1280px-Heinkel_He_178_050602-F-1234P-002.jpg', 'Heinkel', 'Public domain', NULL, 'https://commons.wikimedia.org/wiki/File:Heinkel_He_178_050602-F-1234P-002.jpg', 'Q161540', 'Heinkel He 178', ARRAY['heinkel he 178', 'he 178'], 'https://fr.wikipedia.org/wiki/Heinkel_He_178', '{}'::jsonb, true),
  -- Comac C919 (Q429894)
  ('comac-c919', 'Comac C919', 'Commercial Aircraft Corporation of China', 'ligne', 'Le Comac C919 est un avion de ligne biréacteur moyen-courrier construit depuis 2015 par l''avionneur chinois Comac. Le C919 a une capacité de 168 à 190 sièges, dont le premier vol a eu lieu le 5 mai 2017 et le premier vol commercial en mai 2023. À la fin de l''année 2019, les six prototypes de tests prévus ont été construits, avec alors pour objectif une certification et une mise en service en 2021, début 2022. La certification est finalement obtenue en septembre 2022.', NULL, '2017-05-05', NULL, NULL, 33.6, NULL, NULL, 12100, '2022-01-01', NULL, 'République populaire de Chine', NULL, 30, 5, 'https://upload.wikimedia.org/wikipedia/commons/8/8b/COMAC_B-001A_May_2017.jpg', 'Weimeng at www.airliners.net', 'CC BY-SA 4.0', 'https://creativecommons.org/licenses/by-sa/4.0', 'https://commons.wikimedia.org/wiki/File:COMAC_B-001A_May_2017.jpg', 'Q429894', 'Comac C919', ARRAY['comac c919', 'c919', 'comac-c9-19', '中国商飞-中-919'], 'https://fr.wikipedia.org/wiki/Comac_C919', '{"first_flight":["https://www.flightglobal.com/news/articles/comac-c919-lands-after-uneventful-maiden-sortie-436913/"],"units_built":["http://rzjets.net/aircraft/?typeid=358"]}'::jsonb, true),
  -- Sud-Aviation SE 210 Caravelle (Q6503)
  ('sud-aviation-caravelle', 'Sud-Aviation SE 210 Caravelle', 'Sud-Aviation', 'collection', 'Le Sud-Aviation SE 210 Caravelle est un avion de ligne biréacteur, destiné aux liaisons court et moyen-courriers, produit entre 1958 et 1973 par la société française Sud-Aviation, qui devient Aérospatiale en 1970. Premier avion à réaction court-courrier au monde, la Caravelle présente la caractéristique, innovante pour l''époque, d''avoir les moteurs placés à l''arrière du fuselage et non dans les ailes comme pour le Comet, ou dans des nacelles subalaires comme c''est le cas pour le Boeing 707.', NULL, '1955-05-27', NULL, NULL, 34.3, NULL, NULL, NULL, '1959-01-01', '2005-01-01', 'France', NULL, 282, 4, 'https://thumb.wikimedia.org/wikipedia/commons/thumb/0/00/HB-ICZ_Swissair_Caravelle.jpg/1280px-HB-ICZ_Swissair_Caravelle.jpg', 'Swissair Photo AG', 'CC BY-SA 4.0', 'https://creativecommons.org/licenses/by-sa/4.0', 'https://commons.wikimedia.org/wiki/File:HB-ICZ_Swissair_Caravelle.jpg', 'Q6503', 'Sud Aviation Caravelle', ARRAY['sud aviation caravelle', 'sud-aviation se 210 caravelle', 'sud aviation se 210 caravelle', 'se 210 caravelle', 'se210', 'sud caravelle', 'aerospatiale se 210 caravelle', 'aerospatiale caravelle', 'sud-aviation caravelle'], 'https://fr.wikipedia.org/wiki/Sud-Aviation_SE_210_Caravelle', '{"first_flight":["https://www.wikidata.org/wiki/Q28975923"]}'::jsonb, true),
  -- Grumman A-6 Intruder (Q332809)
  ('grumman-a-6-intruder', 'Grumman A-6 Intruder', 'Grumman', 'militaire', 'Le Grumman A-6 Intruder est un avion d''attaque au sol américain embarqué à bord de porte-avions, mis en service au début des années 1960. Largement utilisé pendant la guerre du Vietnam, il est capable d''emporter une lourde charge sur une grande distance et de frapper avec précision de jour comme de nuit, quelles que soient les conditions météorologiques. Il a été conçu pour remplacer le Douglas A-1 Skyraider.', NULL, '1960-04-19', NULL, 16.6, 16.2, 4.75, 5222, 12400, '1963-01-01', '1997-01-01', 'États-Unis', 'J52', 793, 3, 'https://thumb.wikimedia.org/wikipedia/commons/thumb/c/c3/Grumman_KA-6D_Intruder_of_VA-34_in_flight%2C_in_1988.jpg/1280px-Grumman_KA-6D_Intruder_of_VA-34_in_flight%2C_in_1988.jpg', 'U.S. Navy', 'Public domain', NULL, 'https://commons.wikimedia.org/wiki/File:Grumman_KA-6D_Intruder_of_VA-34_in_flight,_in_1988.jpg', 'Q332809', 'Grumman A-6 Intruder', ARRAY['grumman a-6 intruder', 'grumman a2f intruder', 'g-128', 'a-6', 'grumman intruder', 'grumman g-128 intruder', 'grumman a-6', 'grumman g-128', 'g-128 intruder', 'grumman a2f', 'intruder', 'a2f', 'a2f intruder', '"intruder"', 'a-6 intruder'], 'https://fr.wikipedia.org/wiki/Grumman_A-6_Intruder', '{}'::jsonb, true),
  -- Aichi D3A (Q403668)
  ('aichi-d3a', 'Aichi D3A', 'Aichi Kokuki', 'collection', 'L''Aichi D3A, ou « Bombardier embarqué de Marine Type 99 » (en japonais : « 99式艦上爆撃機 »), est un bombardier en piqué biplace en tandem japonais, en service de 1940 à 1945, pendant la Seconde Guerre mondiale. Dénommé Val par le code des Alliés du Pacifique, il fut le premier avion japonais à bombarder des objectifs américains, et aussi celui qui parvint à couler la plus grande quantité de navires de combat alliés.', NULL, '1938-01-01', NULL, 10.2, 14.37, 3.8, NULL, NULL, '1940-01-01', '1945-01-01', 'empire du Japon', 'Mitsubishi Kinsei', 1495, 3, 'https://thumb.wikimedia.org/wikipedia/commons/thumb/4/45/Aichi_D3A_Replica_Airshow.jpg/1280px-Aichi_D3A_Replica_Airshow.jpg', '"TMWolf"', 'CC BY-SA 2.0', 'https://creativecommons.org/licenses/by-sa/2.0', 'https://commons.wikimedia.org/wiki/File:Aichi_D3A_Replica_Airshow.jpg', 'Q403668', 'Aichi D3A', ARRAY['aichi d3a', 'aichi carrier bomber type 3', 'aichi type 99 carrier bomber', 'navy type 99 carrier bomber', 'val', 'd3a', 'nakajima d3n', 'yokosuka d3y', 'aichi d3a1', 'bombardier val'], 'https://fr.wikipedia.org/wiki/Aichi_D3A', '{}'::jsonb, true),
  -- Yakovlev Yak-3 (Q248348)
  ('yakovlev-yak-3', 'Yakovlev Yak-3', 'Saratov Aviation Plant / Tbilisi Aircraft Manufacturing', 'collection', 'Le Yak-3 (en russe : Як-3) est un avion de chasse monoplace soviétique de la Seconde Guerre mondiale. Cet avion a été réservé aux unités d''élite des Forces aériennes soviétiques. Appareil redoutablement efficace, l''as de la seconde guerre mondiale Marcel Albert qui le pilota au sein du régiment Normandie-Niémen le considérait comme largement supérieur au P-51 Mustang et au Spitfire.', NULL, '1943-04-01', NULL, 8.49, 9.2, 2.38, 648, 10700, '1944-04-01', '1952-01-01', 'Union soviétique', 'Klimov M-105', 4848, 2, 'https://thumb.wikimedia.org/wikipedia/commons/thumb/b/b3/CF15_Yak-3_ZK-VVS_040415_01.jpg/1280px-CF15_Yak-3_ZK-VVS_040415_01.jpg', 'Oren Rozen', 'CC BY-SA 3.0', 'https://creativecommons.org/licenses/by-sa/3.0', 'https://commons.wikimedia.org/wiki/File:CF15_Yak-3_ZK-VVS_040415_01.jpg', 'Q248348', 'Yakovlev Yak-3', ARRAY['yakovlev yak-3', 'yak-3'], 'https://fr.wikipedia.org/wiki/Yakovlev_Yak-3', '{}'::jsonb, true),
  -- Saab 37 Viggen (Q263786)
  ('saab-37-viggen', 'Saab 37 Viggen', 'Saab', 'militaire', 'Le Saab 37 Viggen (Tonnerre, en suédois) est un avion de combat conçu et construit par la Suède dans les années 1960, et dont la première variante a été mise en service le 21 juin 1971. Il se caractérise par une aile delta, des plans canards, et un système d''inversion de poussée permettant des atterrissages courts.', NULL, '1967-02-08', NULL, 16.3, 10.6, NULL, NULL, NULL, '1972-01-01', '2007-01-01', NULL, 'Pratt & Whitney JT8D', 330, 4, 'https://upload.wikimedia.org/wikipedia/commons/6/69/SAAB_J-37_Viggen_special_red_version.jpg', 'Mangan2002', 'CC BY 2.5', 'https://creativecommons.org/licenses/by/2.5', 'https://commons.wikimedia.org/wiki/File:SAAB_J-37_Viggen_special_red_version.jpg', 'Q263786', 'Saab 37 Viggen', ARRAY['saab 37 viggen', 'saab 37', 'saab j 37', 'j37', 'viggen fighter', 'viggen aircraft', 'viggen', 'saab viggen'], 'https://fr.wikipedia.org/wiki/Saab_37_Viggen', '{"length_m":["https://www.wikidata.org/wiki/Q29042798"],"wingspan_m":["https://www.wikidata.org/wiki/Q29042798"],"units_built":["http://www.x-plane.org/home/urf/aviation/aircraft.html"]}'::jsonb, true),
  -- Hawker Hunter (Q641943)
  ('hawker-hunter', 'Hawker Hunter', 'Hawker-Siddeley', 'militaire', 'Le Hawker Hunter est un avion de chasse britannique capable de vol supersonique en léger piqué. Il a fait son premier vol en 1951 et a été construit au total à près de 2 000 exemplaires, utilisés par une vingtaine de pays jusqu''à la fin des années 1990. Fort apprécié des pilotes, le Hunter affichait de bonnes performances pour l''époque en étant à la fois rapide, très manœuvrable et robuste.', NULL, '1951-07-21', NULL, 13.98, 10.26, 4.26, NULL, 15088, '1956-01-01', NULL, 'Royaume-Uni', NULL, 1972, 3, 'https://thumb.wikimedia.org/wikipedia/commons/thumb/9/93/Hawker_hunter_ag1.jpg/1280px-Hawker_hunter_ag1.jpg', 'Arnaud Gaillard (Greatpatton at French Wikipedia), arnaud () amarys . com', 'CC BY-SA 2.5', 'https://creativecommons.org/licenses/by-sa/2.5', 'https://commons.wikimedia.org/wiki/File:Hawker_hunter_ag1.jpg', 'Q641943', 'Hawker Hunter', ARRAY['hunter', 'hawker hunter', 'hunter aircraft', 'bae hunter', 'hunter fighter'], 'https://fr.wikipedia.org/wiki/Hawker_Hunter', '{"length_m":["https://www.wikidata.org/wiki/Q29042798"],"wingspan_m":["https://www.wikidata.org/wiki/Q29042798"]}'::jsonb, true),
  -- Fairey Swordfish (Q674079)
  ('fairey-swordfish', 'Fairey Swordfish', 'Fairey Aviation Company / Blackburn Aircraft', 'collection', 'Le Fairey Swordfish est un avion militaire embarqué britannique des années 1930-1940, fabriqué au départ à titre privé sous la dénomination TSR 1 par Fairey, et approuvé par les autorités en raison du succès des essais de catapultage depuis de grandes unités de la Royal Navy, en particulier le HMS Repulse. Le mot anglais swordfish signifie en français « espadon ». Cet appareil est surnommé durant sa carrière Stringbag (« filet à provisions ») par les aviateurs britanniques.', NULL, '1934-04-17', NULL, NULL, NULL, NULL, NULL, NULL, '1936-01-01', '1945-05-21', 'Royaume-Uni', 'Bristol Pegasus', 2396, 2, 'https://upload.wikimedia.org/wikipedia/commons/7/79/Fairey_Swordfish_on_Airfield.jpg', 'Mr. Peter Noble from UK Flying Displays and Museums', 'CC BY-SA 3.0', 'http://creativecommons.org/licenses/by-sa/3.0/', 'https://commons.wikimedia.org/wiki/File:Fairey_Swordfish_on_Airfield.jpg', 'Q674079', 'Fairey Swordfish', ARRAY['fairey swordfish', 'swordfish'], 'https://fr.wikipedia.org/wiki/Fairey_Swordfish', '{}'::jsonb, true),
  -- Dassault Mirage IV (Q754180)
  ('dassault-mirage-iv', 'Dassault Mirage IV', 'Dassault Aviation', 'collection', 'Le Mirage IV est un bombardier stratégique français dont les études ont débuté au milieu des années 1950. Entré en service en 1964, il fut le premier vecteur de la « triade » de la dissuasion nucléaire française. Sa carrière a duré plus de 40 ans (retrait du service en juin 2005), dont les dix dernières années sont uniquement consacrées à des missions de reconnaissance.', NULL, '1959-06-17', NULL, 23.5, 11.85, NULL, NULL, NULL, '1964-10-01', '1996-01-01', 'France', 'Atar', 66, 4, 'https://thumb.wikimedia.org/wikipedia/commons/thumb/9/95/Mirage_IV_DN-ST-87-02585.JPEG/1280px-Mirage_IV_DN-ST-87-02585.JPEG', 'PH2 Ron Ambroseno, USN', 'Public domain', NULL, 'https://commons.wikimedia.org/wiki/File:Mirage_IV_DN-ST-87-02585.JPEG', 'Q754180', 'Dassault Mirage IV', ARRAY['mirage iv', 'dassault mirage iv', 'mirage 4', 'dassault-breguet mirage iv'], 'https://fr.wikipedia.org/wiki/Dassault_Mirage_IV', '{"length_m":["https://www.wikidata.org/wiki/Q29042798"],"wingspan_m":["https://www.wikidata.org/wiki/Q29042798"]}'::jsonb, true),
  -- Gladiator (Q850179)
  ('gloster-gladiator', 'Gladiator', 'Gloster Aircraft Company', 'collection', '37) est un avion de chasse biplan britannique de l''entre-deux-guerres. Il fut utilisé par la Royal Air Force (RAF) et la Fleet Air Arm (FAA) (version Sea Gladiator) et fut exporté dans de nombreuses forces armées fin des années 1930. Ce fut le dernier chasseur biplan de la RAF. Bien que souvent opposé à des ennemis plus redoutables au cours des premiers jours de la Seconde Guerre mondiale, il s''acquitta assez bien des combats.', NULL, '1934-09-12', NULL, NULL, NULL, NULL, NULL, NULL, '1937-01-01', '1953-01-01', 'Royaume-Uni', 'Bristol Mercury', 747, 3, 'https://upload.wikimedia.org/wikipedia/commons/5/59/Gloster_Gladiator_3_ExCC.jpg', NULL, 'Public domain', NULL, 'https://commons.wikimedia.org/wiki/File:Gloster_Gladiator_3_ExCC.jpg', 'Q850179', 'Gloster Gladiator', ARRAY['gloster gladiator', 'gladiator', 'gloster ss.37', 'ss.37', 'ss37', 'gladiator fighter', 'gladiator aircraft'], 'https://fr.wikipedia.org/wiki/Gloster_Gladiator', '{}'::jsonb, true),
  -- Convair B-36 Peacemaker (Q332657)
  ('convair-b-36-peacemaker', 'Convair B-36 Peacemaker', 'Convair', 'collection', 'Le Convair B-36 Peacemaker est un bombardier stratégique lourd à long rayon d''action utilisé par l''United States Air Force entre 1949 et 1959. Le B-36 est conçu et développé dans les années 1940 par la Consolidated Aircraft Corporation, qui fusionnera avec Vultee pour donner Convair. Avec une envergure de plus de 70 mètres et une masse maximale au décollage de plus de 140 tonnes pour les premières versions, le B-36 est le plus grand avion à moteurs à pistons à avoir été produit en série.', NULL, '1946-08-08', NULL, NULL, NULL, NULL, NULL, NULL, '1949-01-01', '1959-01-01', 'États-Unis', 'R-4360 Wasp Major / General Electric J47', 384, 4, 'https://upload.wikimedia.org/wikipedia/commons/5/5a/Convair_B-36_Peacemaker.jpg', 'U.S. Air Force photo', 'Public domain', NULL, 'https://commons.wikimedia.org/wiki/File:Convair_B-36_Peacemaker.jpg', 'Q332657', 'Convair B-36 Peacemaker', ARRAY['b-36 peacemaker', 'convair b-36 peacemaker', 'b-36', 'convair b-36', 'boeing b-36'], 'https://fr.wikipedia.org/wiki/Convair_B-36_Peacemaker', '{}'::jsonb, true),
  -- Soukhoï Su-37 (Q459133)
  ('sukhoi-su-37', 'Soukhoï Su-37', 'Soukhoï / Komsomolsk-on-Amur Aircraft Production Association', 'militaire', 'Le Soukhoï Su-37 (Code OTAN Flanker-F) est un démonstrateur d''avion de chasse russe. Il est la version à poussée vectorielle et le onzième prototype de la série des Su-27M (T-10M dans la dénomination constructeur). Les Su-27M étant une série de prototypes développée par Sukhoï à partir des années 1980. Le premier prototype vola en 1988.', NULL, '1996-04-02', NULL, 21.93, 14.7, 5.93, 3300, NULL, NULL, NULL, NULL, 'Saturn AL-31', 3, 5, 'https://upload.wikimedia.org/wikipedia/commons/f/f3/Sukhoi_Su-37_at_Farnborough_1996_airshow.jpg', 'Mike Freer', 'GFDL 1.2', 'http://www.gnu.org/licenses/old-licenses/fdl-1.2.html', 'https://commons.wikimedia.org/wiki/File:Sukhoi_Su-37_at_Farnborough_1996_airshow.jpg', 'Q459133', 'Sukhoi Su-37', ARRAY['sukhoi su-37', 'soukhoï su-37', 'su37', 'flanker-f', 'su-37', 'sukhoï su-37', 'soukhoi su-37'], 'https://fr.wikipedia.org/wiki/Soukho%C3%AF_Su-37', '{}'::jsonb, true),
  -- Airbus A318 (Q1784324)
  ('airbus-a318', 'Airbus A318', 'Airbus Commercial Aircraft', 'ligne', 'L''Airbus A318 est un avion de ligne biréacteur à fuselage étroit, appartenant à la famille A320, appareils conçus et produits par la société Airbus Commercial Aircraft. L''A318 est destiné aux vols courts et moyens-courriers, il peut transporter, selon l''autorisation de l''EASA, jusqu''à 136 passagers au maximum (mais 132 passagers d''après la configuration d''Airbus High Density) et sa distance franchissable maximale est de 5 700 km. Son assemblage final est réalisé à Hambourg en Allemagne.', NULL, '2002-01-15', NULL, NULL, 34.1, 12.56, NULL, NULL, NULL, NULL, 'Allemagne / France', NULL, 80, 4, 'https://thumb.wikimedia.org/wikipedia/commons/thumb/7/74/Air_France_Airbus_A318-111%3B_F-GUGI%40FRA%3B06.07.2011_603gt_%285915187832%29.jpg/1280px-Air_France_Airbus_A318-111%3B_F-GUGI%40FRA%3B06.07.2011_603gt_%285915187832%29.jpg', 'Aero Icarus from Zürich, Switzerland', 'CC BY-SA 2.0', 'https://creativecommons.org/licenses/by-sa/2.0', 'https://commons.wikimedia.org/wiki/File:Air_France_Airbus_A318-111;_F-GUGI@FRA;06.07.2011_603gt_(5915187832).jpg', 'Q1784324', 'Airbus A318', ARRAY['airbus a318', 'a318'], 'https://fr.wikipedia.org/wiki/Airbus_A318', '{}'::jsonb, true),
  -- Aero L-39 Albatros (Q155899)
  ('aero-l-39-albatros', 'Aero L-39 Albatros', 'Aero Vodochody', 'militaire', 'Le L-39 Albatros est un avion d''entraînement militaire construit par la firme tchécoslovaque Aero Vodochody, qui a succédé à l''Aero L-29 Delfin comme avion standard d''entraînement des forces du pacte de Varsovie mais il est surtout utilisé comme avion de combat dans les pays acquéreurs.', NULL, '1968-01-01', 730, 12.11, 9.11, 4.77, 1491, 11346, '1972-03-28', NULL, 'Tchécoslovaquie', 'AI-25TL', 2900, 2, 'https://upload.wikimedia.org/wikipedia/commons/a/ad/Aero_L-39_Albatros_Jet_Trainer.jpg', 'Md Shaifuzzaman Ayon', 'CC BY-SA 4.0', 'https://creativecommons.org/licenses/by-sa/4.0', 'https://commons.wikimedia.org/wiki/File:Aero_L-39_Albatros_Jet_Trainer.jpg', 'Q155899', 'Aero L-39 Albatros', ARRAY['aero l-39 albatros', 'albatros', 'aero l-39', 'l-39 albatros', 'aero l-139 albatros', 'aero l-59 super albatros', 'l39'], 'https://fr.wikipedia.org/wiki/Aero_L-39_Albatros', '{"first_flight":["https://www.wikidata.org/wiki/Q56645322"],"max_speed_kmh":["https://www.wikidata.org/wiki/Q56645322"],"length_m":["https://www.wikidata.org/wiki/Q29042798"],"wingspan_m":["https://www.wikidata.org/wiki/Q29042798"],"range_km":["https://www.wikidata.org/wiki/Q56645322"],"ceiling_m":["https://www.wikidata.org/wiki/Q56645322"]}'::jsonb, true),
  -- Fokker Dr.I (Q156753)
  ('fokker-dr-i', 'Fokker Dr.I', 'Fokker', 'collection', 'I (Dr de l''allemand Dreidecker, ce qui veut dire « trois ailes » ou « triplan ») est un avion de chasse de la Première Guerre mondiale construit par Anthony Fokker et utilisé par l''Allemagne en 1917 et 1918. Le plus connu fut celui du « Baron Rouge », Manfred von Richthofen. Ses trois ailes superposées permettent une portance adéquate tout en conservant une envergure limitée, ce qui assure à l''appareil une très bonne maniabilité.', NULL, '1917-07-05', 166, 5.77, 7.2, 2.95, 300, NULL, NULL, NULL, 'Empire allemand', 'Oberursel Ur.II', 320, 4, 'https://upload.wikimedia.org/wikipedia/commons/c/c4/Fok.Dr.I.jpg', NULL, 'Public domain', NULL, 'https://commons.wikimedia.org/wiki/File:Fok.Dr.I.jpg', 'Q156753', 'Fokker Dr.I', ARRAY['fokker dr.i', 'fokker dr.1', 'fokker triplan dr1', 'fokker dr.1 triplan', 'fokker dreidecker', 'dreidecker', 'fokker dr. i', 'dr.i', 'dr1'], 'https://fr.wikipedia.org/wiki/Fokker_Dr.I', '{"max_speed_kmh":["https://www.wikidata.org/wiki/Q15058267"],"length_m":["https://www.wikidata.org/wiki/Q15058267"],"wingspan_m":["https://www.wikidata.org/wiki/Q15058267"]}'::jsonb, true),
  -- Heinkel He 162 (Q156878)
  ('heinkel-he-162-volksjager', 'Heinkel He 162', 'Heinkel', 'collection', 'Le Heinkel He 162 Volksjäger ou Salamander était un avion de chasse intercepteur de la fin de la Seconde Guerre mondiale. Propulsé par un turboréacteur, il fut avec le Messerschmitt Me 262 biréacteur l''un des premiers avions de combat à réaction opérationnels de l''histoire.', NULL, '1944-12-06', NULL, NULL, NULL, NULL, NULL, NULL, NULL, '1945-05-01', 'Troisième Reich', 'BMW 003', 320, 4, 'https://upload.wikimedia.org/wikipedia/commons/c/c8/He162_color010.jpg', NULL, 'Public domain', NULL, 'https://commons.wikimedia.org/wiki/File:He162_color010.jpg', 'Q156878', 'Heinkel He 162 Volksjäger', ARRAY['heinkel he 162', 'heinkel he 162 volksjäger', 'salamander', 'spatz', 'sparrow', 'people''s fighter', 'volksjäger', 'he 162'], 'https://fr.wikipedia.org/wiki/Heinkel_He_162', '{}'::jsonb, true),
  -- Let L-410 Turbolet (Q157925)
  ('let-l-410-turbolet', 'Let L-410 Turbolet', 'Let Kunovice / Ural Works of Civil Aviation', 'ligne', 'Le LET L-410 Turbolet est un avion de transport biturbopropulseur non pressurisé de 19 places développé et construit par l''entreprise tchèque Let Kunovice.', NULL, '1969-04-16', NULL, 13.61, 17.48, NULL, NULL, 7000, '1971-01-01', NULL, 'Tchécoslovaquie', NULL, 1138, 3, 'https://upload.wikimedia.org/wikipedia/commons/a/a5/Let_L-410.jpg', 'The original uploader was Mottld at English Wikipedia.', 'Public domain', NULL, 'https://commons.wikimedia.org/wiki/File:Let_L-410.jpg', 'Q157925', 'Let L-410 Turbolet', ARRAY['let l-410 turbolet', 'turbolet', 'l410', 'let turbolet', 'l-410uvp-e', 'let 410', 'let l-410'], 'https://fr.wikipedia.org/wiki/Let_L-410_Turbolet', '{"length_m":["https://www.wikidata.org/wiki/Q29042798"],"wingspan_m":["https://www.wikidata.org/wiki/Q29042798"]}'::jsonb, true),
  -- De Havilland Vampire (Q179835)
  ('de-havilland-vampire', 'De Havilland Vampire', 'De Havilland Aircraft Company', 'collection', '100, est le second avion à réaction militaire construit par le Royaume-Uni, avec la société de Havilland. Mis en service juste après la Seconde Guerre mondiale, il présente la particularité d''être équipé d''un fuselage arrière bipoutre. C''est le premier avion à réaction à avoir traversé l''océan Atlantique, et le premier avion à réaction capable d''opérer depuis un porte-avions. Plus de 4 500 exemplaires ont été construits, dont une partie sous licence, et utilisés par environ 25 pays différents.', NULL, '1943-09-20', NULL, NULL, NULL, NULL, NULL, NULL, '1945-01-01', '1979-01-01', 'Royaume-Uni', NULL, 3268, 2, 'https://thumb.wikimedia.org/wikipedia/commons/thumb/6/62/Dh115.vampire.t11.june2004.arp.jpg/1280px-Dh115.vampire.t11.june2004.arp.jpg', 'Photographed by Adrian Pingstone and released into the the public domain.', 'Public domain', NULL, 'https://commons.wikimedia.org/wiki/File:Dh115.vampire.t11.june2004.arp.jpg', 'Q179835', 'De Havilland Vampire', ARRAY['de havilland vampire', 'dh.100', 'dh100', 'sea vampire', 'de havilland dh.100 vampire'], 'https://fr.wikipedia.org/wiki/De_Havilland_DH.100_Vampire', '{}'::jsonb, true),
  -- Grumman E-2 Hawkeye (Q223372)
  ('grumman-e-2-hawkeye', 'Grumman E-2 Hawkeye', 'Northrop Grumman Corporation / Grumman', 'militaire', 'Le Grumman E-2 Hawkeye est un avion de surveillance aérienne et de commandement aéroporté ou AWACS développé par le constructeur américain Grumman (absorbé dans Northrop Grumman depuis 1994) et initialement embarqué à bord des porte-avions de la marine américaine. Mis en service en 1964, il a depuis été exporté vers plusieurs pays.', NULL, '1960-10-21', NULL, 17.6, 24.56, 5.59, 2708, NULL, '1964-01-01', NULL, 'États-Unis', NULL, 200, 4, 'https://thumb.wikimedia.org/wikipedia/commons/thumb/3/37/Grumman_E-2C_Hawkeye_0014.jpg/1280px-Grumman_E-2C_Hawkeye_0014.jpg', 'Marcin Zieliński', 'CC BY 2.5', 'https://creativecommons.org/licenses/by/2.5', 'https://commons.wikimedia.org/wiki/File:Grumman_E-2C_Hawkeye_0014.jpg', 'Q223372', 'Grumman E-2 Hawkeye', ARRAY['grumman e-2 hawkeye', 'grumman w2f hawkeye', 'grumman 123', 'hawkeye awacs', 'g-123', 'w2f hawkeye', 'e-2 aircraft', 'grumman hawkeye', 'grumman model 123', 'hawkeye aircraft', 'northrop grumman e-2 hawkeye', 'hawkeye', 'e-2', 'grumman e-2', 'e-2 hawkeye', 'w2f', 'e2'], 'https://fr.wikipedia.org/wiki/Grumman_E-2_Hawkeye', '{"wingspan_m":["https://www.wikidata.org/wiki/Q29042798"]}'::jsonb, true),
  -- Douglas A-1 Skyraider (Q266066)
  ('douglas-a-1-skyraider', 'Douglas A-1 Skyraider', 'Douglas', 'collection', 'Le Douglas AD Skyraider, devenu A-1 Skyraider après la mise en place du système Tri-service en 1962, est un bombardier d''appui tactique monomoteur à pistons, l''un des derniers utilisés par des armées de l''air. En effet, il est sorti lorsque les premiers avions de combat à réaction entraient eux aussi en service. Il restait néanmoins très efficace. L''avion d''attaque léger Skyraider II est ainsi nommé en son hommage en 2024.', NULL, '1945-03-18', NULL, 11.84, 15.25, 4.78, NULL, NULL, '1946-12-01', '1985-01-01', 'États-Unis', 'R-3350 Duplex Cyclone', 3180, 2, 'https://upload.wikimedia.org/wikipedia/commons/c/c7/Douglas_AD-6_Skyraider_of_VA-65_in_flight_in_March_1958.jpg', 'Lt.Cdr. Jerry Tabrum, USN', 'Public domain', NULL, 'https://commons.wikimedia.org/wiki/File:Douglas_AD-6_Skyraider_of_VA-65_in_flight_in_March_1958.jpg', 'Q266066', 'Douglas A-1 Skyraider', ARRAY['douglas skyraider', 'douglas a-1 skyraider', '"skyraider"', 'spad', 'a-1 skyraider', 'douglas ad skyraider', 'douglas attack design 1', 'a-1', 'a1', 'ad skyraider', 'xbt2d skyraider', 'attack design 1', 'ad', 'douglas ad', 'skyraider', 'douglas a-1'], 'https://fr.wikipedia.org/wiki/Douglas_AD_Skyraider', '{}'::jsonb, true),
  -- Saab 340 (Q277491)
  ('saab-340', 'Saab 340', 'Saab', 'ligne', 'Le Saab 340 est un avion de ligne bimoteur à hélice, mu par deux turbopropulseurs, destiné à couvrir de courtes distances. Il a été produit par un partenariat entre Saab et Fairchild Aircraft. Après que cette dernière compagnie a cessé son activité, l''intégralité de la construction fut transférée à l''usine Saab de Linköping, en Suède.', NULL, '1983-01-25', 524, 19.73, 21.44, 6.97, 1350, NULL, '1984-06-06', NULL, 'Suède', 'CT7-5A', 459, 4, 'https://thumb.wikimedia.org/wikipedia/commons/thumb/d/d7/Estonian_Air_Saab_340A_ES-ASN.jpg/1280px-Estonian_Air_Saab_340A_ES-ASN.jpg', 'Paavo Pihelgas', 'CC BY 2.5', 'https://creativecommons.org/licenses/by/2.5', 'https://commons.wikimedia.org/wiki/File:Estonian_Air_Saab_340A_ES-ASN.jpg', 'Q277491', 'Saab 340', ARRAY['saab 340', 'sf340', 'tp 100'], 'https://fr.wikipedia.org/wiki/Saab_340', '{"first_flight":["https://www.wikidata.org/wiki/Q15053275"]}'::jsonb, true),
  -- T-50 Golden Eagle (Q482600)
  ('kai-t-50-golden-eagle', 'T-50 Golden Eagle', 'Korea Aerospace Industries', 'militaire', 'Le T-50 Golden Eagle (골든이글) est à la base dune famille de chasseurs supersoniques et d’avions d’entraînement avancés sud-coréens, conçue, développée et fabriquée par Korea Aerospace Industries (KAI) depuis la fin des années 1990. Le T-50 est le premier aéronef supersonique construit par la république de Corée qui a entrepris un effort de construction d’une aéronautique et d’une industrie de défense nationale.', NULL, '2002-08-20', NULL, 13.14, 9.45, 4.82, 1851, 14630, '2005-02-22', NULL, 'Corée du Sud', 'General Electric F404', 200, 4, 'https://thumb.wikimedia.org/wikipedia/commons/thumb/b/b1/T-50_Golden_Eagle_Demo_flight_%2812201663454%29.jpg/1280px-T-50_Golden_Eagle_Demo_flight_%2812201663454%29.jpg', 'Korea Aerospace Industries', 'CC BY 2.0', 'https://creativecommons.org/licenses/by/2.0', 'https://commons.wikimedia.org/wiki/File:T-50_Golden_Eagle_Demo_flight_(12201663454).jpg', 'Q482600', 'KAI T-50 Golden Eagle', ARRAY['korea aerospace industries t-50 golden eagle', 't-50 golden eagle', 'kai t-50 golden eagle', 'golden eagle', 't50 golden eagle', 'kai golden eagle', 'ktx-2'], 'https://fr.wikipedia.org/wiki/KAI_T-50_Golden_Eagle', '{}'::jsonb, true),
  -- Vought F-8 Crusader (Q502126)
  ('vought-f-8-crusader', 'Vought F-8 Crusader', 'Vought / Ling-Temco-Vought', 'collection', 'Le F-8 Crusader (initialement F8U) est un intercepteur supersonique construit par Vought aux États-Unis. Embarqué à bord de porte-avions, il se caractérise par une entrée d''air frontale et par une voilure à angle de calage variable. Malgré une charge supplémentaire due à son équipement naval, il affiche les mêmes performances que son homologue basé à terre, le North American F-100 Super Sabre.', NULL, '1955-03-25', NULL, 16.53, 10.87, 4.8, NULL, 11700, '1957-03-01', '1999-12-19', 'États-Unis', 'Pratt & Whitney J57', 1219, 3, 'https://thumb.wikimedia.org/wikipedia/commons/thumb/9/91/F8E_Launch-VF33-CVAN65-1964.jpg/1280px-F8E_Launch-VF33-CVAN65-1964.jpg', 'Casey17', 'CC BY-SA 3.0', 'https://creativecommons.org/licenses/by-sa/3.0', 'https://commons.wikimedia.org/wiki/File:F8E_Launch-VF33-CVAN65-1964.jpg', 'Q502126', 'Vought F-8 Crusader', ARRAY['vought f-8 crusader', 'f8u crusader', 'vought f8u crusader', 'rf-8 crusader', 'crusader', 'ltv f-8 crusader', 'vought crusader', 'vought f-8', 'f-8 crusader', 'f8 crusader', 'f8u'], 'https://fr.wikipedia.org/wiki/Vought_F-8_Crusader', '{}'::jsonb, true),
  -- AV-8B Harrier II (Q635687)
  ('mcdonnell-douglas-av-8b-harrier-ii', 'AV-8B Harrier II', 'McDonnell Douglas / BAE Systems', 'militaire', '5 (désignation anglaise) est la seconde génération du Hawker Siddeley Harrier, avion d''attaque au sol à décollage vertical. Son développement a été lancé à la fin des années 1970 par les États-Unis, rejoints rapidement par le Royaume-Uni, qui avait conçu la version initiale.', NULL, '1978-11-09', 667, 14.12, 9.25, 3.55, 3888, 11580, '1985-01-01', NULL, 'États-Unis', 'Rolls-Royce Pegasus', 337, 4, 'https://upload.wikimedia.org/wikipedia/commons/2/21/DM-SD-02-01334.jpg', 'Government of the United States', 'Public domain', NULL, 'https://commons.wikimedia.org/wiki/File:DM-SD-02-01334.jpg', 'Q635687', 'McDonnell Douglas AV-8B Harrier II', ARRAY['mcdonnell douglas av-8b harrier ii', 'av-8b harrier ii', 'av8b', 'harrier ii', 'mcdonnell douglas harrier ii', 'boeing av-8b harrier ii', 'boeing harrier ii', 'av-8b', 'av-8b harrier', 'av8 harrier ii', 'av-8 harrier ii', 'gr.3/av-8', 'bae harrier gr mk 5', 'harrier gr.5'], 'https://fr.wikipedia.org/wiki/McDonnell_Douglas_AV-8B_Harrier_II', '{"first_flight":["https://web.archive.org/web/20131223031751/http://www.flightglobal.com/pdfarchive/view/1978/1978%20-%202917.html"],"max_speed_kmh":["https://www.aviation.marines.mil/Portals/11/2018%20AvPlan%20.pdf"],"length_m":["https://books.google.com/books?id=wySzFUplegsC&pg=PA90&lpg=PA90","https://web.archive.org/web/20130917031046/http://www.boeing.com/boeing/history/mdc/harrier.page"],"wingspan_m":["https://books.google.com/books?id=wySzFUplegsC&pg=PA90&lpg=PA90","https://www.boeing.com/history/products/av-8-harrier-ii.page"],"height_m":["https://books.google.com/books?id=wySzFUplegsC&pg=PA90&lpg=PA90","https://www.boeing.com/history/products/av-8-harrier-ii.page"],"range_km":["https://www.boeing.com/history/products/av-8-harrier-ii.page"],"ceiling_m":["https://www.boeing.com/history/products/av-8-harrier-ii.page"],"service_entry":["https://books.google.com/books?id=wySzFUplegsC&pg=PA90&lpg=PA90"]}'::jsonb, true),
  -- BAe Hawk (Q687743)
  ('bae-systems-hawk', 'BAe Hawk', 'Hawker-Siddeley / British Aerospace', 'militaire', 'Le BAe Hawk est un avion militaire conçu par British Aerospace (devenu BAE Systems) au début des années 1970. Initialement destiné à l''entraînement, il en a été dérivé des versions aptes aux missions d''attaque au sol ou de défense aérienne. Au début des années 2000, environ 700 exemplaires du Hawk avaient été produits, dont une partie sous licence, et l''avion était utilisé par une quinzaine de pays.', NULL, '1974-08-21', NULL, 12.43, 9.94, 3.98, NULL, NULL, '1976-11-01', NULL, 'Royaume-Uni', NULL, 1000, 3, 'https://thumb.wikimedia.org/wikipedia/commons/thumb/b/be/Bae_hawk_t1_xx245_inflight_arp.jpg/1280px-Bae_hawk_t1_xx245_inflight_arp.jpg', 'Adrian Pingstone (Arpingstone)', 'Public domain', NULL, 'https://commons.wikimedia.org/wiki/File:Bae_hawk_t1_xx245_inflight_arp.jpg', 'Q687743', 'BAE Systems Hawk', ARRAY['bae systems hawk', 'bae hawk', 'british aerospace hawk', 'hawker siddeley hawk', 'sp117', 'hs.1182'], 'https://fr.wikipedia.org/wiki/BAe_Hawk', '{"units_built":["http://www.flightglobal.com/news/articles/farnborough-bae-close-to-selling-1000th-hawk-trainer-374394/","http://www.baesystems.com/product/BAES_019763/hawk-advanced-jet-trainer"],"service_entry":["https://web.archive.org/web/20100306052759/http://www.raf.mod.uk/equipment/hawk.cfm"]}'::jsonb, true)
